const AuthorizationSchema = z
  .object({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64' }),
    url: z.url(),
    scopes: z
      .array(z.string())
      .nullable()
      .openapi({ description: 'A list of scopes that this authorization is in.' }),
    token: z.string(),
    token_last_eight: z.string().nullable(),
    hashed_token: z.string().nullable(),
    app: z
      .object({ client_id: z.string(), name: z.string(), url: z.url() })
      .openapi({ required: ['client_id', 'name', 'url'] }),
    note: z.string().nullable(),
    note_url: z.url().nullable(),
    updated_at: z.iso.datetime({ offset: true }),
    created_at: z.iso.datetime({ offset: true }),
    fingerprint: z.string().nullable(),
    user: NullableSimpleUserSchema.exactOptional(),
    installation: NullableScopedInstallationSchema.exactOptional(),
    expires_at: z.iso.datetime({ offset: true }).nullable(),
  })
  .openapi({
    title: 'Authorization',
    description: 'The authorization for an OAuth app, GitHub App, or a Personal Access Token.',
    required: [
      'app',
      'id',
      'note',
      'note_url',
      'scopes',
      'token',
      'hashed_token',
      'token_last_eight',
      'fingerprint',
      'url',
      'created_at',
      'updated_at',
      'expires_at',
    ],
  })
  .openapi('Authorization')

