const DependabotAlertSecurityAdvisorySchema = z
  .strictObject({
    ghsa_id: z
      .string()
      .openapi({
        description: 'The unique GitHub Security Advisory ID assigned to the advisory.',
        readOnly: true,
      }),
    cve_id: z
      .string()
      .nullable()
      .openapi({ description: 'The unique CVE ID assigned to the advisory.', readOnly: true }),
    summary: z
      .string()
      .max(1024)
      .openapi({ description: 'A short, plain text summary of the advisory.', readOnly: true }),
    description: z
      .string()
      .openapi({
        description: 'A long-form Markdown-supported description of the advisory.',
        readOnly: true,
      }),
    vulnerabilities: z
      .array(DependabotAlertSecurityVulnerabilitySchema)
      .openapi({
        description: 'Vulnerable version range information for the advisory.',
        readOnly: true,
      }),
    severity: z
      .enum(['low', 'medium', 'high', 'critical'])
      .openapi({ description: 'The severity of the advisory.', readOnly: true }),
    classification: z
      .enum(['general', 'malware'])
      .exactOptional()
      .openapi({ description: 'The classification of the advisory.', readOnly: true }),
    cvss: z
      .strictObject({
        score: z
          .number()
          .min(0)
          .max(10)
          .openapi({ description: 'The overall CVSS score of the advisory.', readOnly: true }),
        vector_string: z
          .string()
          .nullable()
          .openapi({
            description: 'The full CVSS vector string for the advisory.',
            readOnly: true,
          }),
      })
      .openapi({
        description:
          'Details for the advisory pertaining to the Common Vulnerability Scoring System.',
        readOnly: true,
        required: ['score', 'vector_string'],
      }),
    cvss_severities: CvssSeveritiesSchema.exactOptional(),
    epss: SecurityAdvisoryEpssSchema.exactOptional(),
    cwes: z
      .array(
        z
          .strictObject({
            cwe_id: z.string().openapi({ description: 'The unique CWE ID.', readOnly: true }),
            name: z
              .string()
              .openapi({ description: 'The short, plain text name of the CWE.', readOnly: true }),
          })
          .openapi({
            description: 'A CWE weakness assigned to the advisory.',
            readOnly: true,
            required: ['cwe_id', 'name'],
          }),
      )
      .openapi({
        description: 'Details for the advisory pertaining to Common Weakness Enumeration.',
        readOnly: true,
      }),
    identifiers: z
      .array(
        z
          .strictObject({
            type: z
              .enum(['CVE', 'GHSA'])
              .openapi({ description: 'The type of advisory identifier.', readOnly: true }),
            value: z
              .string()
              .openapi({ description: 'The value of the advisory identifer.', readOnly: true }),
          })
          .openapi({
            description: 'An advisory identifier.',
            readOnly: true,
            required: ['value', 'type'],
          }),
      )
      .openapi({
        description: 'Values that identify this advisory among security information sources.',
        readOnly: true,
      }),
    references: z
      .array(
        z
          .strictObject({
            url: z.url().openapi({ description: 'The URL of the reference.', readOnly: true }),
          })
          .openapi({
            description: 'A link to additional advisory information.',
            readOnly: true,
            required: ['url'],
          }),
      )
      .openapi({ description: 'Links to additional advisory information.', readOnly: true }),
    published_at: z.iso
      .datetime({ offset: true })
      .openapi({
        description:
          'The time that the advisory was published in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ`.',
        readOnly: true,
      }),
    updated_at: z.iso
      .datetime({ offset: true })
      .openapi({
        description:
          'The time that the advisory was last modified in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ`.',
        readOnly: true,
      }),
    withdrawn_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({
        description:
          'The time that the advisory was withdrawn in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ`.',
        readOnly: true,
      }),
  })
  .openapi({
    description: 'Details for the GitHub Security Advisory.',
    readOnly: true,
    required: [
      'ghsa_id',
      'cve_id',
      'summary',
      'description',
      'vulnerabilities',
      'severity',
      'cvss',
      'cwes',
      'identifiers',
      'references',
      'published_at',
      'updated_at',
      'withdrawn_at',
    ],
    'x-github-breaking-changes': [
      {
        changeset: 'deprecate_cvss',
        patch: {
          properties: { cvss: null },
          required: [
            'ghsa_id',
            'cve_id',
            'summary',
            'description',
            'vulnerabilities',
            'severity',
            'cwes',
            'identifiers',
            'references',
            'published_at',
            'updated_at',
            'withdrawn_at',
          ],
        },
        version: '2026-03-10',
      },
    ],
  })
  .openapi('DependabotAlertSecurityAdvisory')

