const ArtifactDeploymentRecordSchema = z
  .object({
    id: z.int().exactOptional(),
    digest: z.string().exactOptional(),
    logical_environment: z.string().exactOptional(),
    physical_environment: z.string().exactOptional(),
    cluster: z.string().exactOptional(),
    deployment_name: z.string().exactOptional(),
    tags: z.record(z.string(), z.string()).exactOptional(),
    runtime_risks: z
      .array(
        z.enum(['critical-resource', 'internet-exposed', 'lateral-movement', 'sensitive-data']),
      )
      .max(4)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({ description: 'A list of runtime risks associated with the deployment.' }),
    created_at: z.string().exactOptional(),
    updated_at: z.string().exactOptional(),
    attestation_id: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'The ID of the provenance attestation associated with the deployment record.',
      }),
  })
  .openapi({
    title: 'Artifact Deployment Record',
    description: 'Artifact Metadata Deployment Record',
    required: [],
  })
  .openapi('ArtifactDeploymentRecord')

