const CodespaceSchema = z
  .object({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64', example: 1 }),
    name: z
      .string()
      .openapi({
        description: 'Automatically generated name of this codespace.',
        example: 'monalisa-octocat-hello-world-g4wpq6h95q',
      }),
    display_name: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Display name for this codespace.',
        example: 'bookish space pancake',
      }),
    environment_id: z
      .string()
      .nullable()
      .openapi({
        description: "UUID identifying this codespace's environment.",
        example: '26a7c758-7299-4a73-b978-5a92a7ae98a0',
      }),
    owner: SimpleUserSchema,
    billable_owner: SimpleUserSchema,
    repository: MinimalRepositorySchema,
    machine: NullableCodespaceMachineSchema,
    devcontainer_path: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Path to devcontainer.json from repo root used to create Codespace.',
        example: '.devcontainer/example/devcontainer.json',
      }),
    prebuild: z
      .boolean()
      .nullable()
      .openapi({
        description: 'Whether the codespace was created from a prebuild.',
        example: false,
      }),
    created_at: z.iso.datetime({ offset: true }).openapi({ example: '2011-01-26T19:01:12Z' }),
    updated_at: z.iso.datetime({ offset: true }).openapi({ example: '2011-01-26T19:01:12Z' }),
    last_used_at: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'Last known time this codespace was started.',
        example: '2011-01-26T19:01:12Z',
      }),
    state: z
      .enum([
        'Unknown',
        'Created',
        'Queued',
        'Provisioning',
        'Available',
        'Awaiting',
        'Unavailable',
        'Deleted',
        'Moved',
        'Shutdown',
        'Archived',
        'Starting',
        'ShuttingDown',
        'Failed',
        'Exporting',
        'Updating',
        'Rebuilding',
      ])
      .openapi({ description: 'State of this codespace.', example: 'Available' }),
    url: z.url().openapi({ description: 'API URL for this codespace.' }),
    git_status: z
      .object({
        ahead: z
          .int()
          .exactOptional()
          .openapi({
            description: 'The number of commits the local repository is ahead of the remote.',
            example: 0,
          }),
        behind: z
          .int()
          .exactOptional()
          .openapi({
            description: 'The number of commits the local repository is behind the remote.',
            example: 0,
          }),
        has_unpushed_changes: z
          .boolean()
          .exactOptional()
          .openapi({ description: 'Whether the local repository has unpushed changes.' }),
        has_uncommitted_changes: z
          .boolean()
          .exactOptional()
          .openapi({ description: 'Whether the local repository has uncommitted changes.' }),
        ref: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'The current branch (or SHA if in detached HEAD state) of the local repository.',
            example: 'main',
          }),
      })
      .openapi({ description: "Details about the codespace's git repository.", required: [] }),
    location: z
      .enum(['EastUs', 'SouthEastAsia', 'WestEurope', 'WestUs2'])
      .openapi({
        description: 'The initally assigned location of a new codespace.',
        example: 'WestUs2',
      }),
    idle_timeout_minutes: z
      .int()
      .nullable()
      .openapi({
        description:
          'The number of minutes of inactivity after which this codespace will be automatically stopped.',
        example: 60,
      }),
    web_url: z.url().openapi({ description: 'URL to access this codespace on the web.' }),
    machines_url: z
      .url()
      .openapi({
        description: 'API URL to access available alternate machine types for this codespace.',
      }),
    start_url: z.url().openapi({ description: 'API URL to start this codespace.' }),
    stop_url: z.url().openapi({ description: 'API URL to stop this codespace.' }),
    publish_url: z
      .url()
      .nullable()
      .exactOptional()
      .openapi({ description: 'API URL to publish this codespace to a new repository.' }),
    pulls_url: z
      .url()
      .nullable()
      .openapi({
        description: 'API URL for the Pull Request associated with this codespace, if any.',
      }),
    recent_folders: z.array(z.string()),
    runtime_constraints: z
      .object({
        allowed_port_privacy_settings: z
          .array(z.string())
          .nullable()
          .exactOptional()
          .openapi({
            description: 'The privacy settings a user can select from when forwarding a port.',
          }),
      })
      .exactOptional()
      .openapi({ required: [] }),
    pending_operation: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Whether or not a codespace has a pending async operation. This would mean that the codespace is temporarily unavailable. The only thing that you can do with a codespace in this state is delete it.',
      }),
    pending_operation_disabled_reason: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Text to show user when codespace is disabled by a pending operation',
      }),
    idle_timeout_notice: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Text to show user when codespace idle timeout minutes has been overriden by an organization policy',
      }),
    retention_period_minutes: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Duration in minutes after codespace has gone idle in which it will be deleted. Must be integer minutes between 0 and 43200 (30 days).',
        example: 60,
      }),
    retention_expires_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'When a codespace will be auto-deleted based on the "retention_period_minutes" and "last_used_at"',
        example: '2011-01-26T20:01:12Z',
      }),
    last_known_stop_notice: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The text to display to a user when a codespace has been stopped for a potentially actionable reason.',
        example: "you've used 100% of your spending limit for Codespaces",
      }),
  })
  .openapi({
    title: 'Codespace',
    description: 'A codespace.',
    required: [
      'id',
      'name',
      'environment_id',
      'owner',
      'billable_owner',
      'repository',
      'machine',
      'prebuild',
      'created_at',
      'updated_at',
      'last_used_at',
      'state',
      'url',
      'git_status',
      'location',
      'idle_timeout_minutes',
      'web_url',
      'machines_url',
      'start_url',
      'stop_url',
      'pulls_url',
      'recent_folders',
    ],
  })
  .openapi('Codespace')

