const RepositoryRuleMergeQueueSchema = z
  .object({
    type: z.literal('merge_queue'),
    parameters: z
      .object({
        check_response_timeout_minutes: z
          .int()
          .min(1)
          .max(360)
          .openapi({
            description:
              'Maximum time for a required status check to report a conclusion. After this much time has elapsed, checks that have not reported a conclusion will be assumed to have failed',
          }),
        grouping_strategy: z
          .enum(['ALLGREEN', 'HEADGREEN'])
          .openapi({
            description:
              'When set to ALLGREEN, the merge commit created by merge queue for each PR in the group must pass all required checks to merge. When set to HEADGREEN, only the commit at the head of the merge group, i.e. the commit containing changes from all of the PRs in the group, must pass its required checks to merge.',
          }),
        max_entries_to_build: z
          .int()
          .min(0)
          .max(100)
          .openapi({
            description:
              'Limit the number of queued pull requests requesting checks and workflow runs at the same time.',
          }),
        max_entries_to_merge: z
          .int()
          .min(0)
          .max(100)
          .openapi({
            description: 'The maximum number of PRs that will be merged together in a group.',
          }),
        merge_method: z
          .enum(['MERGE', 'SQUASH', 'REBASE'])
          .openapi({
            description: 'Method to use when merging changes from queued pull requests.',
          }),
        min_entries_to_merge: z
          .int()
          .min(0)
          .max(100)
          .openapi({
            description: 'The minimum number of PRs that will be merged together in a group.',
          }),
        min_entries_to_merge_wait_minutes: z
          .int()
          .min(0)
          .max(360)
          .openapi({
            description:
              'The time merge queue should wait after the first PR is added to the queue for the minimum group size to be met. After this time has elapsed, the minimum group size will be ignored and a smaller group will be merged.',
          }),
      })
      .exactOptional()
      .openapi({
        required: [
          'check_response_timeout_minutes',
          'grouping_strategy',
          'max_entries_to_build',
          'max_entries_to_merge',
          'merge_method',
          'min_entries_to_merge',
          'min_entries_to_merge_wait_minutes',
        ],
      }),
  })
  .openapi({
    title: 'merge_queue',
    description: 'Merges must be performed via a merge queue.',
    required: ['type'],
  })
  .openapi('RepositoryRuleMergeQueue')

