const SecretScanningCustomPatternToUpdateSchema = z
  .union([
    z
      .unknown()
      .superRefine((val, ctx) => {
        if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
          if (!Object.hasOwn(val, 'pattern')) {
            ctx.addIssue({ code: 'custom' })
          }
        }
      })
      .openapi({ required: ['pattern'] }),
    z
      .unknown()
      .superRefine((val, ctx) => {
        if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
          if (!Object.hasOwn(val, 'start_delimiter')) {
            ctx.addIssue({ code: 'custom' })
          }
        }
      })
      .openapi({ required: ['start_delimiter'] }),
    z
      .unknown()
      .superRefine((val, ctx) => {
        if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
          if (!Object.hasOwn(val, 'end_delimiter')) {
            ctx.addIssue({ code: 'custom' })
          }
        }
      })
      .openapi({ required: ['end_delimiter'] }),
    z
      .unknown()
      .superRefine((val, ctx) => {
        if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
          if (!Object.hasOwn(val, 'must_match')) {
            ctx.addIssue({ code: 'custom' })
          }
        }
      })
      .openapi({ required: ['must_match'] }),
    z
      .unknown()
      .superRefine((val, ctx) => {
        if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
          if (!Object.hasOwn(val, 'must_not_match')) {
            ctx.addIssue({ code: 'custom' })
          }
        }
      })
      .openapi({ required: ['must_not_match'] }),
  ])
  .and(
    z
      .object({
        pattern: z
          .string()
          .exactOptional()
          .openapi({ description: 'The updated regular expression of the custom pattern.' }),
        start_delimiter: z
          .string()
          .exactOptional()
          .openapi({ description: 'The updated start delimiter regex for the custom pattern.' }),
        end_delimiter: z
          .string()
          .exactOptional()
          .openapi({ description: 'The updated end delimiter regex for the custom pattern.' }),
        must_match: z
          .array(z.string())
          .exactOptional()
          .openapi({ description: 'Updated list of regexes that the secret must match.' }),
        must_not_match: z
          .array(z.string())
          .exactOptional()
          .openapi({ description: 'Updated list of regexes that the secret must not match.' }),
        custom_pattern_version: SecretScanningRowVersionSchema,
      })
      .openapi({ required: ['custom_pattern_version'] }),
  )
  .openapi({
    title: 'Secret Scanning Custom Pattern To Update',
    description:
      'Fields to update on a custom pattern. At least one updatable field (`pattern`, `start_delimiter`, `end_delimiter`, `must_match`, or `must_not_match`) must also be provided. Only provided fields will be updated.',
    required: ['custom_pattern_version'],
  })
  .openapi('SecretScanningCustomPatternToUpdate')

