const RepositoryAdvisorySchema = z
  .strictObject({
    ghsa_id: z
      .string()
      .openapi({ description: 'The GitHub Security Advisory ID.', readOnly: true }),
    cve_id: z
      .string()
      .nullable()
      .openapi({ description: 'The Common Vulnerabilities and Exposures (CVE) ID.' }),
    url: z.url().openapi({ description: 'The API URL for the advisory.', readOnly: true }),
    html_url: z.url().openapi({ description: 'The URL for the advisory.', readOnly: true }),
    summary: z.string().max(1024).openapi({ description: 'A short summary of the advisory.' }),
    description: z
      .string()
      .max(65535)
      .nullable()
      .openapi({ description: 'A detailed description of what the advisory entails.' }),
    severity: z
      .enum(['critical', 'high', 'medium', 'low'])
      .nullable()
      .openapi({ description: 'The severity of the advisory.' }),
    author: SimpleUserSchema.nullable().openapi({
      readOnly: true,
      description: 'The author of the advisory.',
    }),
    publisher: SimpleUserSchema.nullable().openapi({
      readOnly: true,
      description: 'The publisher of the advisory.',
    }),
    identifiers: z
      .array(
        z
          .object({
            type: z.enum(['CVE', 'GHSA']).openapi({ description: 'The type of identifier.' }),
            value: z.string().openapi({ description: 'The identifier value.' }),
          })
          .openapi({ required: ['type', 'value'] }),
      )
      .openapi({ readOnly: true }),
    state: z
      .enum(['published', 'closed', 'withdrawn', 'draft', 'triage'])
      .openapi({ description: 'The state of the advisory.' }),
    created_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({
        description: 'The date and time of when the advisory was created, in ISO 8601 format.',
        readOnly: true,
      }),
    updated_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({
        description: 'The date and time of when the advisory was last updated, in ISO 8601 format.',
        readOnly: true,
      }),
    published_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({
        description: 'The date and time of when the advisory was published, in ISO 8601 format.',
        readOnly: true,
      }),
    closed_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({
        description: 'The date and time of when the advisory was closed, in ISO 8601 format.',
        readOnly: true,
      }),
    withdrawn_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({
        description: 'The date and time of when the advisory was withdrawn, in ISO 8601 format.',
        readOnly: true,
      }),
    submission: z
      .object({
        accepted: z
          .boolean()
          .openapi({
            description:
              "Whether a private vulnerability report was accepted by the repository's administrators.",
            readOnly: true,
          }),
      })
      .nullable()
      .openapi({ readOnly: true, required: ['accepted'] }),
    vulnerabilities: z.array(RepositoryAdvisoryVulnerabilitySchema).nullable(),
    cvss: z
      .object({
        vector_string: z.string().nullable().openapi({ description: 'The CVSS vector.' }),
        score: z
          .number()
          .min(0)
          .max(10)
          .nullable()
          .openapi({ description: 'The CVSS score.', readOnly: true }),
      })
      .nullable()
      .openapi({ required: ['vector_string', 'score'] }),
    cvss_severities: CvssSeveritiesSchema.exactOptional(),
    cwes: z
      .array(
        z
          .object({
            cwe_id: z
              .string()
              .openapi({ description: 'The Common Weakness Enumeration (CWE) identifier.' }),
            name: z.string().openapi({ description: 'The name of the CWE.', readOnly: true }),
          })
          .openapi({ required: ['cwe_id', 'name'] }),
      )
      .nullable()
      .openapi({ readOnly: true }),
    cwe_ids: z.array(z.string()).nullable().openapi({ description: 'A list of only the CWE IDs.' }),
    credits: z
      .array(
        z
          .object({
            login: z
              .string()
              .exactOptional()
              .openapi({ description: 'The username of the user credited.' }),
            type: SecurityAdvisoryCreditTypesSchema.exactOptional(),
          })
          .openapi({ required: [] }),
      )
      .nullable(),
    credits_detailed: z
      .array(RepositoryAdvisoryCreditSchema)
      .nullable()
      .openapi({ readOnly: true }),
    collaborating_users: z
      .array(SimpleUserSchema)
      .nullable()
      .openapi({ description: 'A list of users that collaborate on the advisory.' }),
    collaborating_teams: z
      .array(TeamSchema)
      .nullable()
      .openapi({ description: 'A list of teams that collaborate on the advisory.' }),
    private_fork: SimpleRepositorySchema.nullable().openapi({
      readOnly: true,
      description:
        "A temporary private fork of the advisory's repository for collaborating on a fix.",
    }),
  })
  .openapi({
    description: 'A repository security advisory.',
    required: [
      'ghsa_id',
      'cve_id',
      'url',
      'html_url',
      'summary',
      'description',
      'severity',
      'author',
      'publisher',
      'identifiers',
      'state',
      'created_at',
      'updated_at',
      'published_at',
      'closed_at',
      'withdrawn_at',
      'submission',
      'vulnerabilities',
      'cvss',
      'cwes',
      'cwe_ids',
      'credits',
      'credits_detailed',
      'collaborating_users',
      'collaborating_teams',
      'private_fork',
    ],
    'x-github-breaking-changes': [
      {
        changeset: 'deprecate_cvss',
        patch: {
          properties: { cvss: null },
          required: [
            'ghsa_id',
            'cve_id',
            'url',
            'html_url',
            'summary',
            'description',
            'severity',
            'author',
            'publisher',
            'identifiers',
            'state',
            'created_at',
            'updated_at',
            'published_at',
            'closed_at',
            'withdrawn_at',
            'submission',
            'vulnerabilities',
            'cwes',
            'cwe_ids',
            'credits',
            'credits_detailed',
            'collaborating_users',
            'collaborating_teams',
            'private_fork',
          ],
        },
        version: '2026-03-10',
      },
    ],
  })
  .openapi('RepositoryAdvisory')

