const ConcurrencyGroupRunListSchema = z
  .object({
    total_count: z
      .int()
      .openapi({
        description:
          "The total number of concurrency groups this workflow run participates in,\nderived from the run's configuration. This count is not filtered by\nwhether the run currently holds or is waiting in each group, so it can\ninclude groups whose `group_members` array is empty (for example, when\nthe run has already released its lease in that group).",
      }),
    concurrency_groups: z.array(
      z
        .object({
          group_name: z.string().openapi({ description: 'The name of the concurrency group.' }),
          group_url: z
            .url()
            .openapi({
              description:
                'API URL for this concurrency group. May return 404 if the group\nhas no active items at the time it is requested, since the\nget-by-name endpoint reports the live repo-wide state of a group\nwhile this endpoint lists groups associated with a run by\nconfiguration.',
            }),
          group_members: z
            .array(
              z
                .object({
                  run_id: z.int().openapi({ description: 'The ID of the workflow run.' }),
                  run_name: z.string().openapi({ description: 'The name of the workflow run.' }),
                  run_url: z
                    .url()
                    .nullable()
                    .openapi({ description: 'API URL for the workflow run.' }),
                  run_html_url: z
                    .url()
                    .nullable()
                    .openapi({ description: 'Web URL for the workflow run.' }),
                  position: z
                    .int()
                    .openapi({
                      description:
                        'Queue position. 0 means the item holds the concurrency lease (in_progress), 1 or higher means queued (pending).',
                    }),
                  position_url: z
                    .url()
                    .openapi({
                      description:
                        'API URL to get items ahead of this item in the concurrency group.',
                    }),
                  job_id: z
                    .int()
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        'The ID of the job, when the item represents a job-level or reusable-workflow-level lease.',
                    }),
                  job_name: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        'The display name of the job, when the item represents a job-level or reusable-workflow-level lease.',
                    }),
                  job_url: z
                    .url()
                    .nullable()
                    .exactOptional()
                    .openapi({ description: 'API URL for the job.' }),
                  job_html_url: z
                    .url()
                    .nullable()
                    .exactOptional()
                    .openapi({ description: 'Web URL for the job.' }),
                  status: z.enum(['in_progress', 'pending']),
                })
                .openapi({
                  required: [
                    'run_id',
                    'run_name',
                    'run_url',
                    'run_html_url',
                    'status',
                    'position',
                    'position_url',
                  ],
                }),
            )
            .openapi({
              description:
                'Items belonging to this workflow run that are either currently holding or\nwaiting for the concurrency group lease. May be empty if the run no\nlonger has any active or queued items in this group.',
            }),
        })
        .openapi({ required: ['group_name', 'group_url', 'group_members'] }),
    ),
  })
  .openapi({
    title: 'Concurrency Group Run List',
    description: 'A list of concurrency groups associated with a workflow run.',
    required: ['total_count', 'concurrency_groups'],
  })
  .openapi('ConcurrencyGroupRunList')

