const CheckRunSchema = z
  .object({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The id of the check.',
        example: 21,
      }),
    head_sha: z
      .string()
      .openapi({
        description: 'The SHA of the commit that is being checked.',
        example: '009b8a3a9ccbb128af87f9b1c0f4c62e8a304f6d',
      }),
    node_id: z.string().openapi({ example: 'MDg6Q2hlY2tSdW40' }),
    external_id: z.string().nullable().openapi({ example: '42' }),
    url: z
      .string()
      .openapi({ example: 'https://api.github.com/repos/github/hello-world/check-runs/4' }),
    html_url: z
      .string()
      .nullable()
      .openapi({ example: 'https://github.com/github/hello-world/runs/4' }),
    details_url: z.string().nullable().openapi({ example: 'https://example.com' }),
    status: z
      .enum(['queued', 'in_progress', 'completed', 'waiting', 'requested', 'pending'])
      .openapi({
        description:
          'The phase of the lifecycle that the check is currently in. Statuses of waiting, requested, and pending are reserved for GitHub Actions check runs.',
        example: 'queued',
      }),
    conclusion: z
      .enum([
        'success',
        'failure',
        'neutral',
        'cancelled',
        'skipped',
        'timed_out',
        'action_required',
      ])
      .nullable()
      .openapi({ example: 'neutral' }),
    started_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({ example: '2018-05-04T01:14:52Z' }),
    completed_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({ example: '2018-05-04T01:14:52Z' }),
    output: z
      .object({
        title: z.string().nullable(),
        summary: z.string().nullable(),
        text: z.string().nullable(),
        annotations_count: z.int(),
        annotations_url: z.url(),
      })
      .openapi({ required: ['title', 'summary', 'text', 'annotations_count', 'annotations_url'] }),
    name: z.string().openapi({ description: 'The name of the check.', example: 'test-coverage' }),
    check_suite: z
      .object({ id: z.int() })
      .nullable()
      .openapi({ required: ['id'] }),
    app: NullableIntegrationSchema,
    pull_requests: z
      .array(PullRequestMinimalSchema)
      .openapi({
        description:
          'Pull requests that are open with a `head_sha` or `head_branch` that matches the check. The returned pull requests do not necessarily indicate pull requests that triggered the check.',
      }),
    deployment: DeploymentSimpleSchema.exactOptional(),
  })
  .openapi({
    title: 'CheckRun',
    description: 'A check performed on the code of a given code change',
    required: [
      'id',
      'node_id',
      'head_sha',
      'name',
      'url',
      'html_url',
      'details_url',
      'status',
      'conclusion',
      'started_at',
      'completed_at',
      'external_id',
      'check_suite',
      'output',
      'app',
      'pull_requests',
    ],
  })
  .openapi('CheckRun')

