const DependabotAlertSchema = z
  .strictObject({
    number: AlertNumberSchema,
    state: z
      .enum(['auto_dismissed', 'dismissed', 'fixed', 'open'])
      .openapi({ description: 'The state of the Dependabot alert.', readOnly: true }),
    dependency: z
      .object({
        package: DependabotAlertPackageSchema.exactOptional(),
        manifest_path: z
          .string()
          .exactOptional()
          .openapi({
            description:
              'The full path to the dependency manifest file, relative to the root of the repository.',
            readOnly: true,
          }),
        version_requirement: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The dependency version or version constraint last recorded for the dependency associated with this alert.\nFor dependencies detected from a lockfile, this can be the resolved version.\nFor manifest-only dependencies, it can be the declared version constraint. Returns `null` when unavailable.\n\nAn empty string can indicate an unconstrained dependency. The stored value is limited to 64 bytes;\nlonger requirements may have been truncated and may no longer form a complete, valid version constraint.\n\nWhen multiple vulnerable versions of a dependency correspond to the same alert, this field contains one\nrecorded version or constraint and may not represent all vulnerable versions.\n',
            readOnly: true,
          }),
        scope: z
          .enum(['development', 'runtime'])
          .nullable()
          .exactOptional()
          .openapi({
            description: 'The execution scope of the vulnerable dependency.',
            readOnly: true,
          }),
        relationship: z
          .enum(['unknown', 'direct', 'transitive', 'inconclusive'])
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The vulnerable dependency\'s relationship to your project.\n\n> [!NOTE]\n> We are rolling out support for dependency relationship across ecosystems. This value will be "unknown" for all dependencies in unsupported ecosystems.\n',
            readOnly: true,
          }),
      })
      .openapi({
        description: 'Details for the vulnerable dependency.',
        readOnly: true,
        required: [],
      }),
    security_advisory: DependabotAlertSecurityAdvisorySchema,
    security_vulnerability: DependabotAlertSecurityVulnerabilitySchema,
    url: AlertUrlSchema,
    html_url: AlertHtmlUrlSchema,
    created_at: AlertCreatedAtSchema,
    updated_at: AlertUpdatedAtSchema,
    dismissed_at: AlertDismissedAtSchema,
    dismissed_by: NullableSimpleUserSchema,
    dismissed_reason: z
      .enum(['fix_started', 'inaccurate', 'no_bandwidth', 'not_used', 'tolerable_risk'])
      .nullable()
      .openapi({ description: 'The reason that the alert was dismissed.' }),
    dismissed_comment: z
      .string()
      .max(280)
      .nullable()
      .openapi({ description: "An optional comment associated with the alert's dismissal." }),
    fixed_at: AlertFixedAtSchema,
    auto_dismissed_at: AlertAutoDismissedAtSchema.exactOptional(),
    dismissal_request: DependabotAlertDismissalRequestSimpleSchema.exactOptional(),
    assignees: z
      .array(SimpleUserSchema)
      .exactOptional()
      .openapi({ description: 'The users assigned to this alert.', readOnly: true }),
  })
  .openapi({
    description: 'A Dependabot alert.',
    required: [
      'number',
      'state',
      'dependency',
      'security_advisory',
      'security_vulnerability',
      'url',
      'html_url',
      'created_at',
      'updated_at',
      'dismissed_at',
      'dismissed_by',
      'dismissed_reason',
      'dismissed_comment',
      'fixed_at',
    ],
  })
  .openapi('DependabotAlert')

