const EnvironmentSchema = z
  .object({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The id of the environment.',
        example: 56780428,
      }),
    node_id: z.string().openapi({ example: 'MDExOkVudmlyb25tZW50NTY3ODA0Mjg=' }),
    name: z.string().openapi({ description: 'The name of the environment.', example: 'staging' }),
    url: z
      .string()
      .openapi({ example: 'https://api.github.com/repos/github/hello-world/environments/staging' }),
    html_url: z
      .string()
      .openapi({
        example:
          'https://github.com/github/hello-world/deployments/activity_log?environments_filter=staging',
      }),
    created_at: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'The time that the environment was created, in ISO 8601 format.',
        example: '2020-11-23T22:00:40Z',
      }),
    updated_at: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'The time that the environment was last updated, in ISO 8601 format.',
        example: '2020-11-23T22:00:40Z',
      }),
    protection_rules: z
      .array(
        z.union([
          z
            .object({
              id: z.int().openapi({ example: 3515 }),
              node_id: z.string().openapi({ example: 'MDQ6R2F0ZTM1MTU=' }),
              type: z.string().openapi({ example: 'wait_timer' }),
              wait_timer: WaitTimerSchema.exactOptional(),
            })
            .openapi({ required: ['id', 'node_id', 'type'] }),
          z
            .object({
              id: z.int().openapi({ example: 3755 }),
              node_id: z.string().openapi({ example: 'MDQ6R2F0ZTM3NTU=' }),
              prevent_self_review: z
                .boolean()
                .exactOptional()
                .openapi({
                  example: false,
                  description:
                    'Whether deployments to this environment can be approved by the user who created the deployment.',
                }),
              type: z.string().openapi({ example: 'required_reviewers' }),
              reviewers: z
                .array(
                  z
                    .object({
                      type: DeploymentReviewerTypeSchema.exactOptional(),
                      reviewer: z.union([SimpleUserSchema, TeamSchema]).exactOptional(),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'The people or teams that may approve jobs that reference the environment. You can list up to six users or teams as reviewers. The reviewers must have at least read access to the repository. Only one of the required reviewers needs to approve the job for it to proceed.',
                }),
            })
            .openapi({ required: ['id', 'node_id', 'type'] }),
          z
            .object({
              id: z.int().openapi({ example: 3515 }),
              node_id: z.string().openapi({ example: 'MDQ6R2F0ZTM1MTU=' }),
              type: z.string().openapi({ example: 'branch_policy' }),
            })
            .openapi({ required: ['id', 'node_id', 'type'] }),
        ]),
      )
      .exactOptional()
      .openapi({ description: 'Built-in deployment protection rules for the environment.' }),
    deployment_branch_policy: DeploymentBranchPolicySettingsSchema.exactOptional(),
  })
  .openapi({
    title: 'Environment',
    description: 'Details of a deployment environment',
    required: ['id', 'node_id', 'name', 'url', 'html_url', 'created_at', 'updated_at'],
  })
  .openapi('Environment')

