const IssueSuggestionSchema = z
  .object({
    id: z.int().openapi({ description: 'The unique identifier of the suggestion.' }),
    issue_id: z
      .int()
      .openapi({ description: 'The unique identifier of the issue the suggestion applies to.' }),
    action: z
      .enum(['set_type', 'add_label', 'add_field', 'add_assignee', 'close_issue'])
      .openapi({ description: 'The kind of change proposed.' }),
    state: z
      .enum(['pending', 'applied', 'approved', 'dismissed', 'replaced', 'invalidated'])
      .openapi({ description: "The suggestion's lifecycle state." }),
    target_id: z
      .int()
      .nullable()
      .openapi({
        description:
          'The identifier of the target the change applies to (issue type, label, field, assignee, or duplicate issue), when applicable.',
      }),
    target_value: z
      .xor([z.string(), z.number(), z.boolean(), z.array(z.string())])
      .nullable()
      .openapi({
        description:
          'The proposed value, when applicable. An array for multi-select field suggestions.',
      }),
    rationale: z
      .string()
      .nullable()
      .openapi({ description: 'The rationale the actor provided for the suggestion.' }),
    confidence: z
      .enum(['LOW', 'MEDIUM', 'HIGH'])
      .nullable()
      .openapi({ description: "The actor's confidence level in the suggestion." }),
    actor_id: z
      .int()
      .nullable()
      .openapi({ description: 'The unique identifier of the actor that proposed the suggestion.' }),
    issue_event_id: z
      .int()
      .nullable()
      .openapi({
        description:
          'The identifier of the timeline event created when the suggestion was approved, when applicable.',
      }),
    resolved_by: z
      .int()
      .nullable()
      .openapi({
        description: 'The unique identifier of the user who approved or dismissed the suggestion.',
      }),
    created_at: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'The time the suggestion was created.' }),
    updated_at: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'The time the suggestion was last updated.' }),
  })
  .openapi({
    title: 'Issue Suggestion',
    description: 'An agent-proposed change to an issue that a maintainer can approve or dismiss.',
    required: [
      'id',
      'issue_id',
      'action',
      'state',
      'target_id',
      'target_value',
      'rationale',
      'confidence',
      'actor_id',
      'issue_event_id',
      'resolved_by',
      'created_at',
      'updated_at',
    ],
  })
  .openapi('IssueSuggestion')

