const PullRequestReviewCommentSchema = z
  .object({
    url: z
      .string()
      .openapi({
        description: 'URL for the pull request review comment',
        example: 'https://api.github.com/repos/octocat/Hello-World/pulls/comments/1',
      }),
    pull_request_review_id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .nullable()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        description: 'The ID of the pull request review to which the comment belongs.',
        example: 42,
      }),
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The ID of the pull request review comment.',
        example: 1,
      }),
    node_id: z
      .string()
      .openapi({
        description: 'The node ID of the pull request review comment.',
        example: 'MDI0OlB1bGxSZXF1ZXN0UmV2aWV3Q29tbWVudDEw',
      }),
    diff_hunk: z
      .string()
      .openapi({
        description: 'The diff of the line that the comment refers to.',
        example: '@@ -16,33 +16,40 @@ public class Connection : IConnection...',
      }),
    path: z
      .string()
      .openapi({
        description: 'The relative path of the file to which the comment applies.',
        example: 'config/database.yaml',
      }),
    position: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'The line index in the diff to which the comment applies. This field is closing down; use `line` instead.',
        example: 1,
      }),
    original_position: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'The index of the original line in the diff to which the comment applies. This field is closing down; use `original_line` instead.',
        example: 4,
      }),
    commit_id: z
      .string()
      .openapi({
        description: 'The SHA of the commit to which the comment applies.',
        example: '6dcb09b5b57875f334f61aebed695e2e4193db5e',
      }),
    original_commit_id: z
      .string()
      .openapi({
        description: 'The SHA of the original commit to which the comment applies.',
        example: '9c48853fa3dc5c1c3d6f1f1cd1f2743e72652840',
      }),
    in_reply_to_id: z
      .int()
      .exactOptional()
      .openapi({ description: 'The comment ID to reply to.', example: 8 }),
    user: NullableSimpleUserSchema,
    body: z
      .string()
      .openapi({
        description: 'The text of the comment.',
        example: 'We should probably include a check for null values here.',
      }),
    created_at: z.iso.datetime({ offset: true }).openapi({ example: '2011-04-14T16:00:49Z' }),
    updated_at: z.iso.datetime({ offset: true }).openapi({ example: '2011-04-14T16:00:49Z' }),
    html_url: z
      .url()
      .openapi({
        description: 'HTML URL for the pull request review comment.',
        example: 'https://github.com/octocat/Hello-World/pull/1#discussion-diff-1',
      }),
    pull_request_url: z
      .url()
      .openapi({
        description: 'URL for the pull request that the review comment belongs to.',
        example: 'https://api.github.com/repos/octocat/Hello-World/pulls/1',
      }),
    author_association: AuthorAssociationSchema,
    _links: z
      .object({
        self: z
          .object({
            href: z
              .url()
              .openapi({
                example: 'https://api.github.com/repos/octocat/Hello-World/pulls/comments/1',
              }),
          })
          .openapi({ required: ['href'] }),
        html: z
          .object({
            href: z
              .url()
              .openapi({
                example: 'https://github.com/octocat/Hello-World/pull/1#discussion-diff-1',
              }),
          })
          .openapi({ required: ['href'] }),
        pull_request: z
          .object({
            href: z
              .url()
              .openapi({ example: 'https://api.github.com/repos/octocat/Hello-World/pulls/1' }),
          })
          .openapi({ required: ['href'] }),
      })
      .openapi({ required: ['self', 'html', 'pull_request'] }),
    start_line: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'The first line of the range for a multi-line comment.',
        example: 2,
      }),
    original_start_line: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'The first line of the range for a multi-line comment.',
        example: 2,
      }),
    start_side: z
      .enum(['LEFT', 'RIGHT'])
      .nullable()
      .default('RIGHT')
      .exactOptional()
      .openapi({
        description: 'The side of the first line of the range for a multi-line comment.',
      }),
    line: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'The line of the blob to which the comment applies. The last line of the range for a multi-line comment',
        example: 2,
      }),
    original_line: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'The line of the blob to which the comment applies. The last line of the range for a multi-line comment',
        example: 2,
      }),
    side: z
      .enum(['LEFT', 'RIGHT'])
      .default('RIGHT')
      .exactOptional()
      .openapi({
        description:
          'The side of the diff to which the comment applies. The side of the last line of the range for a multi-line comment',
      }),
    subject_type: z
      .enum(['line', 'file'])
      .exactOptional()
      .openapi({
        description: 'The level at which the comment is targeted, can be a diff line or a file.',
      }),
    reactions: ReactionRollupSchema.exactOptional(),
    body_html: z.string().exactOptional().openapi({ example: '"<p>comment body</p>"' }),
    body_text: z.string().exactOptional().openapi({ example: '"comment body"' }),
  })
  .openapi({
    title: 'Pull Request Review Comment',
    description:
      "Pull Request Review Comments are comments on a portion of the Pull Request's diff.",
    required: [
      'url',
      'id',
      'node_id',
      'pull_request_review_id',
      'diff_hunk',
      'path',
      'commit_id',
      'original_commit_id',
      'user',
      'body',
      'created_at',
      'updated_at',
      'html_url',
      'pull_request_url',
      'author_association',
      '_links',
    ],
  })
  .openapi('PullRequestReviewComment')

