const PullRequestMergeResultSchema = z
  .object({ sha: z.string(), merged: z.boolean(), message: z.string() })
  .openapi({
    title: 'Pull Request Merge Result',
    description: 'Pull Request Merge Result',
    required: ['merged', 'message', 'sha'],
  })
  .openapi('PullRequestMergeResult')

const PullRequestMergeAsyncResultSchema = z
  .strictObject({
    status: z.enum(['pending', 'merged', 'enqueued', 'failed']),
    details: z.union([
      z
        .strictObject({
          message: z.string(),
          uuid: z.string(),
          merge_method: z.enum(['default', 'merge', 'squash', 'rebase']),
          merge_action: z.enum(['default', 'merge_queue', 'direct_merge']),
          expected_head_sha: z
            .string()
            .openapi({
              description:
                'SHA that the pull request head must match for the enqueued merge to proceed.',
            }),
          bypass_rules: z
            .boolean()
            .default(false)
            .exactOptional()
            .openapi({
              description:
                'Whether the asynchronous merge request will attempt to bypass repository rules that the authenticated actor is permitted to bypass.',
            }),
        })
        .openapi({
          description: 'When the asynchronous merge request is pending',
          required: ['message', 'uuid', 'merge_method', 'merge_action', 'expected_head_sha'],
        }),
      z
        .strictObject({ message: z.string() })
        .openapi({
          description: 'When the pull request is in a merge queue',
          required: ['message'],
        }),
      z
        .strictObject({ message: z.string() })
        .openapi({
          description: 'When the asynchronous merge request failed',
          required: ['message'],
        }),
      z
        .strictObject({ message: z.string(), sha: z.string() })
        .openapi({
          description: 'When the pull request has been merged',
          required: ['message', 'sha'],
        }),
    ]),
  })
  .openapi({
    title: 'Pull Request Merge Async Result',
    description: 'Pull Request Merge Async Result',
    required: ['status', 'details'],
  })
  .openapi('PullRequestMergeAsyncResult')

const PullRequestReviewRequestSchema = z
