const PullRequestReviewSchema = z
  .object({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'Unique identifier of the review',
        example: 42,
      }),
    node_id: z.string().openapi({ example: 'MDE3OlB1bGxSZXF1ZXN0UmV2aWV3ODA=' }),
    user: NullableSimpleUserSchema,
    body: z
      .string()
      .openapi({ description: 'The text of the review.', example: 'This looks great.' }),
    state: z.string().openapi({ example: 'CHANGES_REQUESTED' }),
    html_url: z
      .url()
      .openapi({ example: 'https://github.com/octocat/Hello-World/pull/12#pullrequestreview-80' }),
    pull_request_url: z
      .url()
      .openapi({ example: 'https://api.github.com/repos/octocat/Hello-World/pulls/12' }),
    _links: z
      .object({
        html: z.object({ href: z.string() }).openapi({ required: ['href'] }),
        pull_request: z.object({ href: z.string() }).openapi({ required: ['href'] }),
      })
      .openapi({ required: ['html', 'pull_request'] }),
    submitted_at: z.iso.datetime({ offset: true }).exactOptional(),
    commit_id: z
      .string()
      .nullable()
      .openapi({
        description:
          'A commit SHA for the review. If the commit object was garbage collected or forcibly deleted, then it no longer exists in Git and this value will be `null`.',
        example: '54bb654c9e6025347f57900a4a5c2313a96b8035',
      }),
    body_html: z.string().exactOptional(),
    body_text: z.string().exactOptional(),
    author_association: AuthorAssociationSchema,
  })
  .openapi({
    title: 'Pull Request Review',
    description: 'Pull Request Reviews are reviews on pull requests.',
    required: [
      'id',
      'node_id',
      'user',
      'body',
      'state',
      'commit_id',
      'html_url',
      'pull_request_url',
      '_links',
      'author_association',
    ],
  })
  .openapi('PullRequestReview')

