const SecretScanningAlertSchema = z
  .object({
    number: AlertNumberSchema.exactOptional(),
    created_at: AlertCreatedAtSchema.exactOptional(),
    updated_at: NullableAlertUpdatedAtSchema.exactOptional(),
    url: AlertUrlSchema.exactOptional(),
    html_url: AlertHtmlUrlSchema.exactOptional(),
    locations_url: z
      .url()
      .exactOptional()
      .openapi({ description: 'The REST API URL of the code locations for this alert.' }),
    state: SecretScanningAlertStateSchema.exactOptional(),
    resolution: SecretScanningAlertResolutionSchema.exactOptional(),
    resolved_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The time that the alert was resolved in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ`.',
      }),
    resolved_by: NullableSimpleUserSchema.exactOptional(),
    resolution_comment: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'An optional comment to resolve an alert.' }),
    secret_type: z
      .string()
      .exactOptional()
      .openapi({ description: 'The type of secret that secret scanning detected.' }),
    secret_type_display_name: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'User-friendly name for the detected secret, matching the `secret_type`.\nFor a list of built-in patterns, see "[Supported secret scanning patterns](https://docs.github.com/code-security/secret-scanning/introduction/supported-secret-scanning-patterns#supported-secrets)."',
      }),
    provider: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'The provider of the secret that was detected.' }),
    provider_slug: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The slug identifier for the provider of the secret that was detected. Use this value for filtering by provider with the `providers` or `exclude_providers` parameters.',
      }),
    secret: z.string().exactOptional().openapi({ description: 'The secret that was detected.' }),
    push_protection_bypassed: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Whether push protection was bypassed for the detected secret.' }),
    push_protection_bypassed_by: NullableSimpleUserSchema.exactOptional(),
    push_protection_bypassed_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The time that push protection was bypassed in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ`.',
      }),
    push_protection_bypass_request_reviewer: NullableSimpleUserSchema.exactOptional(),
    push_protection_bypass_request_reviewer_comment: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'An optional comment when reviewing a push protection bypass.' }),
    push_protection_bypass_request_comment: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'An optional comment when requesting a push protection bypass.' }),
    push_protection_bypass_request_html_url: z
      .url()
      .nullable()
      .exactOptional()
      .openapi({ description: 'The URL to a push protection bypass request.' }),
    validity: z
      .enum(['active', 'inactive', 'unknown'])
      .exactOptional()
      .openapi({ description: 'The token status as of the latest validity check.' }),
    publicly_leaked: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Whether the detected secret was publicly leaked.' }),
    multi_repo: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Whether the detected secret was found in multiple repositories under the same organization or enterprise.',
      }),
    is_base64_encoded: z
      .boolean()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'A boolean value representing whether or not alert is base64 encoded',
      }),
    first_location_detected: NullableSecretScanningFirstDetectedLocationSchema.exactOptional(),
    has_more_locations: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'A boolean value representing whether or not the token in the alert was detected in more than one location.',
      }),
    assigned_to: NullableSimpleUserSchema.exactOptional(),
    closure_request_comment: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'An optional comment from the closure request author.' }),
    closure_request_reviewer_comment: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'An optional comment from the closure request reviewer.' }),
    closure_request_reviewer: NullableSimpleUserSchema.exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('SecretScanningAlert')

