const GpgKeySchema = z
  .object({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64', example: 3 }),
    name: z.string().nullable().exactOptional().openapi({ example: "Octocat's GPG Key" }),
    primary_key_id: z.int().nullable(),
    key_id: z.string().openapi({ example: '3262EFF25BA0D270' }),
    public_key: z.string().openapi({ example: 'xsBNBFayYZ...' }),
    emails: z
      .array(
        z
          .object({ email: z.string().exactOptional(), verified: z.boolean().exactOptional() })
          .openapi({ required: [] }),
      )
      .openapi({ example: [{ email: 'octocat@users.noreply.github.com', verified: true }] }),
    subkeys: z
      .array(
        z
          .object({
            id: z
              .preprocess(
                (val) =>
                  typeof val === 'number' && Number.isSafeInteger(val)
                    ? BigInt(val)
                    : typeof val === 'string' && /^-?\d+$/.test(val)
                      ? BigInt(val)
                      : val,
                z.int64(),
              )
              .exactOptional()
              .openapi({ type: 'integer', format: 'int64' }),
            primary_key_id: z.int().exactOptional(),
            key_id: z.string().exactOptional(),
            public_key: z.string().exactOptional(),
            emails: z
              .array(
                z
                  .object({
                    email: z.string().exactOptional(),
                    verified: z.boolean().exactOptional(),
                  })
                  .openapi({ required: [] }),
              )
              .exactOptional(),
            subkeys: z.array(z.any()).exactOptional(),
            can_sign: z.boolean().exactOptional(),
            can_encrypt_comms: z.boolean().exactOptional(),
            can_encrypt_storage: z.boolean().exactOptional(),
            can_certify: z.boolean().exactOptional(),
            created_at: z.string().exactOptional(),
            expires_at: z.string().nullable().exactOptional(),
            raw_key: z.string().nullable().exactOptional(),
            revoked: z.boolean().exactOptional(),
          })
          .openapi({ required: [] }),
      )
      .openapi({
        example: [
          {
            id: 4,
            primary_key_id: 3,
            key_id: '4A595D4C72EE49C7',
            public_key: 'zsBNBFayYZ...',
            emails: [],
            can_sign: false,
            can_encrypt_comms: true,
            can_encrypt_storage: true,
            can_certify: false,
            created_at: '2016-03-24T11:31:04-06:00',
            expires_at: null,
            revoked: false,
          },
        ],
      }),
    can_sign: z.boolean().openapi({ example: true }),
    can_encrypt_comms: z.boolean(),
    can_encrypt_storage: z.boolean(),
    can_certify: z.boolean().openapi({ example: true }),
    created_at: z.iso.datetime({ offset: true }).openapi({ example: '2016-03-24T11:31:04-06:00' }),
    expires_at: z.iso.datetime({ offset: true }).nullable(),
    revoked: z.boolean().openapi({ example: true }),
    raw_key: z.string().nullable(),
  })
  .openapi({
    title: 'GPG Key',
    description: 'A unique encryption key',
    required: [
      'id',
      'primary_key_id',
      'key_id',
      'raw_key',
      'public_key',
      'created_at',
      'expires_at',
      'can_sign',
      'can_encrypt_comms',
      'can_encrypt_storage',
      'can_certify',
      'emails',
      'subkeys',
      'revoked',
    ],
  })
  .openapi('GpgKey')

