const DependabotAlertWithdrawnWebhookSchema = z
  .strictObject({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The unique identifier of the withdrawn alert.',
        readOnly: true,
      }),
    node_id: z
      .string()
      .openapi({ description: 'The GraphQL node ID of the withdrawn alert.', readOnly: true }),
    number: AlertNumberSchema,
    state: z
      .literal('withdrawn')
      .openapi({ description: 'The state of the Dependabot alert.', readOnly: true }),
    dependency: z
      .strictObject({
        package: DependabotAlertPackageSchema,
        manifest_path: z
          .string()
          .nullable()
          .openapi({
            description:
              'The full path to the dependency manifest file, relative to the root of the repository.',
            readOnly: true,
          }),
        version_requirement: z
          .string()
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The dependency version or version constraint last recorded for the dependency associated with this alert.\nFor dependencies detected from a lockfile, this can be the resolved version.\nFor manifest-only dependencies, it can be the declared version constraint. Returns `null` when unavailable.\n\nAn empty string can indicate an unconstrained dependency. The stored value is limited to 64 bytes;\nlonger requirements may have been truncated and may no longer form a complete, valid version constraint.\n\nWhen multiple vulnerable versions of a dependency correspond to the same alert, this field contains one\nrecorded version or constraint and may not represent all vulnerable versions.\n',
            readOnly: true,
          }),
        scope: z
          .enum(['development', 'runtime'])
          .nullable()
          .openapi({
            description: 'The execution scope of the vulnerable dependency.',
            readOnly: true,
          }),
        relationship: z
          .enum(['unknown', 'direct', 'transitive', 'inconclusive'])
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'The vulnerable dependency\'s relationship to your project.\n\n> [!NOTE]\n> We are rolling out support for dependency relationship across ecosystems. This value will be "unknown" for all dependencies in unsupported ecosystems.\n',
            readOnly: true,
          }),
      })
      .openapi({
        description: 'Details for the vulnerable dependency.',
        readOnly: true,
        required: ['package', 'manifest_path', 'scope'],
      }),
    security_advisory: z
      .strictObject({
        ghsa_id: z
          .string()
          .openapi({
            description: 'The unique GitHub identifier assigned to the advisory.',
            readOnly: true,
          }),
        cve_id: z
          .string()
          .nullable()
          .openapi({
            description: 'The CVE identifier assigned to the advisory, if any.',
            readOnly: true,
          }),
      })
      .openapi({
        description: 'Identifiers of the advisory that produced the withdrawn alert.',
        readOnly: true,
        required: ['ghsa_id', 'cve_id'],
      }),
    url: AlertUrlSchema,
    html_url: AlertHtmlUrlSchema,
    created_at: AlertCreatedAtSchema,
    withdrawn_at: z.iso
      .datetime({ offset: true })
      .openapi({
        description:
          "The time that the alert was withdrawn in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ`. This is not the advisory's withdrawal time.",
        readOnly: true,
      }),
  })
  .openapi({
    description:
      'Identifiers for a withdrawn Dependabot alert, captured before deletion so that\nconsumers can reconcile external records. This is not a full alert representation.\n',
    required: [
      'id',
      'node_id',
      'number',
      'state',
      'dependency',
      'security_advisory',
      'url',
      'html_url',
      'created_at',
      'withdrawn_at',
    ],
  })
  .openapi('DependabotAlertWithdrawnWebhook')

