const PersonalAccessTokenRequestSchema = z
  .object({
    id: z
      .int()
      .openapi({
        description:
          'Unique identifier of the request for access via fine-grained personal access token. Used as the `pat_request_id` parameter in the list and review API calls.',
      }),
    owner: SimpleUserSchema,
    permissions_added: z
      .object({
        organization: z.record(z.string(), z.string()).exactOptional(),
        repository: z.record(z.string(), z.string()).exactOptional(),
        other: z.record(z.string(), z.string()).exactOptional(),
      })
      .openapi({
        description: 'New requested permissions, categorized by type of permission.',
        required: [],
      }),
    permissions_upgraded: z
      .object({
        organization: z.record(z.string(), z.string()).exactOptional(),
        repository: z.record(z.string(), z.string()).exactOptional(),
        other: z.record(z.string(), z.string()).exactOptional(),
      })
      .openapi({
        description:
          'Requested permissions that elevate access for a previously approved request for access, categorized by type of permission.',
        required: [],
      }),
    permissions_result: z
      .object({
        organization: z.record(z.string(), z.string()).exactOptional(),
        repository: z.record(z.string(), z.string()).exactOptional(),
        other: z.record(z.string(), z.string()).exactOptional(),
      })
      .openapi({
        description:
          'Permissions requested, categorized by type of permission. This field incorporates `permissions_added` and `permissions_upgraded`.',
        required: [],
      }),
    repository_selection: z
      .enum(['none', 'all', 'subset'])
      .openapi({ description: 'Type of repository selection requested.' }),
    repository_count: z
      .int()
      .nullable()
      .openapi({
        description:
          'The number of repositories the token is requesting access to. This field is only populated when `repository_selection` is `subset`.',
      }),
    repositories: z
      .array(
        z
          .object({
            full_name: z.string(),
            id: z.int().openapi({ description: 'Unique identifier of the repository' }),
            name: z.string().openapi({ description: 'The name of the repository.' }),
            node_id: z.string(),
            private: z
              .boolean()
              .openapi({ description: 'Whether the repository is private or public.' }),
          })
          .openapi({ required: ['id', 'node_id', 'name', 'full_name', 'private'] }),
      )
      .nullable()
      .openapi({
        description:
          'An array of repository objects the token is requesting access to. This field is only populated when `repository_selection` is `subset`.',
      }),
    created_at: z
      .string()
      .openapi({ description: 'Date and time when the request for access was created.' }),
    token_id: z
      .int()
      .openapi({
        description:
          "Unique identifier of the user's token. This field can also be found in audit log events and the organization's settings for their PAT grants.",
      }),
    token_name: z
      .string()
      .openapi({
        description:
          "The name given to the user's token. This field can also be found in an organization's settings page for Active Tokens.",
      }),
    token_expired: z
      .boolean()
      .openapi({
        description: 'Whether the associated fine-grained personal access token has expired.',
      }),
    token_expires_at: z
      .string()
      .nullable()
      .openapi({
        description:
          'Date and time when the associated fine-grained personal access token expires.',
      }),
    token_last_used_at: z
      .string()
      .nullable()
      .openapi({
        description:
          'Date and time when the associated fine-grained personal access token was last used for authentication.',
      }),
  })
  .openapi({
    title: 'Personal Access Token Request',
    description: 'Details of a Personal Access Token Request.',
    required: [
      'id',
      'owner',
      'permissions_added',
      'permissions_upgraded',
      'permissions_result',
      'repository_selection',
      'repository_count',
      'repositories',
      'created_at',
      'token_id',
      'token_name',
      'token_expired',
      'token_expires_at',
      'token_last_used_at',
    ],
  })
  .openapi('PersonalAccessTokenRequest')

