export const postApplicationsClientIdTokenScopedRoute = createRoute({
  method: 'post',
  path: '/applications/{client_id}/token/scoped',
  tags: ['apps'],
  summary: 'Create a scoped access token',
  description:
    'Use a non-scoped user access token to create a repository-scoped and/or permission-scoped user access token. You can specify\nwhich repositories the token can access and which permissions are granted to the\ntoken.\n\nInvalid tokens will return `404 NOT FOUND`.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/apps/apps#create-a-scoped-access-token',
  },
  operationId: 'apps/scope-token',
  request: {
    params: z.object({ client_id: ClientIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              access_token: z
                .string()
                .openapi({
                  description: 'The access token used to authenticate to the GitHub API.',
                  example: 'e72e16c7e42f292c6912e7710c838347ae178b4a',
                }),
              target: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The name of the user or organization to scope the user access token to. **Required** unless `target_id` is specified.',
                  example: 'octocat',
                }),
              target_id: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'The ID of the user or organization to scope the user access token to. **Required** unless `target` is specified.',
                  example: 1,
                }),
              repositories: z
                .array(z.string().openapi({ example: 'rails' }))
                .exactOptional()
                .openapi({
                  description:
                    'The list of repository names to scope the user access token to. `repositories` may not be specified if `repository_ids` is specified.',
                }),
              repository_ids: z
                .array(z.int())
                .exactOptional()
                .openapi({
                  description:
                    'The list of repository IDs to scope the user access token to. `repository_ids` may not be specified if `repositories` is specified.',
                  example: [1],
                }),
              permissions: AppPermissionsSchema.exactOptional(),
            })
            .openapi({ required: ['access_token'] }),
          examples: {
            default: {
              value: {
                access_token: 'e72e16c7e42f292c6912e7710c838347ae178b4a',
                target: 'octocat',
                permissions: { metadata: 'read', issues: 'write', contents: 'read' },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: AuthorizationSchema,
          examples: { default: ScopeTokenExample },
        },
      },
    },
    401: RequiresAuthenticationResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

