export const postCredentialsRevokeRoute = createRoute({
  method: 'post',
  path: '/credentials/revoke',
  tags: ['credentials'],
  summary: 'Revoke a list of credentials',
  description:
    'Submit a list of credentials to be revoked. This endpoint is intended to revoke credentials the caller does not own and may have found exposed on GitHub.com or elsewhere. It can also be used for credentials associated with an old user account that you no longer have access to. Credential owners will be notified of the revocation.\n\nThis endpoint currently accepts the following credential types:\n- Personal access tokens (classic) (`ghp_`)\n- Fine-grained personal access tokens (`github_pat_`)\n- OAuth app access tokens (`gho_`)\n- User-to-server tokens from GitHub Apps (`ghu_`)\n- Refresh tokens from GitHub Apps (`ghr_`)\n\n\nRevoked credentials may impact users on GitHub Free, Pro, & Team and GitHub Enterprise Cloud, and GitHub Enterprise Cloud with Enterprise Managed Users.\nGitHub cannot reactivate any credentials that have been revoked; new credentials will need to be generated.\n\nTo prevent abuse, this API is limited to only 60 unauthenticated requests per hour and a max of 1000 tokens per API request.\n\n> [!NOTE]\n> Any authenticated requests will return a 403.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/credentials/revoke#revoke-a-list-of-credentials',
  },
  operationId: 'credentials/revoke',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              credentials: z
                .array(z.string())
                .min(1)
                .max(1000)
                .openapi({
                  description: 'A list of credentials to be revoked, up to 1000 per request.',
                }),
            })
            .openapi({ required: ['credentials'] }),
          examples: {
            default: {
              value: {
                credentials: [
                  'ghp_1234567890abcdef1234567890abcdef12345678',
                  'github_pat_0A1B2C3D4E5F6G7H8I9J0K_ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456',
                  'gho_1234567890abcdef1234567890abcdef12345678',
                  'ghu_1234567890abcdef1234567890abcdef12345678',
                  'ghr_1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef1234567890ab',
                ],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    202: AcceptedResponse,
    422: ValidationFailedSimpleResponse,
    500: InternalErrorResponse,
  },
})

