export const patchEnterprisesEnterpriseCodeSecurityConfigurationsConfigurationIdRoute = createRoute(
  {
    method: 'patch',
    path: '/enterprises/{enterprise}/code-security/configurations/{configuration_id}',
    tags: ['code-security'],
    summary: 'Update a custom code security configuration for an enterprise',
    description:
      'Updates a code security configuration in an enterprise.\n\nThe authenticated user must be an administrator of the enterprise in order to use this endpoint.\n\nOAuth app tokens and personal access tokens (classic) need the `admin:enterprise` scope to use this endpoint.',
    externalDocs: {
      description: 'API method documentation',
      url: 'https://docs.github.com/rest/code-security/configurations#update-a-custom-code-security-configuration-for-an-enterprise',
    },
    operationId: 'code-security/update-enterprise-configuration',
    request: {
      params: z.object({
        enterprise: EnterpriseParamsSchema,
        configuration_id: ConfigurationIdParamsSchema,
      }),
      body: {
        content: {
          'application/json': {
            schema: z
              .strictObject({
                name: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      'The name of the code security configuration. Must be unique across the enterprise.',
                  }),
                description: z
                  .string()
                  .max(255)
                  .exactOptional()
                  .openapi({ description: 'A description of the code security configuration' }),
                advanced_security: z
                  .enum(['enabled', 'disabled', 'code_security', 'secret_protection'])
                  .exactOptional()
                  .openapi({
                    description:
                      'The enablement status of GitHub Advanced Security features. `enabled` will enable both Code Security and Secret Protection features.\n\n> [!WARNING]\n> `code_security` and `secret_protection` are deprecated values for this field. Prefer the individual `code_security` and `secret_protection` fields to set the status of these features.\n',
                  }),
                code_security: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .exactOptional()
                  .openapi({
                    description: 'The enablement status of GitHub Code Security features.',
                  }),
                dependency_graph: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .exactOptional()
                  .openapi({ description: 'The enablement status of Dependency Graph' }),
                dependency_graph_autosubmit_action: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .exactOptional()
                  .openapi({
                    description: 'The enablement status of Automatic dependency submission',
                  }),
                dependency_graph_autosubmit_action_options: z
                  .object({
                    labeled_runners: z
                      .boolean()
                      .exactOptional()
                      .openapi({
                        description:
                          "Whether to use runners labeled with 'dependency-submission' or standard GitHub runners.",
                      }),
                  })
                  .exactOptional()
                  .openapi({
                    description: 'Feature options for Automatic dependency submission',
                    required: [],
                  }),
                dependabot_alerts: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .exactOptional()
                  .openapi({ description: 'The enablement status of Dependabot alerts' }),
                dependabot_security_updates: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .exactOptional()
                  .openapi({ description: 'The enablement status of Dependabot security updates' }),
                code_scanning_default_setup: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .exactOptional()
                  .openapi({ description: 'The enablement status of code scanning default setup' }),
                code_scanning_default_setup_options:
                  CodeScanningDefaultSetupOptionsSchema.exactOptional(),
                code_scanning_options: CodeScanningOptionsSchema.exactOptional(),
                code_scanning_delegated_alert_dismissal: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .default('disabled')
                  .exactOptional()
                  .openapi({
                    description: 'The enablement status of code scanning delegated alert dismissal',
                  }),
                secret_protection: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .exactOptional()
                  .openapi({
                    description: 'The enablement status of GitHub Secret Protection features.',
                  }),
                secret_scanning: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .exactOptional()
                  .openapi({ description: 'The enablement status of secret scanning' }),
                secret_scanning_push_protection: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .exactOptional()
                  .openapi({
                    description: 'The enablement status of secret scanning push protection',
                  }),
                secret_scanning_validity_checks: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .exactOptional()
                  .openapi({
                    description: 'The enablement status of secret scanning validity checks',
                  }),
                secret_scanning_non_provider_patterns: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .exactOptional()
                  .openapi({
                    description: 'The enablement status of secret scanning non-provider patterns',
                  }),
                secret_scanning_generic_secrets: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .default('disabled')
                  .exactOptional()
                  .openapi({ description: 'The enablement status of Copilot secret scanning' }),
                secret_scanning_delegated_alert_dismissal: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .default('disabled')
                  .exactOptional()
                  .openapi({
                    description:
                      'The enablement status of secret scanning delegated alert dismissal',
                  }),
                secret_scanning_extended_metadata: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .default('disabled')
                  .exactOptional()
                  .openapi({
                    description: 'The enablement status of secret scanning extended metadata',
                  }),
                private_vulnerability_reporting: z
                  .enum(['enabled', 'disabled', 'not_set'])
                  .exactOptional()
                  .openapi({
                    description: 'The enablement status of private vulnerability reporting',
                  }),
                enforcement: z
                  .enum(['enforced', 'unenforced', 'enterprise_enforced'])
                  .exactOptional()
                  .openapi({ description: 'The enforcement status for a security configuration' }),
              })
              .openapi({ required: [] }),
            examples: {
              default: {
                summary: 'Example for updating a code security configuration',
                value: {
                  name: 'octo-enterprise recommended settings v2',
                  secret_scanning: 'disabled',
                  code_scanning_default_setup: 'enabled',
                },
              },
            },
          },
        },
        required: true,
      },
    },
    responses: {
      200: {
        description: 'Response',
        content: {
          'application/json': {
            schema: CodeSecurityConfigurationSchema,
            examples: { default: EnterpriseCodeSecurityConfigurationExample },
          },
        },
      },
      304: NotModifiedResponse,
      400: {
        description:
          'Bad Request because of a global configuration, incompatible parameters, or invalid enforcement changes.',
        content: { 'application/json': { schema: BasicErrorSchema } },
      },
      403: ForbiddenResponse,
      404: NotFoundResponse,
      409: {
        description: 'Conflict because security configuration work is already in progress.',
        content: { 'application/json': { schema: BasicErrorSchema } },
      },
      422: {
        description: 'Validation failed because the configuration is invalid.',
        content: { 'application/json': { schema: ValidationErrorSimpleSchema } },
      },
    },
  },
)

