export const putEnterprisesEnterpriseCopilotPoliciesCodingAgentRoute = createRoute({
  method: 'put',
  path: '/enterprises/{enterprise}/copilot/policies/coding_agent',
  tags: ['copilot'],
  summary: 'Set the coding agent policy for an enterprise',
  description:
    'Sets the policy for Copilot cloud agent usage across an enterprise.\n\nEnterprise owners can configure whether Copilot cloud agent is enabled for all\norganizations, disabled for all organizations, configured by individual organization\nadmins, or enabled for selected organizations only.\n\nOnly enterprise owners can set the coding agent policy for their enterprise.\n\nOAuth app tokens and personal access tokens (classic) need either the `manage_billing:copilot` or `admin:enterprise` scopes to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/copilot/copilot-coding-agent-management#set-the-coding-agent-policy-for-an-enterprise',
  },
  operationId: 'copilot/set-enterprise-coding-agent-policy',
  request: {
    params: z.object({ enterprise: EnterpriseParamsSchema }),
    body: {
      description: 'The coding agent policy configuration',
      content: {
        'application/json': {
          schema: z
            .object({
              policy_state: z
                .enum([
                  'enabled_for_all_orgs',
                  'disabled_for_all_orgs',
                  'enabled_for_selected_orgs',
                  'configured_by_org_admins',
                ])
                .openapi({
                  description:
                    'The policy state for Copilot cloud agent in the enterprise. Can be one of `enabled_for_all_orgs`, `disabled_for_all_orgs`, `enabled_for_selected_orgs`, or `configured_by_org_admins`.',
                }),
            })
            .openapi({ required: ['policy_state'] }),
          examples: {
            default: {
              summary: 'Enable coding agent for all organizations',
              value: { policy_state: 'enabled_for_all_orgs' },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: { 204: NoContentResponse, 400: BadRequestResponse },
})

export const postEnterprisesEnterpriseCopilotPoliciesCodingAgentOrganizationsRoute = createRoute({
  method: 'post',
  path: '/enterprises/{enterprise}/copilot/policies/coding_agent/organizations',
  tags: ['copilot'],
  summary: 'Add organizations to the enterprise coding agent policy',
  description:
    "Enables Copilot cloud agent for the specified organizations within the enterprise.\n\nThe enterprise's coding agent policy must be set to `enabled_for_selected_orgs` before\nusing this endpoint. Organizations can be specified by login or matched via custom properties.\n\nOnly organizations that have Copilot enabled and belong to the enterprise will be affected.\n\nOnly enterprise owners can add organizations to the coding agent policy.\n\nOAuth app tokens and personal access tokens (classic) need either the `manage_billing:copilot` or `admin:enterprise` scopes to use this endpoint.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/copilot/copilot-coding-agent-management#add-organizations-to-the-enterprise-coding-agent-policy',
  },
  operationId: 'copilot/add-organizations-to-enterprise-coding-agent-policy',
  request: {
    params: z.object({ enterprise: EnterpriseParamsSchema }),
    body: {
      description: 'The organizations to enable Copilot cloud agent for',
      content: {
        'application/json': {
          schema: z
            .object({
              organizations: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    'List of organization logins within the enterprise to enable Copilot cloud agent for.',
                }),
              custom_properties: z
                .array(
                  z
                    .object({
                      property_name: z
                        .string()
                        .openapi({ description: 'The name of the custom property to filter by.' }),
                      values: z
                        .array(z.string())
                        .openapi({ description: 'The values of the custom property to match.' }),
                    })
                    .openapi({ required: ['property_name', 'values'] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'List of custom property filters to match organizations. Organizations matching any of the specified property name/value pairs will be included. This is a one-time operation, setting the property on an organization in the future will not automatically update its coding agent policy.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            default: {
              summary: 'Add organizations that match a login or have a custom property',
              value: {
                organizations: ['my-org-1', 'my-org-2'],
                custom_properties: [
                  { property_name: 'department', values: ['engineering', 'security'] },
                ],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: { 204: NoContentResponse, 400: BadRequestResponse },
})

