export const patchGistsGistIdRoute = createRoute({
  method: 'patch',
  path: '/gists/{gist_id}',
  tags: ['gists'],
  summary: 'Update a gist',
  description:
    'Allows you to update a gist\'s description and to update, delete, or rename gist files. Files\nfrom the previous version of the gist that aren\'t explicitly changed during an edit\nare unchanged.\n\nAt least one of `description` or `files` is required.\n\nThis endpoint supports the following custom media types. For more information, see "[Media types](https://docs.github.com/rest/using-the-rest-api/getting-started-with-the-rest-api#media-types)."\n\n- **`application/vnd.github.raw+json`**: Returns the raw markdown. This is the default if you do not pass any specific media type.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/gists/gists#update-a-gist',
  },
  operationId: 'gists/update',
  request: {
    params: z.object({ gist_id: GistIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              description: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'The description of the gist.',
                  example: 'Example Ruby script',
                }),
              files: z
                .record(
                  z.string(),
                  z
                    .object({
                      content: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'The new content of the file.' }),
                      filename: z
                        .string()
                        .nullable()
                        .exactOptional()
                        .openapi({ description: 'The new filename for the file.' }),
                    })
                    .nullable()
                    .openapi({ required: [] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'The gist files to be updated, renamed, or deleted. Each `key` must match the current filename\n(including extension) of the targeted gist file. For example: `hello.py`.\n\nTo delete a file, set the whole file to null. For example: `hello.py : null`. The file will also be\ndeleted if the specified object does not contain at least one of `content` or `filename`.',
                  example: { 'hello.rb': { content: 'blah', filename: 'goodbye.rb' } },
                }),
            })
            .nullable()
            .openapi({ required: [] }),
          examples: {
            updateGist: {
              summary: 'Updating a gist',
              value: {
                description: 'An updated gist description',
                files: { 'README.md': { content: 'Hello World from GitHub' } },
              },
            },
            deleteFile: { summary: 'Deleting a gist file', value: { files: { 'hello.py': null } } },
            renameFile: {
              summary: 'Renaming a gist file',
              value: { files: { 'hello.py': { filename: 'goodbye.py' } } },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: GistSimpleSchema,
          examples: {
            updateGist: GistExample,
            deleteFile: DeleteGistFileExample,
            renameFile: RenameGistFileExample,
          },
        },
      },
    },
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

