export const postMarkdownRoute = createRoute({
  method: 'post',
  path: '/markdown',
  tags: ['markdown'],
  summary: 'Render a Markdown document',
  description:
    'Depending on what is rendered in the Markdown, you may need to provide additional token scopes for labels, such as `issues:read` or `pull_requests:read`.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/markdown/markdown#render-a-markdown-document',
  },
  operationId: 'markdown/render',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              text: z.string().openapi({ description: 'The Markdown text to render in HTML.' }),
              mode: z
                .enum(['markdown', 'gfm'])
                .default('markdown')
                .exactOptional()
                .openapi({ description: 'The rendering mode.', example: 'markdown' }),
              context: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The repository context to use when creating references in `gfm` mode.  For example, setting `context` to `octo-org/octo-repo` will change the text `#42` into an HTML link to issue 42 in the `octo-org/octo-repo` repository.',
                }),
            })
            .openapi({ required: ['text'] }),
          examples: {
            default: { summary: 'Rendering markdown', value: { text: 'Hello **world**' } },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'text/html': {
          schema: z.string(),
          examples: {
            default: { summary: 'Example response', value: '<p>Hello <strong>world</strong></p>' },
          },
        },
      },
      headers: z.object({
        'Content-Type': ContentTypeHeaderSchema,
        'Content-Length': {
          example: '279',
          schema: z
            .string()
            .exactOptional()
            .openapi({ example: '279', param: { required: false } }),
        },
        'X-CommonMarker-Version': XCommonMarkerVersionHeaderSchema,
      }),
    },
    304: NotModifiedResponse,
  },
})

export const postMarkdownRawRoute = createRoute({
  method: 'post',
  path: '/markdown/raw',
  tags: ['markdown'],
  summary: 'Render a Markdown document in raw mode',
  description:
    'You must send Markdown as plain text (using a `Content-Type` header of `text/plain` or `text/x-markdown`) to this endpoint, rather than using JSON format. In raw mode, [GitHub Flavored Markdown](https://github.github.com/gfm/) is not supported and Markdown will be rendered in plain format like a README.md file. Markdown content must be 400 KB or less.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/markdown/markdown#render-a-markdown-document-in-raw-mode',
  },
  operationId: 'markdown/render-raw',
  request: {
    body: {
      content: {
        'text/plain': {
          schema: z.string(),
          examples: { default: { value: { text: 'Hello **world**' } } },
        },
        'text/x-markdown': {
          schema: z.string(),
          examples: {
            default: { summary: 'Rendering markdown', value: { text: 'Hello **world**' } },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'text/html': {
          schema: z.string(),
          examples: {
            default: { summary: 'Example response', value: '<p>Hello <strong>world</strong></p>' },
          },
        },
      },
      headers: z.object({ 'X-CommonMarker-Version': XCommonMarkerVersionHeaderSchema }),
    },
    304: NotModifiedResponse,
  },
})

export const getMarketplaceListingAccountsAccountIdRoute = createRoute({
  method: 'get',
  path: '/marketplace_listing/accounts/{account_id}',
  tags: ['apps'],
  summary: 'Get a subscription plan for an account',
  description:
    "Shows whether the user or organization account actively subscribes to a plan listed by the authenticated GitHub App. When someone submits a plan change that won't be processed until the end of their billing cycle, you will also see the upcoming pending change.\n\nGitHub Apps must use a [JWT](https://docs.github.com/apps/building-github-apps/authenticating-with-github-apps/#authenticating-as-a-github-app) to access this endpoint. OAuth apps must use [basic authentication](https://docs.github.com/rest/authentication/authenticating-to-the-rest-api#using-basic-authentication) with their client ID and client secret to access this endpoint.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/apps/marketplace#get-a-subscription-plan-for-an-account',
  },
  operationId: 'apps/get-subscription-plan-for-account',
  request: { params: z.object({ account_id: AccountIdParamsSchema }) },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: MarketplacePurchaseSchema,
          examples: { default: MarketplacePurchaseExample },
        },
      },
    },
    401: RequiresAuthenticationResponse,
    404: {
      description: 'Not Found when the account has not purchased the listing',
      content: { 'application/json': { schema: BasicErrorSchema } },
    },
  },
})

