export const getNotificationsRoute = createRoute({
  method: 'get',
  path: '/notifications',
  tags: ['activity'],
  summary: 'List notifications for the authenticated user',
  description: 'List all notifications for the current user, sorted by most recently updated.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/activity/notifications#list-notifications-for-the-authenticated-user',
  },
  operationId: 'activity/list-notifications-for-authenticated-user',
  request: {
    query: z.object({
      all: AllParamsSchema,
      participating: ParticipatingParamsSchema,
      since: SinceParamsSchema,
      before: BeforeParamsSchema,
      page: PageParamsSchema,
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            description:
              'The number of results per page (max 50). For more information, see "[Using pagination in the REST API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the-rest-api)."',
            in: 'query',
            schema: { type: 'integer', default: 50 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z.array(ThreadSchema),
          examples: { default: ThreadItemsExample },
        },
      },
      headers: z.object({ Link: LinkHeaderSchema }),
    },
    304: NotModifiedResponse,
    401: RequiresAuthenticationResponse,
    403: ForbiddenResponse,
    422: ValidationFailedResponse,
  },
})

export const putNotificationsRoute = createRoute({
  method: 'put',
  path: '/notifications',
  tags: ['activity'],
  summary: 'Mark notifications as read',
  description:
    'Marks all notifications as "read" for the current user. If the number of notifications is too large to complete in one request, you will receive a `202 Accepted` status and GitHub will run an asynchronous process to mark notifications as "read." To check whether any "unread" notifications remain, you can use the [List notifications for the authenticated user](https://docs.github.com/rest/activity/notifications#list-notifications-for-the-authenticated-user) endpoint and pass the query parameter `all=false`.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/activity/notifications#mark-notifications-as-read',
  },
  operationId: 'activity/mark-notifications-as-read',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              last_read_at: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({
                  description:
                    'Describes the last point that notifications were checked. Anything updated since this time will not be marked as read. If you omit this parameter, all notifications are marked as read. This is a timestamp in [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) format: `YYYY-MM-DDTHH:MM:SSZ`. Default: The current timestamp.',
                }),
              read: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Whether the notification has been read.' }),
            })
            .openapi({ required: [] }),
          examples: { default: { value: { last_read_at: '2022-06-10T00:00:00Z', read: true } } },
        },
      },
    },
  },
  responses: {
    202: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z.object({ message: z.string().exactOptional() }).openapi({ required: [] }),
          examples: { default: NotificationsMarkReadExample },
        },
      },
    },
    205: { description: 'Reset Content' },
    304: NotModifiedResponse,
    401: RequiresAuthenticationResponse,
    403: ForbiddenResponse,
  },
})

