export const getOrganizationsOrgSettingsBillingBudgetsRoute = createRoute({
  method: 'get',
  path: '/organizations/{org}/settings/billing/budgets',
  tags: ['billing'],
  summary: 'Get all budgets for an organization',
  description:
    'Gets all budgets for an organization. The authenticated user must be an organization admin or billing manager.\nEach page returns up to 100 budgets.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/billing/budgets#get-all-budgets-for-an-organization',
  },
  operationId: 'billing/get-all-budgets-org',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    query: z.object({
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            description: 'The page number of the results to fetch.',
            in: 'query',
            schema: { type: 'integer', default: 1 },
            required: false,
          },
        }),
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .default(10)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            description: 'The number of results per page (max 100).',
            in: 'query',
            schema: { type: 'integer', default: 10 },
            required: false,
          },
        }),
      scope: z
        .enum([
          'enterprise',
          'organization',
          'repository',
          'cost_center',
          'multi_user_customer',
          'user',
        ])
        .exactOptional()
        .openapi({
          param: {
            name: 'scope',
            description:
              'Filter budgets by scope type.\n\n- `organization`: Budgets scoped to the organization.\n- `repository`: Budgets scoped to a repository.\n- `multi_user_customer`: Universal budgets that apply to all users in the organization.\n- `user`: Budgets scoped to an individual user.',
            in: 'query',
            schema: {
              type: 'string',
              enum: [
                'enterprise',
                'organization',
                'repository',
                'cost_center',
                'multi_user_customer',
                'user',
              ],
            },
            required: false,
          },
        }),
      user: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'user',
            description: 'Filter consumed amount details for budgets by the specified user login.',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: GetAllBudgetsResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    500: InternalErrorResponse,
  },
})

export const postOrganizationsOrgSettingsBillingBudgetsRoute = createRoute({
  method: 'post',
  path: '/organizations/{org}/settings/billing/budgets',
  tags: ['billing'],
  summary: 'Create a budget for an organization',
  description:
    'Creates a new budget for an organization. The authenticated user must be an\norganization admin or billing manager.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/billing/budgets#create-a-budget-for-an-organization',
  },
  operationId: 'billing/create-organization-budget',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              budget_amount: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'The budget amount in whole dollars. For license-based products, this represents the number of licenses.',
                }),
              prevent_further_usage: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Whether to prevent additional spending once the budget is exceeded. For `user` and `multi_user_customer` scopes, this must be `true`.',
                }),
              budget_alerting: z
                .object({
                  will_alert: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description:
                        'Whether alerts are enabled for this budget. Rejected for user-scope as alerting is always disabled for them.',
                    }),
                  alert_recipients: z
                    .array(z.string())
                    .exactOptional()
                    .openapi({
                      description:
                        'Array of user login names who will receive alerts. Rejected for user-scope as alerting is always disabled for them.',
                    }),
                })
                .exactOptional()
                .openapi({ required: [] }),
              budget_scope: z
                .enum(['organization', 'repository', 'multi_user_customer', 'user'])
                .exactOptional()
                .openapi({
                  description:
                    'The scope of the budget for this organization.\n\n- `organization`: Apply the budget to the organization.\n- `repository`: Apply the budget to a specific repository in the organization.\n- `multi_user_customer`: Apply a universal budget to all users in the organization.\n- `user`: Apply the budget to a single user in the organization.\n\n`user` and `multi_user_customer` scopes are only supported when\n`budget_product_sku` is `ai_credits` or `premium_requests`.',
                }),
              budget_entity_name: z
                .string()
                .default('')
                .exactOptional()
                .openapi({ description: 'The name of the entity to apply the budget to' }),
              budget_type: z
                .xor([
                  z.literal('BundlePricing'),
                  z.literal('ProductPricing'),
                  z.literal('SkuPricing'),
                ])
                .exactOptional()
                .openapi({
                  description:
                    'The type of pricing model used by the budget. Determines how `budget_product_sku` is interpreted.\n\n- `BundlePricing`: Covers all AI credit SKUs. Set `budget_product_sku` to `ai_credits`.\n- `ProductPricing`: Covers all SKUs that belong to a product. Set `budget_product_sku` to a product such as `actions` or `packages`.\n- `SkuPricing`: Covers a single, specific SKU. Set `budget_product_sku` to a SKU such as `actions_linux`.',
                }),
              budget_product_sku: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'A single product or SKU that will be covered in the budget',
                }),
              user: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The username of the user for `user` scope budgets. This field is required when `budget_scope` is `user`.',
                }),
              expires_at: z.iso
                .date()
                .exactOptional()
                .openapi({
                  description:
                    'The date the budget will expire in `YYYY-MM-DD` format. Only dates in the future are accepted.\nIf not provided, the budget will not expire.\n\nOnly supported for budgets with `budget_scope` of `user`',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            'create-organization-budget': {
              summary: 'Create organization budget example',
              value: {
                budget_amount: 500,
                prevent_further_usage: true,
                budget_scope: 'organization',
                budget_entity_name: '',
                budget_type: 'ProductPricing',
                budget_product_sku: 'actions',
                budget_alerting: { will_alert: false, alert_recipients: [] },
              },
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Budget created successfully',
      content: {
        'application/json': {
          schema: CreateBudgetSchema,
          examples: { 'create-organization-budget': CreateBudgetExample },
        },
      },
    },
    400: BadRequestResponse,
    401: RequiresAuthenticationResponse,
    403: {
      description: 'Insufficient permissions',
      content: {
        'application/json': {
          schema: BasicErrorSchema,
          examples: {
            'insufficient-permissions': {
              value: {
                message: 'Insufficient permissions to create a budget.',
                documentation_url:
                  'https://docs.github.com/rest/billing/budgets#create-a-budget-for-an-organization',
              },
            },
          },
        },
      },
    },
    404: {
      description: 'Feature not enabled or organization not found',
      content: {
        'application/json': {
          schema: BasicErrorSchema,
          examples: {
            'feature-not-enabled': {
              value: {
                message: 'Not Found',
                documentation_url:
                  'https://docs.github.com/rest/billing/budgets#create-a-budget-for-an-organization',
              },
            },
          },
        },
      },
    },
    422: ValidationFailedResponse,
    500: {
      description: 'Internal server error',
      content: {
        'application/json': {
          schema: BasicErrorSchema,
          examples: {
            'server-error': {
              value: {
                message: 'Unable to create budget.',
                documentation_url:
                  'https://docs.github.com/rest/billing/budgets#create-a-budget-for-an-organization',
              },
            },
          },
        },
      },
    },
  },
})

