export const postOrgsOrgActionsHostedRunnersRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/actions/hosted-runners',
  tags: ['actions'],
  summary: 'Create a GitHub-hosted runner for an organization',
  description:
    'Creates a GitHub-hosted runner for an organization.\nOAuth tokens and personal access tokens (classic) need the `manage_runners:org` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/actions/hosted-runners#create-a-github-hosted-runner-for-an-organization',
  },
  operationId: 'actions/create-hosted-runner-for-org',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z
                .string()
                .openapi({
                  description:
                    "Name of the runner. Must be between 1 and 64 characters and may only contain upper and lowercase letters a-z, numbers 0-9, '.', '-', and '_'.",
                }),
              image: z
                .object({
                  id: z
                    .string()
                    .exactOptional()
                    .openapi({ description: 'The unique identifier of the runner image.' }),
                  source: z
                    .enum(['github', 'partner', 'custom'])
                    .exactOptional()
                    .openapi({ description: 'The source of the runner image.' }),
                  version: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        'The version of the runner image to deploy. This is relevant only for runners using custom images.',
                    }),
                })
                .openapi({
                  description:
                    'The image of runner. To list all available images, use `GET /actions/hosted-runners/images/github-owned` or `GET /actions/hosted-runners/images/partner`.',
                  required: [],
                }),
              size: z
                .string()
                .openapi({
                  description:
                    'The machine size of the runner. To list available sizes, use `GET actions/hosted-runners/machine-sizes`',
                }),
              runner_group_id: z
                .int()
                .openapi({ description: 'The existing runner group to add this runner to.' }),
              maximum_runners: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'The maximum amount of runners to scale up to. Runners will not auto-scale above this number. Use this setting to limit your cost.',
                }),
              enable_static_ip: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Whether this runner should be created with a static public IP. Note limit on account. To list limits on account, use `GET actions/hosted-runners/limits`',
                }),
              image_gen: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description: 'Whether this runner should be used to generate custom images.',
                }),
            })
            .openapi({ required: ['name', 'image', 'size', 'runner_group_id'] }),
          examples: {
            default: {
              value: {
                name: 'My Hosted runner',
                image: { id: 'ubuntu-latest', source: 'github' },
                runner_group_id: 1,
                size: '4-core',
                maximum_runners: 50,
                enable_static_ip: false,
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: ActionsHostedRunnerSchema,
          examples: { default: ActionsHostedRunnerExample },
        },
      },
    },
  },
})

