export const getOrgsOrgActionsPoliciesPolicyIdRoute = createRoute({
  method: 'get',
  path: '/orgs/{org}/actions/policies/{policy_id}',
  tags: ['actions'],
  summary: 'Get an organization Actions policy',
  description: 'Get a specific Actions policy for an organization.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/actions/policies#get-an-organization-actions-policy',
  },
  operationId: 'actions/get-org-actions-policy',
  request: {
    params: z.object({
      org: OrgParamsSchema,
      policy_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'policy_id',
            description: 'The ID of the policy.',
            in: 'path',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: ActionsPolicySchema,
          examples: { default: ActionsPolicyExample },
        },
      },
    },
    404: NotFoundResponse,
    500: InternalErrorResponse,
  },
})

