export const postOrgsOrgActionsRunnerGroupsRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/actions/runner-groups',
  tags: ['actions'],
  summary: 'Create a self-hosted runner group for an organization',
  description:
    'Creates a new self-hosted runner group for an organization.\n\nOAuth tokens and personal access tokens (classic) need the `admin:org` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/actions/self-hosted-runner-groups#create-a-self-hosted-runner-group-for-an-organization',
  },
  operationId: 'actions/create-self-hosted-runner-group-for-org',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z.string().openapi({ description: 'Name of the runner group.' }),
              visibility: z
                .enum(['selected', 'all', 'private'])
                .default('all')
                .exactOptional()
                .openapi({
                  description:
                    'Visibility of a runner group. You can select all repositories, select individual repositories, or limit access to private repositories.',
                }),
              selected_repository_ids: z
                .array(z.int().openapi({ description: 'Unique identifier of the repository.' }))
                .exactOptional()
                .openapi({
                  description: 'List of repository IDs that can access the runner group.',
                }),
              runners: z
                .array(z.int().openapi({ description: 'Unique identifier of the runner.' }))
                .exactOptional()
                .openapi({ description: 'List of runner IDs to add to the runner group.' }),
              allows_public_repositories: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description: 'Whether the runner group can be used by `public` repositories.',
                }),
              restricted_to_workflows: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'If `true`, the runner group will be restricted to running only the workflows specified in the `selected_workflows` array.',
                }),
              selected_workflows: z
                .array(
                  z
                    .string()
                    .openapi({
                      description:
                        'Name of workflow the runner group should be allowed to run. Note that a ref, tag, or long SHA is required.',
                      example: 'octo-org/octo-repo/.github/workflows/deploy.yaml@main',
                    }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'List of workflows the runner group should be allowed to run. This setting will be ignored unless `restricted_to_workflows` is set to `true`.',
                }),
              network_configuration_id: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'The identifier of a hosted compute network configuration.',
                }),
            })
            .openapi({ required: ['name'] }),
          examples: {
            default: {
              value: {
                name: 'Expensive hardware runners',
                visibility: 'selected',
                selected_repository_ids: [32, 91],
                runners: [9, 2],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: RunnerGroupsOrgSchema,
          examples: { default: RunnerGroupExample },
        },
      },
    },
  },
})

