export const getOrgsOrgActionsRunnersDeprecationsVersionRoute = createRoute({
  method: 'get',
  path: '/orgs/{org}/actions/runners/deprecations/{version}',
  tags: ['actions'],
  summary: 'Get runner version end-of-life schedule for an organization',
  description:
    'Gets the end-of-life schedule for a specific runner version in an organization. Returns the runner version\nand the dates when registration and runtime support will end.\n\nAuthenticated users must have admin access to the organization to use this endpoint.\n\nOAuth app tokens and personal access tokens (classic) need the `admin:org` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/actions/self-hosted-runners#get-runner-version-end-of-life-schedule-for-an-organization',
  },
  operationId: 'actions/get-runner-version-deprecation-for-org',
  request: {
    params: z.object({
      org: OrgParamsSchema,
      version: z
        .string()
        .openapi({
          param: {
            name: 'version',
            description: 'The runner version to look up.',
            in: 'path',
            required: true,
            schema: { type: 'string' },
            example: '2.300.0',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z
            .object({
              runner_version: z
                .string()
                .openapi({ description: 'The runner version string.', example: '2.300.0' }),
              registration_deprecates_at: z.iso
                .datetime({ offset: true })
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'The date after which this runner version can no longer register. Null if no schedule is set.',
                  example: '2026-08-01T00:00:00Z',
                }),
              runtime_deprecates_at: z.iso
                .datetime({ offset: true })
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'The date after which jobs will no longer be dispatched to runners on this version.',
                  example: '2026-09-01T00:00:00Z',
                }),
            })
            .openapi({ required: ['runner_version'] }),
          examples: {
            default: {
              value: { runner_version: '2.300.0', runtime_deprecates_at: '2026-09-01T00:00:00Z' },
            },
          },
        },
      },
    },
  },
})

