export const putOrgsOrgActionsSecretsSecretNameRepositoriesRepositoryIdRoute = createRoute({
  method: 'put',
  path: '/orgs/{org}/actions/secrets/{secret_name}/repositories/{repository_id}',
  tags: ['actions'],
  summary: 'Add selected repository to an organization secret',
  description:
    'Adds a repository to an organization secret when the `visibility` for\nrepository access is set to `selected`. For more information about setting the visibility, see [Create or\nupdate an organization secret](https://docs.github.com/rest/actions/secrets#create-or-update-an-organization-secret).\n\nAuthenticated users must have collaborator access to a repository to create, update, or read secrets.\n\nOAuth tokens and personal access tokens (classic) need the `admin:org` scope to use this endpoint. If the repository is private, OAuth tokens and personal access tokens (classic) need the `repo` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/actions/secrets#add-selected-repository-to-an-organization-secret',
  },
  operationId: 'actions/add-selected-repo-to-org-secret',
  request: {
    params: z.object({
      org: OrgParamsSchema,
      secret_name: SecretNameParamsSchema,
      repository_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: { name: 'repository_id', in: 'path', required: true, schema: { type: 'integer' } },
        }),
    }),
  },
  responses: {
    204: { description: 'No Content when repository was added to the selected list' },
    409: { description: 'Conflict when visibility type is not set to selected' },
  },
})

