export const putOrgsOrgAgentsVariablesNameRepositoriesRepositoryIdRoute = createRoute({
  method: 'put',
  path: '/orgs/{org}/agents/variables/{name}/repositories/{repository_id}',
  tags: ['agents'],
  summary: 'Add selected repository to an organization variable',
  description:
    'Adds a repository to an organization agent variable that is available to selected repositories.\nOrganization variables that are available to selected repositories have their `visibility` field set to `selected`.\n\nAuthenticated users must have collaborator access to a repository to create, update, or read variables.\n\nOAuth tokens and personal access tokens (classic) need the `admin:org` scope to use this endpoint. If the repository is private, OAuth tokens and personal access tokens (classic) need the `repo` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/agents/variables#add-selected-repository-to-an-organization-variable',
  },
  operationId: 'agents/add-selected-repo-to-org-variable',
  request: {
    params: z.object({
      org: OrgParamsSchema,
      name: VariableNameParamsSchema,
      repository_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: { name: 'repository_id', in: 'path', required: true, schema: { type: 'integer' } },
        }),
    }),
  },
  responses: {
    204: { description: 'Response' },
    409: { description: 'Response when the visibility of the variable is not set to `selected`' },
  },
})

