export const postOrgsOrgArtifactsMetadataDeploymentRecordRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/artifacts/metadata/deployment-record',
  tags: ['orgs'],
  summary: 'Create an artifact deployment record',
  description:
    'Create or update deployment records for an artifact associated\nwith an organization.\nThis endpoint allows you to record information about a specific\nartifact, such as its name, digest, environments, cluster, and\ndeployment.\nThe deployment name has to be uniqe within a cluster (i.e a\ncombination of logical, physical environment and cluster) as it\nidentifies unique deployment.\nMultiple requests for the same combination of logical, physical\nenvironment, cluster and deployment name will only create one\nrecord, successive request will update the existing record.\nThis allows for a stable tracking of a deployment where the actual\ndeployed artifact can change over time.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/artifact-metadata#create-an-artifact-deployment-record',
  },
  operationId: 'orgs/create-artifact-deployment-record',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z
                .string()
                .min(1)
                .max(256)
                .openapi({ description: 'The name of the artifact.', example: 'libfoo' }),
              digest: z
                .string()
                .regex(/^sha256:[a-f0-9]{64}$/)
                .length(71)
                .openapi({ description: 'The hex encoded digest of the artifact.' }),
              version: z
                .string()
                .min(1)
                .max(100)
                .exactOptional()
                .openapi({
                  description: 'The artifact version.',
                  'x-multi-segment': true,
                  example: '1.2.3',
                }),
              status: z
                .enum(['deployed', 'decommissioned'])
                .openapi({
                  description:
                    'The status of the artifact. Can be either deployed or decommissioned.',
                }),
              logical_environment: z
                .string()
                .min(1)
                .max(128)
                .openapi({ description: 'The stage of the deployment.' }),
              physical_environment: z
                .string()
                .max(128)
                .exactOptional()
                .openapi({ description: 'The physical region of the deployment.' }),
              cluster: z
                .string()
                .max(128)
                .exactOptional()
                .openapi({ description: 'The deployment cluster.' }),
              deployment_name: z
                .string()
                .max(256)
                .openapi({
                  description:
                    'The unique identifier for the deployment represented by the new record. To accommodate differing\ncontainers and namespaces within a cluster, the following format is recommended:\n{namespaceName}-{deploymentName}-{containerName}.\n',
                }),
              tags: z
                .record(z.string(), z.string())
                .refine((val) => Object.keys(val).length <= 5)
                .exactOptional()
                .openapi({ description: 'The tags associated with the deployment.' }),
              runtime_risks: z
                .array(
                  z.enum([
                    'critical-resource',
                    'internet-exposed',
                    'lateral-movement',
                    'sensitive-data',
                  ]),
                )
                .max(4)
                .superRefine((items, ctx) => {
                  const seen = new Map()
                  for (const [i, val] of items.entries()) {
                    const key = JSON.stringify(val)
                    if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                    else seen.set(key, i)
                  }
                })
                .exactOptional()
                .openapi({
                  description: 'A list of runtime risks associated with the deployment.',
                }),
              github_repository: z
                .string()
                .regex(/^[A-Za-z0-9.\-_]+$/)
                .min(1)
                .max(100)
                .exactOptional()
                .openapi({
                  description:
                    'The name of the GitHub repository associated with the artifact. This should be used\nwhen there are no provenance attestations available for the artifact. The repository\nmust belong to the organization specified in the path parameter.\n\nIf a provenance attestation is available for the artifact, the API will use\nthe repository information from the attestation instead of this parameter.',
                  example: 'my-github-repo',
                }),
              return_records: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    'If true, the endpoint will return the created or updated record in the response body.\n',
                }),
            })
            .openapi({
              required: ['name', 'digest', 'status', 'logical_environment', 'deployment_name'],
            }),
          examples: {
            default: {
              value: {
                name: 'awesome-image',
                digest: 'sha256:1bb1e949e55dcefc6353e7b36c8897d2a107d8e8dca49d4e3c0ea8493fc0bc72',
                status: 'deployed',
                logical_environment: 'prod',
                physical_environment: 'pacific-east',
                cluster: 'moda-1',
                deployment_name: 'deployment-pod',
                tags: { 'data-access': 'sensitive' },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Artifact deployment record stored successfully.',
      content: {
        'application/json': {
          schema: z
            .object({
              total_count: z
                .int()
                .openapi({ description: 'The number of deployment records created' }),
              deployment_records: z.array(ArtifactDeploymentRecordSchema).exactOptional(),
            })
            .openapi({ required: ['total_count'] }),
          examples: { default: ArtifactDeploymentRecordListExample },
        },
      },
    },
    403: ForbiddenResponse,
    404: NotFoundResponse,
  },
})

export const postOrgsOrgArtifactsMetadataDeploymentRecordClusterClusterRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/artifacts/metadata/deployment-record/cluster/{cluster}',
  tags: ['orgs'],
  summary: 'Set cluster deployment records',
  description:
    "Set deployment records for a given cluster.\nIf proposed records in the 'deployments' field have identical 'cluster', 'logical_environment',\n'physical_environment', and 'deployment_name' values as existing records, the existing records will be updated.\nIf no existing records match, new records will be created.\nNote: Artifacts are uniquely identified by the combination of their repository and digest fields. If two entries in the deployments\narray resolve to the same repository and have identical digest fields but differing name and version fields, the endpoint will use\nthe artifact name and version from the record processed first, since a single artifact (identified by repository and digest) can\nonly have one name and version.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/artifact-metadata#set-cluster-deployment-records',
  },
  operationId: 'orgs/set-cluster-deployment-records',
  request: {
    params: z.object({
      org: OrgParamsSchema,
      cluster: z
        .string()
        .regex(/^[a-zA-Z0-9._-]+$/)
        .min(1)
        .max(128)
        .openapi({
          param: {
            name: 'cluster',
            in: 'path',
            description: 'The cluster name.',
            required: true,
            schema: { type: 'string', minLength: 1, maxLength: 128, pattern: '^[a-zA-Z0-9._-]+$' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              logical_environment: z
                .string()
                .min(1)
                .max(128)
                .openapi({ description: 'The stage of the deployment.' }),
              physical_environment: z
                .string()
                .max(128)
                .exactOptional()
                .openapi({ description: 'The physical region of the deployment.' }),
              deployments: z
                .array(
                  z
                    .object({
                      name: z
                        .string()
                        .min(1)
                        .max(256)
                        .openapi({ description: 'The name of the artifact.' }),
                      digest: z
                        .string()
                        .regex(/^sha256:[a-f0-9]{64}$/)
                        .length(71)
                        .openapi({ description: 'The hex encoded digest of the artifact.' }),
                      version: z
                        .string()
                        .max(100)
                        .exactOptional()
                        .openapi({
                          description: 'The artifact version.',
                          'x-multi-segment': true,
                          example: '1.2.3',
                        }),
                      status: z
                        .enum(['deployed', 'decommissioned'])
                        .default('deployed')
                        .exactOptional()
                        .openapi({ description: 'The deployment status of the artifact.' }),
                      deployment_name: z
                        .string()
                        .min(1)
                        .max(256)
                        .openapi({
                          description:
                            'The unique identifier for the deployment represented by the new record. To accommodate differing\ncontainers and namespaces within a record set, the following format is recommended:\n{namespaceName}-{deploymentName}-{containerName}.\nThe deployment_name must be unique across all entries in the deployments array.\n',
                        }),
                      github_repository: z
                        .string()
                        .regex(/^[A-Za-z0-9.\-_]+$/)
                        .max(100)
                        .exactOptional()
                        .openapi({
                          description:
                            'The name of the GitHub repository associated with the artifact. This should be used\nwhen there are no provenance attestations available for the artifact. The repository\nmust belong to the organization specified in the path parameter.\n\nIf a provenance attestation is available for the artifact, the API will use\nthe repository information from the attestation instead of this parameter.',
                          example: 'my-github-repo',
                        }),
                      tags: z
                        .record(z.string(), z.string())
                        .exactOptional()
                        .openapi({ description: 'Key-value pairs to tag the deployment record.' }),
                      runtime_risks: z
                        .array(
                          z.enum([
                            'critical-resource',
                            'internet-exposed',
                            'lateral-movement',
                            'sensitive-data',
                          ]),
                        )
                        .max(4)
                        .superRefine((items, ctx) => {
                          const seen = new Map()
                          for (const [i, val] of items.entries()) {
                            const key = JSON.stringify(val)
                            if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                            else seen.set(key, i)
                          }
                        })
                        .exactOptional()
                        .openapi({
                          description: 'A list of runtime risks associated with the deployment.',
                        }),
                    })
                    .openapi({ required: ['name', 'deployment_name', 'digest'] }),
                )
                .max(1000)
                .openapi({ description: 'The list of deployments to record.' }),
              partial_success: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'When enabled, deployments associated with repositories the actor can write to are processed\nwhile deployments associated with repositories that cannot be resolved or written to by the actor\nare skipped and reported in the `errors` array. When false (the default), the endpoint returns\nan error if any targeted repository cannot be resolved, the actor lacks write access, or no matching attestation can be found.\n',
                }),
              return_records: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    'If true, the endpoint will return the set records in the response body\n',
                }),
            })
            .openapi({ required: ['logical_environment', 'deployments'] }),
          examples: {
            default: {
              value: {
                logical_environment: 'prod',
                physical_environment: 'pacific-east',
                deployments: [
                  {
                    name: 'awesome-image',
                    digest:
                      'sha256:1bb1e949e55dcefc6353e7b36c8897d2a107d8e8dca49d4e3c0ea8493fc0bc72',
                    version: '2.1.0',
                    status: 'deployed',
                    deployment_name: 'deployment-pod',
                    tags: { 'owning-team': 'platform' },
                    runtime_risks: ['sensitive-data'],
                  },
                ],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Deployment records created or updated successfully.\n',
      content: {
        'application/json': {
          schema: z
            .object({
              total_count: z
                .int()
                .openapi({ description: 'The number of deployment records created' }),
              deployment_records: z.array(ArtifactDeploymentRecordSchema).exactOptional(),
            })
            .openapi({ required: ['total_count'] }),
          examples: { default: ArtifactDeploymentRecordListExample },
        },
      },
    },
    207: {
      description:
        'This response format is only returned when `partial_success` is set to true in the request body.\nSuccessfully processed deployments are included in the `deployment_records` field. Records that could\nnot be processed and were skipped because of unresolvable repositories, missing actor permissions, or lack of a matching attestation are\nincluded in the `errors` field.\n',
      content: {
        'application/json': {
          schema: z
            .object({
              total_count: z
                .int()
                .openapi({ description: 'The number of deployment records created or updated.' }),
              deployment_records: z.array(ArtifactDeploymentRecordSchema).exactOptional(),
              errors: z
                .array(
                  z
                    .object({
                      cause: z
                        .enum(['unauthorized', 'not_found'])
                        .exactOptional()
                        .openapi({ description: 'The reason the deployment failed processing.' }),
                      deployment: z
                        .object({
                          name: z
                            .string()
                            .exactOptional()
                            .openapi({ description: 'The name of the artifact.' }),
                          digest: z
                            .string()
                            .exactOptional()
                            .openapi({ description: 'The digest of the artifact.' }),
                          deployment_name: z
                            .string()
                            .exactOptional()
                            .openapi({
                              description: 'The name of the deployment that failed processing.',
                            }),
                          version: z
                            .string()
                            .nullable()
                            .exactOptional()
                            .openapi({ description: 'The version of the deployment.' }),
                          status: z
                            .string()
                            .exactOptional()
                            .openapi({ description: 'The deployment status.' }),
                          github_repository: z
                            .string()
                            .nullable()
                            .exactOptional()
                            .openapi({
                              description: 'The repository associated with the deployment.',
                            }),
                          tags: z
                            .record(z.string(), z.string())
                            .exactOptional()
                            .openapi({ description: 'Custom metadata tags for the deployment.' }),
                          runtime_risks: z
                            .array(z.string())
                            .exactOptional()
                            .openapi({
                              description: 'Runtime risk classifications for the deployment.',
                            }),
                        })
                        .exactOptional()
                        .openapi({
                          description: 'The deployment payload that could not be processed.',
                          required: [],
                        }),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional()
                .openapi({
                  description: 'A list of errors for deployments that could not be processed.',
                }),
            })
            .openapi({ required: ['total_count'] }),
          examples: {
            partial_success: {
              value: {
                total_count: 1,
                deployment_records: [
                  {
                    id: 42,
                    digest:
                      'sha256:1bb1e949e55dcefc6353e7b36c8897d2a107d8e8dca49d4e3c0ea8493fc0bc72',
                    logical_environment: 'prod',
                    physical_environment: 'us-east-1a',
                    cluster: 'production-cluster',
                    deployment_name: 'deployment-pod',
                    tags: { 'owning-team': 'platform' },
                    runtime_risks: ['sensitive-data'],
                    created_at: '2024-01-01T12:00:00Z',
                    updated_at: '2024-01-01T12:30:00Z',
                    attestation_id: 777,
                  },
                ],
                errors: [
                  {
                    cause: 'unauthorized',
                    deployment: {
                      name: 'my-image',
                      digest:
                        'sha256:5aa19f9a13f67a644f6d8528e2eb5cf64431e236df5dbbd44ff9b9e3f6fc6cb2',
                      deployment_name: 'restricted-deployment',
                      version: '2.1.1',
                      status: 'deployed',
                      github_repository: 'private-repo',
                      tags: { 'owning-team': 'platform' },
                      runtime_risks: ['sensitive-data'],
                    },
                  },
                ],
              },
            },
          },
        },
      },
    },
    403: {
      description: 'Forbidden',
      content: {
        'application/json': {
          schema: BasicErrorSchema,
          examples: {
            insufficient_repo_permissions: {
              value: {
                message: {
                  cause: 'artifact metadata write permission required on one or more repositories',
                  repositories: [123, 345],
                },
              },
            },
          },
        },
      },
    },
    404: {
      description: 'Resource not found',
      content: {
        'application/json': {
          schema: BasicErrorSchema,
          examples: {
            not_found: {
              value: {
                message: {
                  cause: 'One or more repositories do not exist',
                  repositories: ['repoA', 'repoB'],
                },
              },
            },
          },
        },
      },
    },
  },
})

export const postOrgsOrgArtifactsMetadataDeploymentRecordClusterClusterJobsRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/artifacts/metadata/deployment-record/cluster/{cluster}/jobs',
  tags: ['orgs'],
  summary: 'Create a cluster deployment records job',
  description:
    'Create a background job to set deployment records for a given cluster.\nPerforms validation and permission checks synchronously, returning rejected\ndeployments immediately, then enqueues a background job for the actual\ndeployment updates. Use the companion GET endpoint to poll for job status.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/artifact-metadata#create-a-cluster-deployment-records-job',
  },
  operationId: 'orgs/create-cluster-deployment-records-job',
  request: {
    params: z.object({
      org: OrgParamsSchema,
      cluster: z
        .string()
        .regex(/^[a-zA-Z0-9._-]+$/)
        .min(1)
        .max(128)
        .openapi({
          param: {
            name: 'cluster',
            in: 'path',
            description: 'The cluster name.',
            required: true,
            schema: { type: 'string', minLength: 1, maxLength: 128, pattern: '^[a-zA-Z0-9._-]+$' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              logical_environment: z
                .string()
                .min(1)
                .max(128)
                .openapi({ description: 'The stage of the deployment.' }),
              physical_environment: z
                .string()
                .max(128)
                .exactOptional()
                .openapi({ description: 'The physical region of the deployment.' }),
              deployments: z
                .array(
                  z
                    .object({
                      name: z
                        .string()
                        .min(1)
                        .max(256)
                        .openapi({ description: 'The name of the artifact.' }),
                      digest: z
                        .string()
                        .regex(/^sha256:[a-f0-9]{64}$/)
                        .length(71)
                        .openapi({ description: 'The hex encoded digest of the artifact.' }),
                      version: z
                        .string()
                        .max(100)
                        .exactOptional()
                        .openapi({
                          description: 'The artifact version.',
                          'x-multi-segment': true,
                          example: '1.2.3',
                        }),
                      status: z
                        .enum(['deployed', 'decommissioned'])
                        .default('deployed')
                        .exactOptional()
                        .openapi({ description: 'The deployment status of the artifact.' }),
                      deployment_name: z
                        .string()
                        .min(1)
                        .max(256)
                        .openapi({
                          description:
                            'The unique identifier for the deployment represented by the new record.\n',
                        }),
                      github_repository: z
                        .string()
                        .regex(/^[A-Za-z0-9.\-_]+$/)
                        .max(100)
                        .exactOptional()
                        .openapi({
                          description:
                            'The name of the GitHub repository associated with the artifact.',
                          example: 'my-github-repo',
                        }),
                      tags: z
                        .record(z.string(), z.string())
                        .exactOptional()
                        .openapi({ description: 'Key-value pairs to tag the deployment record.' }),
                      runtime_risks: z
                        .array(
                          z.enum([
                            'critical-resource',
                            'internet-exposed',
                            'lateral-movement',
                            'sensitive-data',
                          ]),
                        )
                        .max(4)
                        .superRefine((items, ctx) => {
                          const seen = new Map()
                          for (const [i, val] of items.entries()) {
                            const key = JSON.stringify(val)
                            if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                            else seen.set(key, i)
                          }
                        })
                        .exactOptional()
                        .openapi({
                          description: 'A list of runtime risks associated with the deployment.',
                        }),
                    })
                    .openapi({ required: ['name', 'deployment_name', 'digest'] }),
                )
                .max(5000)
                .openapi({ description: 'The list of deployments to record.' }),
            })
            .openapi({ required: ['logical_environment', 'deployments'] }),
          examples: {
            default: {
              value: {
                logical_environment: 'prod',
                physical_environment: 'pacific-east',
                deployments: [
                  {
                    name: 'awesome-image',
                    digest:
                      'sha256:1bb1e949e55dcefc6353e7b36c8897d2a107d8e8dca49d4e3c0ea8493fc0bc72',
                    version: '2.1.0',
                    status: 'deployed',
                    deployment_name: 'deployment-pod',
                    tags: { 'owning-team': 'platform' },
                    runtime_risks: ['sensitive-data'],
                  },
                ],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    202: {
      description:
        'Job created successfully. Authorized deployments will be processed in the background.\n',
      content: {
        'application/json': {
          schema: z
            .object({
              job_id: z.int().openapi({ description: 'The ID of the created job.' }),
              errors: z
                .array(z.object({}))
                .exactOptional()
                .openapi({ description: 'Deployments that were rejected during authorization.' }),
            })
            .openapi({ required: ['job_id'] }),
          examples: { default: { value: { job_id: 123 } } },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: BasicErrorSchema } },
    },
    403: {
      description: 'Forbidden',
      content: { 'application/json': { schema: BasicErrorSchema } },
    },
    404: {
      description: 'Resource not found',
      content: { 'application/json': { schema: BasicErrorSchema } },
    },
    409: {
      description: 'A job is already in progress for this cluster.',
      content: { 'application/json': { schema: BasicErrorSchema } },
    },
  },
})

export const getOrgsOrgArtifactsMetadataDeploymentRecordClusterClusterJobsJobIdRoute = createRoute({
  method: 'get',
  path: '/orgs/{org}/artifacts/metadata/deployment-record/cluster/{cluster}/jobs/{job_id}',
  tags: ['orgs'],
  summary: 'Get cluster deployment records job status',
  description: 'Get the status and results of a previously created cluster deployment records job.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/artifact-metadata#get-cluster-deployment-records-job-status',
  },
  operationId: 'orgs/get-cluster-deployment-records-job',
  request: {
    params: z.object({
      org: OrgParamsSchema,
      cluster: z
        .string()
        .regex(/^[a-zA-Z0-9._-]+$/)
        .min(1)
        .max(128)
        .openapi({
          param: {
            name: 'cluster',
            in: 'path',
            description: 'The cluster name.',
            required: true,
            schema: { type: 'string', minLength: 1, maxLength: 128, pattern: '^[a-zA-Z0-9._-]+$' },
          },
        }),
      job_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'job_id',
            in: 'path',
            description: 'The ID of the job.',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Job status retrieved successfully.\n',
      content: {
        'application/json': {
          schema: z
            .object({
              job_id: z.int().openapi({ description: 'The ID of the job.' }),
              status: z
                .enum(['pending', 'processing', 'completed', 'failed'])
                .openapi({ description: 'The current status of the job.' }),
              started_at: z.iso
                .datetime({ offset: true })
                .exactOptional()
                .openapi({
                  description:
                    'When the job started processing (only present when processing, completed, or failed).',
                }),
              total_count: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'The number of records successfully mutated (only present when completed).',
                }),
              errors: z
                .array(z.object({}))
                .exactOptional()
                .openapi({
                  description: 'Processing errors (only present when completed or failed).',
                }),
            })
            .openapi({ required: ['job_id', 'status'] }),
          examples: {
            default: {
              value: {
                job_id: 123,
                status: 'completed',
                started_at: '2026-06-10T12:00:00Z',
                total_count: 5,
              },
            },
          },
        },
      },
    },
    404: {
      description: 'Resource not found',
      content: { 'application/json': { schema: BasicErrorSchema } },
    },
  },
})

export const postOrgsOrgArtifactsMetadataStorageRecordRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/artifacts/metadata/storage-record',
  tags: ['orgs'],
  summary: 'Create artifact metadata storage record',
  description:
    'Create metadata storage records for artifacts associated with an organization.\nThis endpoint will create a new artifact storage record on behalf of any artifact matching the provided digest and\nassociated with a repository owned by the organization.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/artifact-metadata#create-artifact-metadata-storage-record',
  },
  operationId: 'orgs/create-artifact-storage-record',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z
                .string()
                .min(1)
                .max(256)
                .openapi({ description: 'The name of the artifact.', example: 'libfoo' }),
              digest: z
                .string()
                .regex(/^sha256:[a-f0-9]{64}$/)
                .length(71)
                .openapi({
                  description: 'The digest of the artifact (algorithm:hex-encoded-digest).',
                  example: 'sha256:0ecbaa601dba202129058746c7d8e3f282d0efb5fff0...',
                }),
              version: z
                .string()
                .min(1)
                .max(100)
                .exactOptional()
                .openapi({
                  description: 'The artifact version.',
                  'x-multi-segment': true,
                  example: '1.2.3',
                }),
              artifact_url: z
                .url()
                .regex(/^https:\/\//)
                .max(152)
                .exactOptional()
                .openapi({
                  description: 'The URL where the artifact is stored.',
                  example: 'https://reg.example.com/artifactory/bar/libfoo-1.2.3',
                }),
              path: z
                .url()
                .max(512)
                .exactOptional()
                .openapi({
                  description: 'The path of the artifact.',
                  example: 'com/github/bar/libfoo-1.2.3',
                }),
              registry_url: z
                .url()
                .regex(/^https:\/\//)
                .min(1)
                .max(256)
                .openapi({
                  description: 'The base URL of the artifact registry.',
                  example: 'https://reg.example.com/artifactory/',
                }),
              repository: z
                .string()
                .max(128)
                .exactOptional()
                .openapi({
                  description: 'The repository name within the registry.',
                  example: 'bar',
                }),
              status: z
                .enum(['active', 'eol', 'deleted'])
                .default('active')
                .exactOptional()
                .openapi({
                  description: 'The status of the artifact (e.g., active, inactive).',
                  example: 'active',
                }),
              github_repository: z
                .string()
                .regex(/^[A-Za-z0-9.\-_]+$/)
                .min(1)
                .max(100)
                .exactOptional()
                .openapi({
                  description:
                    'The name of the GitHub repository associated with the artifact. This should be used\nwhen there are no provenance attestations available for the artifact. The repository\nmust belong to the organization specified in the path parameter.\n\nIf a provenance attestation is available for the artifact, the API will use\nthe repository information from the attestation instead of this parameter.',
                  example: 'my-github-repo',
                }),
              return_records: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    'If true, the endpoint will return the created record in the response body.\n',
                }),
            })
            .openapi({ required: ['name', 'digest', 'registry_url'] }),
          examples: {
            default: {
              value: {
                name: 'libfoo',
                version: '1.2.3',
                digest: 'sha256:1bb1e949e55dcefc6353e7b36c8897d2a107d8e8dca49d4e3c0ea8493fc0bc72',
                artifact_url: 'https://reg.example.com/artifactory/bar/libfoo-1.2.3',
                registry_url: 'https://reg.example.com/artifactory/',
                repository: 'bar',
                status: 'active',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Artifact metadata storage record stored successfully.',
      content: {
        'application/json': {
          schema: z
            .object({
              total_count: z.int().openapi({ example: 1 }),
              storage_records: z
                .array(
                  z
                    .object({
                      id: z.int().exactOptional(),
                      name: z.string().exactOptional(),
                      digest: z.string().exactOptional(),
                      artifact_url: z.string().nullable().exactOptional(),
                      registry_url: z.string().exactOptional(),
                      repository: z.string().nullable().exactOptional(),
                      status: z.string().exactOptional(),
                      created_at: z.string().exactOptional(),
                      updated_at: z.string().exactOptional(),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
            })
            .openapi({ required: ['total_count'] }),
          examples: {
            default: {
              value: {
                total_count: 1,
                storage_records: [
                  {
                    name: 'libfoo',
                    digest:
                      'sha256:1bb1e949e55dcefc6353e7b36c8897d2a107d8e8dca49d4e3c0ea8493fc0bc72',
                    artifact_url: 'https://reg.example.com/artifactory/bar/libfoo-1.2.3',
                    registry_url: 'https://reg.example.com/artifactory/',
                    repository: 'bar',
                    status: 'active',
                    created_at: '2023-10-01T12:00:00Z',
                    updated_at: '2023-10-01T12:00:00Z',
                  },
                ],
              },
            },
          },
        },
      },
    },
    403: ForbiddenResponse,
    404: NotFoundResponse,
  },
})

