export const postOrgsOrgAttestationsBulkListRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/attestations/bulk-list',
  tags: ['orgs'],
  summary: 'List attestations by bulk subject digests',
  description:
    "List a collection of artifact attestations associated with any entry in a list of subject digests owned by an organization.\n\nThe collection of attestations returned by this endpoint is filtered according to the authenticated user's permissions; if the authenticated user cannot read a repository, the attestations associated with that repository will not be included in the response. In addition, when using a fine-grained access token the `attestations:read` permission is required.\n\n**Please note:** in order to offer meaningful security benefits, an attestation's signature and timestamps **must** be cryptographically verified, and the identity of the attestation signer **must** be validated. Attestations can be verified using the [GitHub CLI `attestation verify` command](https://cli.github.com/manual/gh_attestation_verify). For more information, see [our guide on how to use artifact attestations to establish a build's provenance](https://docs.github.com/actions/security-guides/using-artifact-attestations-to-establish-provenance-for-builds).",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/attestations#list-attestations-by-bulk-subject-digests',
  },
  operationId: 'orgs/list-attestations-bulk',
  request: {
    query: z.object({
      per_page: PerPageParamsSchema,
      before: PaginationBeforeParamsSchema,
      after: PaginationAfterParamsSchema,
    }),
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              subject_digests: z
                .array(z.string())
                .min(1)
                .max(1024)
                .openapi({ description: 'List of subject digests to fetch attestations for.' }),
              predicate_type: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Optional filter for fetching attestations with a given predicate type.\nThis option accepts `provenance`, `sbom`, `release`, or freeform text\nfor custom predicate types.',
                }),
            })
            .openapi({ required: ['subject_digests'] }),
          examples: {
            default: BulkSubjectDigestBodyExample,
            withPredicateType: BulkSubjectDigestBodyWithPredicateTypeExample,
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z
            .object({
              attestations_subject_digests: z
                .record(
                  z.string(),
                  z
                    .array(
                      z
                        .object({
                          bundle: z
                            .object({
                              mediaType: z.string().exactOptional(),
                              verificationMaterial: z.looseObject({}).exactOptional(),
                              dsseEnvelope: z.looseObject({}).exactOptional(),
                            })
                            .exactOptional()
                            .openapi({
                              description: 'The bundle of the attestation.',
                              required: [],
                            }),
                          repository_id: z.int().exactOptional(),
                          bundle_url: z.string().exactOptional(),
                        })
                        .openapi({ required: [] }),
                    )
                    .nullable(),
                )
                .exactOptional()
                .openapi({ description: 'Mapping of subject digest to bundles.' }),
              page_info: z
                .object({
                  has_next: z
                    .boolean()
                    .exactOptional()
                    .openapi({ description: 'Indicates whether there is a next page.' }),
                  has_previous: z
                    .boolean()
                    .exactOptional()
                    .openapi({ description: 'Indicates whether there is a previous page.' }),
                  next: z
                    .string()
                    .exactOptional()
                    .openapi({ description: 'The cursor to the next page.' }),
                  previous: z
                    .string()
                    .exactOptional()
                    .openapi({ description: 'The cursor to the previous page.' }),
                })
                .exactOptional()
                .openapi({ description: 'Information about the current page.', required: [] }),
            })
            .openapi({ required: [] }),
          examples: { default: ListAttestationsBulkExample },
        },
      },
    },
  },
})

