export const getOrgsOrgAttestationsSubjectDigestRoute = createRoute({
  method: 'get',
  path: '/orgs/{org}/attestations/{subject_digest}',
  tags: ['orgs'],
  summary: 'List attestations',
  description:
    "List a collection of artifact attestations with a given subject digest that are associated with repositories owned by an organization.\n\nThe collection of attestations returned by this endpoint is filtered according to the authenticated user's permissions; if the authenticated user cannot read a repository, the attestations associated with that repository will not be included in the response. In addition, when using a fine-grained access token the `attestations:read` permission is required.\n\n**Please note:** in order to offer meaningful security benefits, an attestation's signature and timestamps **must** be cryptographically verified, and the identity of the attestation signer **must** be validated. Attestations can be verified using the [GitHub CLI `attestation verify` command](https://cli.github.com/manual/gh_attestation_verify). For more information, see [our guide on how to use artifact attestations to establish a build's provenance](https://docs.github.com/actions/security-guides/using-artifact-attestations-to-establish-provenance-for-builds).",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/attestations#list-attestations',
  },
  operationId: 'orgs/list-attestations',
  request: {
    query: z.object({
      per_page: PerPageParamsSchema,
      before: PaginationBeforeParamsSchema,
      after: PaginationAfterParamsSchema,
      predicate_type: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'predicate_type',
            description:
              'Optional filter for fetching attestations with a given predicate type.\nThis option accepts `provenance`, `sbom`, `release`, or freeform text\nfor custom predicate types.',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
    params: z.object({
      org: OrgParamsSchema,
      subject_digest: z
        .string()
        .openapi({
          param: {
            name: 'subject_digest',
            description:
              "The parameter should be set to the attestation's subject's SHA256 digest, in the form `sha256:HEX_DIGEST`.",
            in: 'path',
            required: true,
            schema: { type: 'string' },
            'x-multi-segment': true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z
            .object({
              attestations: z
                .array(
                  z
                    .object({
                      bundle: z
                        .object({
                          mediaType: z.string().exactOptional(),
                          verificationMaterial: z.looseObject({}).exactOptional(),
                          dsseEnvelope: z.looseObject({}).exactOptional(),
                        })
                        .nullable()
                        .exactOptional()
                        .openapi({
                          description:
                            "The attestation's Sigstore Bundle.\nRefer to the [Sigstore Bundle Specification](https://github.com/sigstore/protobuf-specs/blob/main/protos/sigstore_bundle.proto) for more information.",
                          required: [],
                        }),
                      repository_id: z.int().exactOptional(),
                      bundle_url: z.string().exactOptional(),
                      initiator: z.string().exactOptional(),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
          examples: { default: ListAttestationsExample },
        },
      },
    },
  },
})

