export const postOrgsOrgCampaignsRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/campaigns',
  tags: ['campaigns'],
  summary: 'Create a campaign for an organization',
  description:
    'Create a campaign for an organization.\n\nThe authenticated user must be an owner or security manager for the organization to use this endpoint.\n\nOAuth app tokens and personal access tokens (classic) need the `security_events` scope to use this endpoint.\n\nFine-grained tokens must have the "Code scanning alerts" repository permissions (read) on all repositories included\nin the campaign.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/campaigns/campaigns#create-a-campaign-for-an-organization',
  },
  operationId: 'campaigns/create-campaign',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .xor([
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'code_scanning_alerts')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['code_scanning_alerts'] }),
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'secret_scanning_alerts')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['secret_scanning_alerts'] }),
            ])
            .openapi({ required: ['name', 'description', 'ends_at'] }),
          examples: {
            default: {
              value: {
                name: 'Critical CodeQL alerts',
                description:
                  'Address critical alerts before they are exploited to prevent breaches, protect sensitive data, and mitigate financial and reputational damage.',
                managers: ['octocat'],
                ends_at: '2024-03-14T00:00:00Z',
                code_scanning_alerts: [{ repository_id: 1296269, alert_numbers: [1, 2] }],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: CampaignSummarySchema,
          examples: { default: CampaignSummaryExample },
        },
      },
    },
    400: {
      description: 'Bad Request',
      content: { 'application/json': { schema: BasicErrorSchema } },
    },
    404: NotFoundResponse,
    422: {
      description: 'Unprocessable Entity',
      content: { 'application/json': { schema: BasicErrorSchema } },
    },
    429: { description: 'Too Many Requests' },
    503: ServiceUnavailableResponse,
  },
})

