export const deleteOrgsOrgCodeSecurityConfigurationsDetachRoute = createRoute({
  method: 'delete',
  path: '/orgs/{org}/code-security/configurations/detach',
  tags: ['code-security'],
  summary: 'Detach configurations from repositories',
  description:
    "Detach code security configuration(s) from a set of repositories.\nRepositories will retain their settings but will no longer be associated with the configuration.\n\nThe authenticated user must be an administrator or security manager for the organization to use this endpoint.\n\nRepositories with active enterprise-enforced attachments are skipped unless the authenticated user can manage the enterprise's code security settings; the rest are detached. Inactive enterprise-enforced attachments, such as failed attachments, are detached. The request still returns `204` if every repository is skipped.\n\nOAuth app tokens and classic PATs require the `write:org` scope. Managing enterprise-enforced configurations also requires `admin:enterprise` and is not supported by fine-grained PATs or GitHub App access tokens.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/code-security/configurations#detach-configurations-from-repositories',
  },
  operationId: 'code-security/detach-configuration',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              selected_repository_ids: z
                .array(z.int().openapi({ description: 'Unique identifier of the repository.' }))
                .min(1)
                .max(250)
                .openapi({
                  description:
                    'An array of repository IDs to detach from configurations. Up to 250 IDs can be provided.',
                }),
            })
            .openapi({ required: ['selected_repository_ids'] }),
          examples: {
            default: {
              summary: 'Example for detaching repositories from configurations.',
              value: { selected_repository_ids: [32, 91] },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    204: NoContentResponse,
    400: BadRequestResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    409: ConflictResponse,
  },
})

