export const putOrgsOrgCodespacesAccessRoute = createRoute({
  method: 'put',
  path: '/orgs/{org}/codespaces/access',
  tags: ['codespaces'],
  summary: 'Manage access control for organization codespaces',
  description:
    'Sets which users can access codespaces in an organization. This is synonymous with granting or revoking codespaces access permissions for users according to the visibility.\nOAuth app tokens and personal access tokens (classic) need the `admin:org` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/codespaces/organizations#manage-access-control-for-organization-codespaces',
  },
  operationId: 'codespaces/set-codespaces-access',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              visibility: z
                .enum([
                  'disabled',
                  'selected_members',
                  'all_members',
                  'all_members_and_outside_collaborators',
                ])
                .openapi({
                  description:
                    'Which users can access codespaces in the organization. `disabled` means that no users can access codespaces in the organization.',
                }),
              selected_usernames: z
                .array(z.string())
                .max(100)
                .exactOptional()
                .openapi({
                  description:
                    'The usernames of the organization members who should have access to codespaces in the organization. Required when `visibility` is `selected_members`. The provided list of usernames will replace any existing value.',
                }),
            })
            .openapi({ required: ['visibility'] }),
          examples: {
            default: {
              value: { visibility: 'selected_members', selected_usernames: ['johnDoe', 'atomIO'] },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    204: { description: 'Response when successfully modifying permissions.' },
    304: NotModifiedResponse,
    400: { description: 'Users are neither members nor collaborators of this organization.' },
    404: NotFoundResponse,
    422: ValidationFailedResponse,
    500: InternalErrorResponse,
  },
  deprecated: true,
})

