export const postOrgsOrgCopilotSpacesSpaceNumberResourcesRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/copilot-spaces/{space_number}/resources',
  tags: ['copilot-spaces'],
  summary: 'Create a resource for an organization Copilot Space',
  description:
    'Creates a new resource in a specific Copilot Space owned by an organization.\nThe authenticated user must have write permissions on the space.\n\nThe following resource types are supported: `repository`, `github_file`, `free_text`, `github_issue`, `github_pull_request`.\nThe `uploaded_text_file` and `media_content` types are not supported via this endpoint.\n\nFor `github_file` resources, if a resource with the same repository, file path, and SHA already exists, the existing resource is returned with a `200` status.\n\nOAuth app tokens and personal access tokens (classic) need the `write:org` scope to use this endpoint.\n\nFine-grained tokens and GitHub App user access tokens must have been granted access to the organization that owns the space. They must also have been granted access to every repository referenced by resources in the space, including the resource being created.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/copilot-spaces/resources#create-a-resource-for-an-organization-copilot-space',
  },
  operationId: 'copilot-spaces/create-resource-for-org',
  request: {
    params: z.object({
      org: OrgParamsSchema,
      space_number: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'space_number',
            description: 'The unique identifier of the Copilot Space.',
            in: 'path',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              resource_type: z
                .enum([
                  'repository',
                  'github_file',
                  'free_text',
                  'github_issue',
                  'github_pull_request',
                ])
                .openapi({ description: 'The type of resource to create.' }),
              metadata: z.looseObject({}).openapi({ description: 'Resource-specific metadata.' }),
            })
            .openapi({ required: ['resource_type', 'metadata'] }),
          examples: {
            free_text: {
              value: {
                resource_type: 'free_text',
                metadata: { name: 'notes.txt', text: 'Some helpful notes' },
              },
            },
            repository: { value: { resource_type: 'repository', metadata: { repository_id: 42 } } },
            github_file: {
              value: {
                resource_type: 'github_file',
                metadata: { repository_id: 42, file_path: 'README.md', sha: 'abc123' },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Duplicate github_file resource already exists',
      content: {
        'application/json': {
          schema: CopilotSpaceResourceSchema,
          examples: {
            default: {
              value: {
                id: 1,
                resource_type: 'github_file',
                copilot_chat_attachment_id: null,
                metadata: { repository_id: 42, file_path: 'README.md', sha: 'abc123' },
                created_at: '2025-01-01T00:00:00Z',
                updated_at: '2025-01-01T00:00:00Z',
              },
            },
          },
        },
      },
    },
    201: {
      description: 'Resource created',
      content: {
        'application/json': {
          schema: CopilotSpaceResourceSchema,
          examples: {
            default: {
              value: {
                id: 1,
                resource_type: 'free_text',
                copilot_chat_attachment_id: null,
                metadata: { name: 'notes.txt', text: 'Some helpful notes' },
                created_at: '2025-01-01T00:00:00Z',
                updated_at: '2025-01-01T00:00:00Z',
              },
            },
          },
        },
      },
    },
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

