export const getOrgsOrgCopilotCodingAgentPermissionsRoute = createRoute({
  method: 'get',
  path: '/orgs/{org}/copilot/coding-agent/permissions',
  tags: ['copilot'],
  summary: 'Get Copilot cloud agent permissions for an organization',
  description:
    '> [!NOTE]\n> This endpoint is in public preview and is subject to change.\n\nGets information about which repositories in an organization have been enabled\nor disabled for the Copilot cloud agent.\n\nOrganization owners can configure whether Copilot cloud agent is enabled for\nall repositories, selected repositories, or no repositories owned by organization.\n\nOAuth app tokens and personal access tokens (classic) need the `admin:org` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/copilot/copilot-coding-agent-management#get-copilot-cloud-agent-permissions-for-an-organization',
  },
  operationId: 'copilot/get-copilot-coding-agent-permissions-organization',
  request: { params: z.object({ org: OrgParamsSchema }) },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z
            .object({
              enabled_repositories: z
                .enum(['all', 'selected', 'none'])
                .openapi({
                  description:
                    'The policy for which repositories can use Copilot cloud agent. Can be one of `all`, `selected`, or `none`.',
                }),
              selected_repositories_url: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The URL for the selected repositories endpoint. Only present when `enabled_repositories` is `selected`.',
                }),
            })
            .openapi({ required: ['enabled_repositories'] }),
          examples: {
            all_enabled: {
              summary: 'All repositories enabled',
              value: { enabled_repositories: 'all' },
            },
            selected_enabled: {
              summary: 'Selected repositories enabled',
              value: {
                enabled_repositories: 'selected',
                selected_repositories_url:
                  'https://api.github.com/orgs/my-org/copilot/coding-agent/permissions/repositories',
              },
            },
            none_enabled: {
              summary: 'No repositories enabled',
              value: { enabled_repositories: 'none' },
            },
          },
        },
      },
    },
    401: RequiresAuthenticationResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    500: InternalErrorResponse,
  },
})

