export const putOrgsOrgDependabotSecretsSecretNameRoute = createRoute({
  method: 'put',
  path: '/orgs/{org}/dependabot/secrets/{secret_name}',
  tags: ['dependabot'],
  summary: 'Create or update an organization secret',
  description:
    'Creates or updates an organization secret with an encrypted value. Encrypt your secret using\n[LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages). For more information, see "[Encrypting secrets for the REST API](https://docs.github.com/rest/guides/encrypting-secrets-for-the-rest-api)."\n\nOAuth app tokens and personal access tokens (classic) need the `admin:org` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/dependabot/secrets#create-or-update-an-organization-secret',
  },
  operationId: 'dependabot/create-or-update-org-secret',
  request: {
    params: z.object({ org: OrgParamsSchema, secret_name: SecretNameParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              encrypted_value: z
                .string()
                .regex(
                  /^(?:[A-Za-z0-9+\/]{4})*(?:[A-Za-z0-9+\/]{2}==|[A-Za-z0-9+\/]{3}=|[A-Za-z0-9+\/]{4})$/,
                )
                .exactOptional()
                .openapi({
                  description:
                    'Value for your secret, encrypted with [LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages) using the public key retrieved from the [Get an organization public key](https://docs.github.com/rest/dependabot/secrets#get-an-organization-public-key) endpoint.',
                }),
              key_id: z
                .string()
                .exactOptional()
                .openapi({ description: 'ID of the key you used to encrypt the secret.' }),
              visibility: z
                .enum(['all', 'private', 'selected'])
                .openapi({
                  description:
                    'Which type of organization repositories have access to the organization secret. `selected` means only the repositories specified by `selected_repository_ids` can access the secret.',
                }),
              selected_repository_ids: z
                .array(z.union([z.int(), z.string()]))
                .exactOptional()
                .openapi({
                  description:
                    'An array of repository ids that can access the organization secret. You can only provide a list of repository ids when the `visibility` is set to `selected`. You can manage the list of selected repositories using the [List selected repositories for an organization secret](https://docs.github.com/rest/dependabot/secrets#list-selected-repositories-for-an-organization-secret), [Set selected repositories for an organization secret](https://docs.github.com/rest/dependabot/secrets#set-selected-repositories-for-an-organization-secret), and [Remove selected repository from an organization secret](https://docs.github.com/rest/dependabot/secrets#remove-selected-repository-from-an-organization-secret) endpoints.',
                }),
            })
            .openapi({ required: ['visibility'] }),
          examples: {
            default: {
              value: {
                encrypted_value: 'c2VjcmV0',
                key_id: '012345678912345678',
                visibility: 'selected',
                selected_repository_ids: [1296269, 1296280],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response when creating a secret',
      content: {
        'application/json': { schema: EmptyObjectSchema, examples: { default: { value: null } } },
      },
    },
    204: { description: 'Response when updating a secret' },
  },
})

