export const putOrgsOrgDependabotSecretsSecretNameRepositoriesRepositoryIdRoute = createRoute({
  method: 'put',
  path: '/orgs/{org}/dependabot/secrets/{secret_name}/repositories/{repository_id}',
  tags: ['dependabot'],
  summary: 'Add selected repository to an organization secret',
  description:
    'Adds a repository to an organization secret when the `visibility` for\nrepository access is set to `selected`. The visibility is set when you [Create or\nupdate an organization secret](https://docs.github.com/rest/dependabot/secrets#create-or-update-an-organization-secret).\n\nOAuth app tokens and personal access tokens (classic) need the `admin:org` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/dependabot/secrets#add-selected-repository-to-an-organization-secret',
  },
  operationId: 'dependabot/add-selected-repo-to-org-secret',
  request: {
    params: z.object({
      org: OrgParamsSchema,
      secret_name: SecretNameParamsSchema,
      repository_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: { name: 'repository_id', in: 'path', required: true, schema: { type: 'integer' } },
        }),
    }),
  },
  responses: {
    204: { description: 'No Content when repository was added to the selected list' },
    409: { description: 'Conflict when visibility type is not set to selected' },
  },
})

