export const patchOrgsOrgHooksHookIdRoute = createRoute({
  method: 'patch',
  path: '/orgs/{org}/hooks/{hook_id}',
  tags: ['orgs'],
  summary: 'Update an organization webhook',
  description:
    'Updates a webhook configured in an organization. When you update a webhook,\nthe `secret` will be overwritten. If you previously had a `secret` set, you must\nprovide the same `secret` or set a new `secret` or the secret will be removed. If\nyou are only updating individual webhook `config` properties, use "[Update a webhook\nconfiguration for an organization](/rest/orgs/webhooks#update-a-webhook-configuration-for-an-organization)".\n\nYou must be an organization owner to use this endpoint.\n\nOAuth app tokens and personal access tokens (classic) need `admin:org_hook` scope. OAuth apps cannot list, view, or edit\nwebhooks that they did not create and users cannot list, view, or edit webhooks that were created by OAuth apps.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/webhooks#update-an-organization-webhook',
  },
  operationId: 'orgs/update-webhook',
  request: {
    params: z.object({ org: OrgParamsSchema, hook_id: HookIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              config: z
                .object({
                  url: WebhookConfigUrlSchema,
                  content_type: WebhookConfigContentTypeSchema.exactOptional(),
                  secret: WebhookConfigSecretSchema.exactOptional(),
                  insecure_ssl: WebhookConfigInsecureSslSchema.exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description: 'Key/value pairs to provide settings for this webhook.',
                  required: ['url'],
                }),
              events: z
                .array(z.string())
                .default(['push'])
                .exactOptional()
                .openapi({
                  description:
                    'Determines what [events](https://docs.github.com/webhooks/event-payloads) the hook is triggered for.',
                }),
              active: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    'Determines if notifications are sent when the webhook is triggered. Set to `true` to send notifications.',
                }),
              name: z.string().exactOptional().openapi({ example: '"web"' }),
            })
            .openapi({ required: [] }),
          examples: { default: { value: { active: true, events: ['pull_request'] } } },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': { schema: OrgHookSchema, examples: { default: OrgHook_2Example } },
      },
    },
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

