export const getOrgsOrgInteractionLimitsPullsCreationCapRoute = createRoute({
  method: 'get',
  path: '/orgs/{org}/interaction-limits/pulls/creation-cap',
  tags: ['interactions'],
  summary: 'Get pull request creation cap for an org',
  description:
    'Gets the pull request creation cap configuration for an organization.\nThe cap limits the total number of open pull requests a user can have across all public\nrepositories in the organization at one time.\n\nOnly users with admin access to the organization can view the cap configuration.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/interactions/orgs#get-pull-request-creation-cap-for-an-org',
  },
  operationId: 'interactions/get-pull-request-creation-cap-for-org',
  request: { params: z.object({ org: OrgParamsSchema }) },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z
            .object({
              enabled: z
                .boolean()
                .openapi({ description: 'Whether the pull request creation cap is enabled' }),
              max_open_pull_requests: z
                .int()
                .min(1)
                .max(1000)
                .openapi({
                  description:
                    'The maximum number of open pull requests a user can have at one time',
                }),
              include_drafts: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Whether draft pull requests count toward the pull request creation cap',
                }),
            })
            .openapi({ required: ['enabled', 'max_open_pull_requests'] }),
          examples: {
            default: {
              summary: 'Response when cap is enabled',
              value: { enabled: true, max_open_pull_requests: 1 },
            },
          },
        },
      },
    },
    403: ForbiddenResponse,
    404: NotFoundResponse,
    405: {
      description: 'Method Not Allowed',
      content: { 'application/json': { schema: BasicErrorSchema } },
    },
  },
})

