export const putOrgsOrgOutsideCollaboratorsUsernameRoute = createRoute({
  method: 'put',
  path: '/orgs/{org}/outside_collaborators/{username}',
  tags: ['orgs'],
  summary: 'Convert an organization member to outside collaborator',
  description:
    'When an organization member is converted to an outside collaborator, they\'ll only have access to the repositories that their current team membership allows. The user will no longer be a member of the organization. For more information, see "[Converting an organization member to an outside collaborator](https://docs.github.com/articles/converting-an-organization-member-to-an-outside-collaborator/)". Converting an organization member to an outside collaborator may be restricted by enterprise administrators. For more information, see "[Enforcing repository management policies in your enterprise](https://docs.github.com/admin/policies/enforcing-policies-for-your-enterprise/enforcing-repository-management-policies-in-your-enterprise#enforcing-a-policy-for-inviting-outside-collaborators-to-repositories)."',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/outside-collaborators#convert-an-organization-member-to-outside-collaborator',
  },
  operationId: 'orgs/convert-member-to-outside-collaborator',
  request: {
    params: z.object({ org: OrgParamsSchema, username: UsernameParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              async: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'When set to `true`, the request will be performed asynchronously. Returns a 202 status code when the job is successfully queued.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            '202': { summary: 'Status code 202, asynchronous request', value: { async: true } },
            '204': { summary: 'Status code 204, synchronous request', value: null },
          },
        },
      },
    },
  },
  responses: {
    202: {
      description: 'User is getting converted asynchronously',
      content: {
        'application/json': { schema: z.strictObject({}), examples: { '202': { value: null } } },
      },
    },
    204: { description: 'User was converted' },
    403: {
      description:
        'Forbidden if user is the last owner of the organization, not a member of the organization, or if the enterprise enforces a policy for inviting outside collaborators. For more information, see "[Enforcing repository management policies in your enterprise](https://docs.github.com/admin/policies/enforcing-policies-for-your-enterprise/enforcing-repository-management-policies-in-your-enterprise#enforcing-a-policy-for-inviting-outside-collaborators-to-repositories)."',
    },
    404: NotFoundResponse,
  },
})

