export const postOrgsOrgPersonalAccessTokenRequestsRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/personal-access-token-requests',
  tags: ['orgs'],
  summary:
    'Review requests to access organization resources with fine-grained personal access tokens',
  description:
    'Approves or denies multiple pending requests to access organization resources via a fine-grained personal access token.\n\nOnly GitHub Apps can use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/personal-access-tokens#review-requests-to-access-organization-resources-with-fine-grained-personal-access-tokens',
  },
  operationId: 'orgs/review-pat-grant-requests-in-bulk',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              pat_request_ids: z
                .array(z.int())
                .min(1)
                .max(100)
                .exactOptional()
                .openapi({
                  description:
                    'Unique identifiers of the requests for access via fine-grained personal access token. Must be formed of between 1 and 100 `pat_request_id` values.',
                }),
              action: z
                .enum(['approve', 'deny'])
                .openapi({ description: 'Action to apply to the requests.' }),
              reason: z
                .string()
                .max(1024)
                .nullable()
                .exactOptional()
                .openapi({
                  description: 'Reason for approving or denying the requests. Max 1024 characters.',
                }),
            })
            .openapi({ required: ['action'] }),
          examples: {
            '204': {
              summary: 'Example of denying a request',
              value: { pat_request_ids: [42, 73], action: 'deny', reason: 'Access is too broad.' },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    202: AcceptedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
    500: InternalErrorResponse,
  },
})

export const postOrgsOrgPersonalAccessTokenRequestsPatRequestIdRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/personal-access-token-requests/{pat_request_id}',
  tags: ['orgs'],
  summary:
    'Review a request to access organization resources with a fine-grained personal access token',
  description:
    'Approves or denies a pending request to access organization resources via a fine-grained personal access token.\n\nOnly GitHub Apps can use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/personal-access-tokens#review-a-request-to-access-organization-resources-with-a-fine-grained-personal-access-token',
  },
  operationId: 'orgs/review-pat-grant-request',
  request: {
    params: z.object({
      org: OrgParamsSchema,
      pat_request_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'pat_request_id',
            in: 'path',
            description:
              'Unique identifier of the request for access via fine-grained personal access token.',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              action: z
                .enum(['approve', 'deny'])
                .openapi({ description: 'Action to apply to the request.' }),
              reason: z
                .string()
                .max(1024)
                .nullable()
                .exactOptional()
                .openapi({
                  description: 'Reason for approving or denying the request. Max 1024 characters.',
                }),
            })
            .openapi({ required: ['action'] }),
          examples: {
            '204': {
              summary: 'Example of denying a request',
              value: {
                action: 'deny',
                reason: 'This request is denied because the access is too broad.',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    204: NoContentResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
    500: InternalErrorResponse,
  },
})

