export const getOrgsOrgPersonalAccessTokensPatIdRepositoriesRoute = createRoute({
  method: 'get',
  path: '/orgs/{org}/personal-access-tokens/{pat_id}/repositories',
  tags: ['orgs'],
  summary: 'List repositories a fine-grained personal access token has access to',
  description:
    'Lists the repositories a fine-grained personal access token has access to.\n\nOnly GitHub Apps can use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/personal-access-tokens#list-repositories-a-fine-grained-personal-access-token-has-access-to',
  },
  operationId: 'orgs/list-pat-grant-repositories',
  request: {
    params: z.object({
      org: OrgParamsSchema,
      pat_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'pat_id',
            in: 'path',
            description: 'Unique identifier of the fine-grained personal access token.',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
    query: z.object({ per_page: PerPageParamsSchema, page: PageParamsSchema }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z.array(MinimalRepositorySchema),
          examples: { default: MinimalRepositoryItemsExample },
        },
      },
      headers: z.object({ Link: LinkHeaderSchema }),
    },
    403: ForbiddenResponse,
    404: NotFoundResponse,
    500: InternalErrorResponse,
  },
})

