export const postOrgsOrgPropertiesInstallationsRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/properties/installations',
  tags: ['orgs'],
  summary: 'Register an app installation for external custom properties',
  description:
    "Registers a GitHub App installation so it can read and write external custom properties for an organization, and assigns it a display name.\n\nThe display name must be 1 to 15 characters and contain only letters and numbers. Capitalization is preserved as entered.\n\nAn app installation can only be registered once, and its display name can't be changed afterward. Calling with an app installation that has already been registered returns a `422` response with an `already_exists` error code for `installation_id`. If the display name is already in use by another app installation in the organization, the response is `422` with an `already_exists` error code for `display_name`. An invalid display name also returns `422`.\n\nThe app installation being registered must have write or admin permission for organization external custom properties for repositories. If it doesn't, the response is `422`. This is the permission of the installation being registered, which isn't necessarily the caller.\n\nUninstalling the GitHub App unregisters it, and removes the external custom properties it created.\n\nTo use this endpoint, the authenticated caller must have the `organization_external_properties_for_repos:admin` permission.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/custom-properties#register-an-app-installation-for-external-custom-properties',
  },
  operationId: 'orgs/external-properties-for-repos-register-organization-app-installation',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              installation_id: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'The unique identifier of the GitHub App installation to register for managing external custom properties. When authenticating as a GitHub App installation, this defaults to the authenticated installation and can be omitted. It is required for all other callers (users and fine-grained personal access tokens).',
                }),
              display_name: z
                .string()
                .regex(/^[a-zA-Z0-9]+$/)
                .min(1)
                .max(15)
                .openapi({
                  description:
                    "The display name for this app installation's external custom properties in the organization. Must be 1 to 15 characters and contain only letters and numbers. Capitalization is preserved as entered. This can't be changed after the app installation is registered.",
                }),
            })
            .openapi({ required: ['display_name'] }),
          examples: { default: { value: { installation_id: 67890, display_name: 'Acme' } } },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: OrganizationExternalPropertyInstallationSchema,
          examples: { default: OrganizationExternalPropertyInstallationExample },
        },
      },
    },
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

