export const postOrgsOrgReposRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/repos',
  tags: ['repos'],
  summary: 'Create an organization repository',
  description:
    'Creates a new repository in the specified organization. The authenticated user must be a member of the organization.\n\nOAuth app tokens and personal access tokens (classic) need the `public_repo` or `repo` scope to create a public repository, and `repo` scope to create a private repository.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/repos/repos#create-an-organization-repository',
  },
  operationId: 'repos/create-in-org',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z.string().openapi({ description: 'The name of the repository.' }),
              description: z
                .string()
                .exactOptional()
                .openapi({ description: 'A short description of the repository.' }),
              homepage: z
                .string()
                .exactOptional()
                .openapi({ description: 'A URL with more information about the repository.' }),
              private: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({ description: 'Whether the repository is private.' }),
              visibility: z
                .enum(['public', 'private'])
                .exactOptional()
                .openapi({ description: 'The visibility of the repository.' }),
              has_issues: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    'Either `true` to enable issues for this repository or `false` to disable them.',
                }),
              has_projects: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    "Either `true` to enable projects for this repository or `false` to disable them. **Note:** If you're creating a repository in an organization that has disabled repository projects, the default is `false`, and if you pass `true`, the API returns an error.",
                }),
              has_wiki: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    'Either `true` to enable the wiki for this repository or `false` to disable it.',
                }),
              has_downloads: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({ description: 'Whether downloads are enabled.', example: true }),
              is_template: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Either `true` to make this repo available as a template repository or `false` to prevent it.',
                }),
              team_id: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'The id of the team that will be granted access to this repository. This is only valid when creating a repository in an organization.',
                }),
              auto_init: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description: 'Pass `true` to create an initial commit with empty README.',
                }),
              gitignore_template: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Desired language or platform [.gitignore template](https://github.com/github/gitignore) to apply. Use the name of the template without the extension. For example, "Haskell".',
                }),
              license_template: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Choose an [open source license template](https://choosealicense.com/) that best suits your needs, and then use the [license keyword](https://docs.github.com/articles/licensing-a-repository/#searching-github-by-license-type) as the `license_template` string. For example, "mit" or "mpl-2.0".',
                }),
              allow_squash_merge: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    'Either `true` to allow squash-merging pull requests, or `false` to prevent squash-merging.',
                }),
              allow_merge_commit: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    'Either `true` to allow merging pull requests with a merge commit, or `false` to prevent merging pull requests with merge commits.',
                }),
              allow_rebase_merge: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    'Either `true` to allow rebase-merging pull requests, or `false` to prevent rebase-merging.',
                }),
              allow_auto_merge: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Either `true` to allow auto-merge on pull requests, or `false` to disallow auto-merge.',
                }),
              delete_branch_on_merge: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Either `true` to allow automatically deleting head branches when pull requests are merged, or `false` to prevent automatic deletion. **The authenticated user must be an organization owner to set this property to `true`.**',
                }),
              use_squash_pr_title_as_default: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Either `true` to allow squash-merge commits to use pull request title, or `false` to use commit message. **This property is closing down. Please use `squash_merge_commit_title` instead.',
                  deprecated: true,
                }),
              squash_merge_commit_title: z
                .enum(['PR_TITLE', 'COMMIT_OR_PR_TITLE'])
                .exactOptional()
                .openapi({
                  description:
                    "Required when using `squash_merge_commit_message`.\n\nThe default value for a squash merge commit title:\n\n- `PR_TITLE` - default to the pull request's title.\n- `COMMIT_OR_PR_TITLE` - default to the commit's title (if only one commit) or the pull request's title (when more than one commit).",
                }),
              squash_merge_commit_message: z
                .enum(['PR_BODY', 'COMMIT_MESSAGES', 'BLANK'])
                .exactOptional()
                .openapi({
                  description:
                    "The default value for a squash merge commit message:\n\n- `PR_BODY` - default to the pull request's body.\n- `COMMIT_MESSAGES` - default to the branch's commit messages.\n- `BLANK` - default to a blank commit message.",
                }),
              merge_commit_title: z
                .enum(['PR_TITLE', 'MERGE_MESSAGE'])
                .exactOptional()
                .openapi({
                  description:
                    "Required when using `merge_commit_message`.\n\nThe default value for a merge commit title.\n\n- `PR_TITLE` - default to the pull request's title.\n- `MERGE_MESSAGE` - default to the classic title for a merge message (e.g., Merge pull request #123 from branch-name).",
                }),
              merge_commit_message: z
                .enum(['PR_BODY', 'PR_TITLE', 'BLANK'])
                .exactOptional()
                .openapi({
                  description:
                    "The default value for a merge commit message.\n\n- `PR_TITLE` - default to the pull request's title.\n- `PR_BODY` - default to the pull request's body.\n- `BLANK` - default to a blank commit message.",
                }),
              custom_properties: z
                .looseObject({})
                .exactOptional()
                .openapi({
                  description:
                    'The custom properties for the new repository. The keys are the custom property names, and the values are the corresponding custom property values.',
                }),
            })
            .openapi({ required: ['name'] }),
          examples: {
            default: {
              value: {
                name: 'Hello-World',
                description: 'This is your first repository',
                homepage: 'https://github.com',
                private: false,
                has_issues: true,
                has_projects: true,
                has_wiki: true,
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: FullRepositorySchema,
          examples: { default: FullRepositoryExample },
        },
      },
      headers: z.object({
        Location: {
          example: 'https://api.github.com/repos/octocat/Hello-World',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              example: 'https://api.github.com/repos/octocat/Hello-World',
              param: { required: false },
            }),
        },
      }),
    },
    403: ForbiddenResponse,
    422: ValidationFailedResponse,
  },
})

