export const postOrgsOrgRulesetsRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/rulesets',
  tags: ['repos'],
  summary: 'Create an organization repository ruleset',
  description: 'Create a repository ruleset for an organization.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/rules#create-an-organization-repository-ruleset',
  },
  operationId: 'repos/create-org-ruleset',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      description: 'Request body',
      content: {
        'application/json': {
          schema: z
            .object({
              name: z.string().openapi({ description: 'The name of the ruleset.' }),
              target: z
                .enum(['branch', 'tag', 'push', 'repository'])
                .default('branch')
                .exactOptional()
                .openapi({ description: 'The target of the ruleset' }),
              enforcement: RepositoryRuleEnforcementSchema,
              bypass_actors: z
                .array(RepositoryRulesetBypassActorSchema)
                .exactOptional()
                .openapi({ description: 'The actors that can bypass the rules in this ruleset' }),
              conditions: OrgRulesetConditionsSchema.exactOptional(),
              rules: z
                .array(OrgRulesSchema)
                .exactOptional()
                .openapi({ description: 'An array of rules within the ruleset.' }),
            })
            .openapi({ required: ['name', 'enforcement'] }),
          examples: {
            default: {
              value: {
                name: 'super cool ruleset',
                target: 'branch',
                enforcement: 'active',
                bypass_actors: [{ actor_id: 234, actor_type: 'Team', bypass_mode: 'always' }],
                conditions: {
                  ref_name: {
                    include: ['refs/heads/main', 'refs/heads/master'],
                    exclude: ['refs/heads/dev*'],
                  },
                  repository_name: {
                    include: ['important_repository', 'another_important_repository'],
                    exclude: ['unimportant_repository'],
                    protected: true,
                  },
                },
                rules: [
                  {
                    type: 'commit_author_email_pattern',
                    parameters: { operator: 'contains', pattern: 'github' },
                  },
                ],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: RepositoryRulesetSchema,
          examples: { default: OrgRulesetExample },
        },
      },
    },
    404: NotFoundResponse,
    422: ValidationFailedResponse,
    500: InternalErrorResponse,
  },
})

