export const getOrgsOrgRulesetsRulesetIdRoute = createRoute({
  method: 'get',
  path: '/orgs/{org}/rulesets/{ruleset_id}',
  tags: ['repos'],
  summary: 'Get an organization repository ruleset',
  description:
    'Get a repository ruleset for an organization.\n\n**Note:** To prevent leaking sensitive information, the `bypass_actors` property is only returned if the user\nmaking the API request has write access to the ruleset.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/rules#get-an-organization-repository-ruleset',
  },
  operationId: 'repos/get-org-ruleset',
  request: {
    params: z.object({
      org: OrgParamsSchema,
      ruleset_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'ruleset_id',
            description: 'The ID of the ruleset.',
            in: 'path',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: RepositoryRulesetSchema,
          examples: { default: OrgRulesetExample },
        },
      },
    },
    404: NotFoundResponse,
    500: InternalErrorResponse,
  },
})

