export const getOrgsOrgSecurityAdvisoriesRoute = createRoute({
  method: 'get',
  path: '/orgs/{org}/security-advisories',
  tags: ['security-advisories'],
  summary: 'List repository security advisories for an organization',
  description:
    'Lists repository security advisories for an organization.\n\nThe authenticated user must be an owner or security manager for the organization to use this endpoint.\n\nOAuth app tokens and personal access tokens (classic) need the `repo` or `repository_advisories:write` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/security-advisories/repository-advisories#list-repository-security-advisories-for-an-organization',
  },
  operationId: 'security-advisories/list-org-repository-advisories',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    query: z.object({
      direction: DirectionParamsSchema,
      sort: z
        .enum(['created', 'updated', 'published'])
        .default('created')
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            description: 'The property to sort the results by.',
            in: 'query',
            required: false,
            schema: {
              type: 'string',
              enum: ['created', 'updated', 'published'],
              default: 'created',
            },
          },
        }),
      before: PaginationBeforeParamsSchema,
      after: PaginationAfterParamsSchema,
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(30)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            description:
              'The number of advisories to return per page. For more information, see "[Using pagination in the REST API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the-rest-api)."',
            in: 'query',
            required: false,
            schema: { type: 'integer', minimum: 1, maximum: 100, default: 30 },
          },
        }),
      state: z
        .enum(['triage', 'draft', 'published', 'closed'])
        .exactOptional()
        .openapi({
          param: {
            name: 'state',
            description:
              'Filter by the state of the repository advisories. Only advisories of this state will be returned.',
            in: 'query',
            required: false,
            schema: { type: 'string', enum: ['triage', 'draft', 'published', 'closed'] },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z.array(RepositoryAdvisorySchema),
          examples: { default: ListRepositoryAdvisoriesExample },
        },
      },
    },
    400: BadRequestResponse,
    404: NotFoundResponse,
  },
})

