export const postOrgsOrgSettingsNetworkConfigurationsRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/settings/network-configurations',
  tags: ['hosted-compute'],
  summary: 'Create a hosted compute network configuration for an organization',
  description:
    'Creates a hosted compute network configuration for an organization.\n\nOAuth app tokens and personal access tokens (classic) need the `write:network_configurations` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/orgs/network-configurations#create-a-hosted-compute-network-configuration-for-an-organization',
  },
  operationId: 'hosted-compute/create-network-configuration-for-org',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z
                .string()
                .openapi({
                  description:
                    "Name of the network configuration. Must be between 1 and 100 characters and may only contain upper and lowercase letters a-z, numbers 0-9, '.', '-', and '_'.",
                }),
              compute_service: z
                .enum(['none', 'actions'])
                .exactOptional()
                .openapi({
                  description: 'The hosted compute service to use for the network configuration.',
                }),
              network_settings_ids: z
                .array(z.string())
                .length(1)
                .openapi({
                  description:
                    'A list of identifiers of the network settings resources to use for the network configuration. Exactly one resource identifier must be specified in the list.',
                }),
              failover_network_settings_ids: z
                .array(z.string())
                .min(0)
                .max(1)
                .exactOptional()
                .openapi({
                  description:
                    'A list of identifiers of the failover network settings resources to use for the network configuration. Exactly one resource identifier must be specified in the list.',
                }),
              failover_network_enabled: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Indicates whether the failover network resource is enabled.',
                }),
            })
            .openapi({ required: ['name', 'network_settings_ids'] }),
          examples: {
            default: {
              value: {
                name: 'my-network-configuration',
                network_settings_ids: ['23456789ABDCEF1'],
                compute_service: 'actions',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: NetworkConfigurationSchema,
          examples: { default: NetworkConfigurationExample },
        },
      },
    },
  },
})

