export const postOrgsOrgTeamsRoute = createRoute({
  method: 'post',
  path: '/orgs/{org}/teams',
  tags: ['teams'],
  summary: 'Create a team',
  description:
    'To create a team, the authenticated user must be a member or owner of `{org}`. By default, organization members can create teams. Organization owners can limit team creation to organization owners. For more information, see "[Setting team creation permissions](https://docs.github.com/articles/setting-team-creation-permissions-in-your-organization)."\n\nWhen you create a new team, you automatically become a team maintainer without explicitly adding yourself to the optional array of `maintainers`. For more information, see "[About teams](https://docs.github.com/github/setting-up-and-managing-organizations-and-teams/about-teams)".',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/teams/teams#create-a-team',
  },
  operationId: 'teams/create',
  request: {
    params: z.object({ org: OrgParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z.string().openapi({ description: 'The name of the team.' }),
              description: z
                .string()
                .exactOptional()
                .openapi({ description: 'The description of the team.' }),
              maintainers: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    'List GitHub usernames for organization members who will become team maintainers.',
                }),
              repo_names: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    'The full name (e.g., "organization-name/repository-name") of repositories to add the team to.',
                }),
              privacy: z
                .enum(['secret', 'closed'])
                .exactOptional()
                .openapi({
                  description:
                    'The level of privacy this team should have. The options are:  \n**For a non-nested team:**  \n * `secret` - only visible to organization owners and members of this team.  \n * `closed` - visible to all members of this organization.  \nDefault: `secret`  \n**For a parent or child team:**  \n * `closed` - visible to all members of this organization.  \nDefault for child team: `closed`',
                }),
              notification_setting: z
                .enum(['notifications_enabled', 'notifications_disabled'])
                .exactOptional()
                .openapi({
                  description:
                    'The notification setting the team has chosen. The options are:  \n * `notifications_enabled` - team members receive notifications when the team is @mentioned.  \n * `notifications_disabled` - no one receives notifications.  \nDefault: `notifications_enabled`',
                }),
              permission: z
                .enum(['pull', 'push'])
                .default('pull')
                .exactOptional()
                .openapi({
                  description:
                    '**Closing down notice**. The permission that new repositories will be added to the team with when none is specified.',
                }),
              parent_team_id: z
                .int()
                .exactOptional()
                .openapi({ description: 'The ID of a team to set as the parent team.' }),
              parent_team_slug: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The slug of a team to set as the parent team. Ignored when `parent_team_id` is also provided.',
                }),
            })
            .openapi({ required: ['name'] }),
          examples: {
            default: {
              value: {
                name: 'Justice League',
                description: 'A great team',
                permission: 'push',
                notification_setting: 'notifications_enabled',
                privacy: 'closed',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': { schema: TeamFullSchema, examples: { default: TeamFullExample } },
      },
    },
    403: ForbiddenResponse,
    422: ValidationFailedResponse,
  },
})

