export const getReposOwnerRepoActionsConcurrencyGroupsConcurrencyGroupNameRoute = createRoute({
  method: 'get',
  path: '/repos/{owner}/{repo}/actions/concurrency_groups/{concurrency_group_name}',
  tags: ['actions'],
  summary: 'Get a concurrency group for a repository',
  description:
    "Gets a specific concurrency group for a repository, including all instances in the group's queue.\nReturns 404 if the group is inactive or does not exist.\n\nOptionally, pass `ahead_of_run` or `ahead_of_job` to filter the results to only the items\nahead of the specified workflow run or job in the queue, plus the specified item itself\n(returned as the last element). This is useful for determining what is blocking a particular\nrun or job. Returns 422 if the specified run or job is not in this concurrency group.\n\nWhen using `ahead_of_run`, this matches workflow-level concurrency and any reusable-workflow\nleases held on behalf of that run. Job-level leases within the run are not considered to\nblock the run as a whole. Use `ahead_of_job` to match job-level concurrency and reusable-workflow\nleases on the job's ancestor paths.\n\nOAuth app tokens and personal access tokens (classic) need the `repo` scope to use this endpoint with a private repository.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/actions/concurrency-groups#get-a-concurrency-group-for-a-repository',
  },
  operationId: 'actions/get-concurrency-group-for-repository',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      concurrency_group_name: ConcurrencyGroupNameParamsSchema,
    }),
    query: z.object({
      ahead_of_run: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'ahead_of_run',
            description:
              'Filter to items ahead of this workflow run ID in the queue, plus the run itself.\nMatches workflow-level concurrency and reusable-workflow leases held on behalf of\nthe run. Mutually exclusive with `ahead_of_job`.',
            in: 'query',
            required: false,
            schema: { type: 'integer', minimum: 1 },
          },
        }),
      ahead_of_job: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'ahead_of_job',
            description:
              "Filter to items ahead of this job ID in the queue, plus the job itself.\nMatches job-level concurrency and reusable-workflow leases on the job's\nancestor paths. Mutually exclusive with `ahead_of_run`.",
            in: 'query',
            required: false,
            schema: { type: 'integer', minimum: 1 },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: ConcurrencyGroupSchema,
          examples: { default: ConcurrencyGroupExample },
        },
      },
    },
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

