export const getReposOwnerRepoActionsPoliciesPolicyIdRoute = createRoute({
  method: 'get',
  path: '/repos/{owner}/{repo}/actions/policies/{policy_id}',
  tags: ['actions'],
  summary: 'Get a repository Actions policy',
  description: 'Get a specific Actions policy for a repository.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/actions/policies#get-a-repository-actions-policy',
  },
  operationId: 'actions/get-repo-actions-policy',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      policy_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'policy_id',
            description: 'The ID of the policy.',
            in: 'path',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: ActionsPolicySchema,
          examples: { default: ActionsPolicyExample },
        },
      },
    },
    404: NotFoundResponse,
    500: InternalErrorResponse,
  },
})

