export const getReposOwnerRepoActionsRunsRunIdConcurrencyGroupsRoute = createRoute({
  method: 'get',
  path: '/repos/{owner}/{repo}/actions/runs/{run_id}/concurrency_groups',
  tags: ['actions'],
  summary: 'List concurrency groups for a workflow run',
  description:
    'Lists all concurrency groups associated with a workflow run or its jobs.\n\nThe set of groups is derived from the run\'s configuration, so a group is\nincluded even when the run no longer has any items currently holding or\nwaiting in it. In that case the `group_members` array will be empty.\n`total_count` reflects the number of groups the run participates in by\nconfiguration, not the number with active items.\n\nThis differs from `GET /repos/{owner}/{repo}/actions/concurrency_groups/{group_name}`,\nwhich returns 404 when a group has no active items. That endpoint reports\nthe live state of a group repo-wide, while this endpoint reports the\ngroups associated with a specific run by configuration.\n\nResults are sorted by group name and support cursor-based pagination via\n`before` and `after`. The `after` cursor paginates forward only and does\nnot emit a `rel="prev"` Link; use `before` to page backward from a\nforward page\'s `next` cursor.\n\nOAuth app tokens and personal access tokens (classic) need the `repo` scope to use this endpoint with a private repository.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/actions/concurrency-groups#list-concurrency-groups-for-a-workflow-run',
  },
  operationId: 'actions/list-concurrency-groups-for-workflow-run',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      run_id: RunIdParamsSchema,
    }),
    query: z.object({
      per_page: PerPageParamsSchema,
      before: PaginationBeforeParamsSchema,
      after: PaginationAfterParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: ConcurrencyGroupRunListSchema,
          examples: { default: ConcurrencyGroupRunListExample },
        },
      },
      headers: z.object({ Link: LinkHeaderSchema }),
    },
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

