export const postReposOwnerRepoActionsWorkflowsWorkflowIdDispatchesRoute = createRoute({
  method: 'post',
  path: '/repos/{owner}/{repo}/actions/workflows/{workflow_id}/dispatches',
  tags: ['actions'],
  summary: 'Create a workflow dispatch event',
  description:
    'You can use this endpoint to manually trigger a GitHub Actions workflow run. You can replace `workflow_id` with the workflow file name. For example, you could use `main.yaml`.\n\nYou must configure your GitHub Actions workflow to run when the [`workflow_dispatch` webhook](/developers/webhooks-and-events/webhook-events-and-payloads#workflow_dispatch) event occurs. The `inputs` are configured in the workflow file. For more information about how to configure the `workflow_dispatch` event in the workflow file, see "[Events that trigger workflows](/actions/reference/events-that-trigger-workflows#workflow_dispatch)."\n\nOAuth tokens and personal access tokens (classic) need the `repo` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/actions/workflows#create-a-workflow-dispatch-event',
  },
  operationId: 'actions/create-workflow-dispatch',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      workflow_id: WorkflowIdParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              ref: z
                .string()
                .openapi({
                  description:
                    'The git reference for the workflow. The reference can be a branch or tag name.',
                }),
              inputs: z
                .looseObject({})
                .refine((val) => Object.keys(val).length <= 25)
                .exactOptional()
                .openapi({
                  description:
                    'Input keys and values configured in the workflow file. The maximum number of properties is 25. Any default properties configured in the workflow file will be used when `inputs` are omitted.',
                }),
              return_run_details: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Whether the response should include the workflow run ID and URLs.',
                }),
            })
            .openapi({ required: ['ref'] }),
          examples: {
            default: {
              value: {
                ref: 'topic-branch',
                inputs: { name: 'Mona the Octocat', home: 'San Francisco, CA' },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Response including the workflow run ID and URLs when `return_run_details` parameter is `true`.',
      content: {
        'application/json': {
          schema: WorkflowDispatchResponseSchema,
          examples: { default: WorkflowDispatchResponseExample },
        },
      },
    },
    204: { description: 'Empty response when `return_run_details` parameter is `false`.' },
  },
})

