export const putReposOwnerRepoAgentsSecretsSecretNameRoute = createRoute({
  method: 'put',
  path: '/repos/{owner}/{repo}/agents/secrets/{secret_name}',
  tags: ['agents'],
  summary: 'Create or update a repository secret',
  description:
    'Creates or updates a repository secret with an encrypted value. Encrypt your secret using\n[LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages). For more information, see "[Encrypting secrets for the REST API](https://docs.github.com/rest/guides/encrypting-secrets-for-the-rest-api)."\n\nAuthenticated users must have collaborator access to a repository to create, update, or read secrets.\n\nOAuth tokens and personal access tokens (classic) need the `repo` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/agents/secrets#create-or-update-a-repository-secret',
  },
  operationId: 'agents/create-or-update-repo-secret',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      secret_name: SecretNameParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              encrypted_value: z
                .string()
                .regex(
                  /^(?:[A-Za-z0-9+\/]{4})*(?:[A-Za-z0-9+\/]{2}==|[A-Za-z0-9+\/]{3}=|[A-Za-z0-9+\/]{4})$/,
                )
                .openapi({
                  description:
                    'Value for your secret, encrypted with [LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages) using the public key retrieved from the [Get a repository public key](https://docs.github.com/rest/agents/secrets#get-a-repository-public-key) endpoint.',
                }),
              key_id: z
                .string()
                .openapi({ description: 'ID of the key you used to encrypt the secret.' }),
            })
            .openapi({ required: ['encrypted_value', 'key_id'] }),
          examples: {
            default: { value: { encrypted_value: 'c2VjcmV0', key_id: '012345678912345678' } },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response when creating a secret',
      content: {
        'application/json': { schema: EmptyObjectSchema, examples: { default: { value: null } } },
      },
    },
    204: { description: 'Response when updating a secret' },
  },
})

