export const getReposOwnerRepoAttestationsSubjectDigestRoute = createRoute({
  method: 'get',
  path: '/repos/{owner}/{repo}/attestations/{subject_digest}',
  tags: ['repos'],
  summary: 'List attestations',
  description:
    "List a collection of artifact attestations with a given subject digest that are associated with a repository.\n\nThe authenticated user making the request must have read access to the repository. In addition, when using a fine-grained access token the `attestations:read` permission is required.\n\n**Please note:** in order to offer meaningful security benefits, an attestation's signature and timestamps **must** be cryptographically verified, and the identity of the attestation signer **must** be validated. Attestations can be verified using the [GitHub CLI `attestation verify` command](https://cli.github.com/manual/gh_attestation_verify). For more information, see [our guide on how to use artifact attestations to establish a build's provenance](https://docs.github.com/actions/security-guides/using-artifact-attestations-to-establish-provenance-for-builds).",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/repos/attestations#list-attestations',
  },
  operationId: 'repos/list-attestations',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      subject_digest: z
        .string()
        .openapi({
          param: {
            name: 'subject_digest',
            description:
              "The parameter should be set to the attestation's subject's SHA256 digest, in the form `sha256:HEX_DIGEST`.",
            in: 'path',
            required: true,
            schema: { type: 'string' },
            'x-multi-segment': true,
          },
        }),
    }),
    query: z.object({
      per_page: PerPageParamsSchema,
      before: PaginationBeforeParamsSchema,
      after: PaginationAfterParamsSchema,
      predicate_type: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'predicate_type',
            description:
              'Optional filter for fetching attestations with a given predicate type.\nThis option accepts `provenance`, `sbom`, `release`, or freeform text\nfor custom predicate types.',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z
            .object({
              attestations: z
                .array(
                  z
                    .object({
                      bundle: z
                        .object({
                          mediaType: z.string().exactOptional(),
                          verificationMaterial: z.looseObject({}).exactOptional(),
                          dsseEnvelope: z.looseObject({}).exactOptional(),
                        })
                        .exactOptional()
                        .openapi({
                          description:
                            "The attestation's Sigstore Bundle.\nRefer to the [Sigstore Bundle Specification](https://github.com/sigstore/protobuf-specs/blob/main/protos/sigstore_bundle.proto) for more information.",
                          required: [],
                        }),
                      repository_id: z.int().exactOptional(),
                      bundle_url: z.string().exactOptional(),
                      initiator: z.string().exactOptional(),
                    })
                    .openapi({ required: [] }),
                )
                .exactOptional(),
            })
            .openapi({ required: [] }),
          examples: { default: ListAttestationsExample },
        },
      },
    },
  },
})

