export const postReposOwnerRepoAutolinksRoute = createRoute({
  method: 'post',
  path: '/repos/{owner}/{repo}/autolinks',
  tags: ['repos'],
  summary: 'Create an autolink reference for a repository',
  description: 'Users with admin access to the repository can create an autolink.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/repos/autolinks#create-an-autolink-reference-for-a-repository',
  },
  operationId: 'repos/create-autolink',
  request: {
    params: z.object({ owner: OwnerParamsSchema, repo: RepoParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              key_prefix: z
                .string()
                .openapi({
                  description:
                    'This prefix appended by certain characters will generate a link any time it is found in an issue, pull request, or commit.',
                }),
              url_template: z
                .string()
                .openapi({
                  description:
                    'The URL must contain `<num>` for the reference number. `<num>` matches different characters depending on the value of `is_alphanumeric`.',
                }),
              is_alphanumeric: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    'Whether this autolink reference matches alphanumeric characters. If true, the `<num>` parameter of the `url_template` matches alphanumeric characters `A-Z` (case insensitive), `0-9`, and `-`. If false, this autolink reference only matches numeric characters.',
                }),
            })
            .openapi({ required: ['key_prefix', 'url_template'] }),
          examples: {
            default: {
              value: {
                key_prefix: 'TICKET-',
                url_template: 'https://example.com/TICKET?query=<num>',
                is_alphanumeric: true,
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'response',
      content: {
        'application/json': { schema: AutolinkSchema, examples: { default: AutolinkExample } },
      },
      headers: z.object({
        Location: {
          example: 'https://api.github.com/repos/octocat/Hello-World/autolinks/1',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              example: 'https://api.github.com/repos/octocat/Hello-World/autolinks/1',
              param: { required: false },
            }),
        },
      }),
    },
    422: ValidationFailedResponse,
  },
})

