export const putReposOwnerRepoBranchesBranchProtectionRoute = createRoute({
  method: 'put',
  path: '/repos/{owner}/{repo}/branches/{branch}/protection',
  tags: ['repos'],
  summary: 'Update branch protection',
  description:
    "Protected branches are available in public repositories with GitHub Free and GitHub Free for organizations, and in public and private repositories with GitHub Pro, GitHub Team, GitHub Enterprise Cloud, and GitHub Enterprise Server. For more information, see [GitHub's products](https://docs.github.com/github/getting-started-with-github/githubs-products) in the GitHub Help documentation.\n\nProtecting a branch requires admin or owner permissions to the repository.\n\n> [!NOTE]\n> Passing new arrays of `users` and `teams` replaces their previous values.\n\n> [!NOTE]\n> The list of users, apps, and teams in total is limited to 100 items.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/branches/branch-protection#update-branch-protection',
  },
  operationId: 'repos/update-branch-protection',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      branch: BranchParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              required_status_checks: z
                .object({
                  strict: z
                    .boolean()
                    .openapi({ description: 'Require branches to be up to date before merging.' }),
                  contexts: z
                    .array(z.string())
                    .openapi({
                      deprecated: true,
                      description:
                        '**Closing down notice**: The list of status checks to require in order to merge into this branch. If any of these checks have recently been set by a particular GitHub App, they will be required to come from that app in future for the branch to merge. Use `checks` instead of `contexts` for more fine-grained control.',
                    }),
                  checks: z
                    .array(
                      z
                        .object({
                          context: z
                            .string()
                            .openapi({ description: 'The name of the required check' }),
                          app_id: z
                            .int()
                            .exactOptional()
                            .openapi({
                              description:
                                'The ID of the GitHub App that must provide this check. Omit this field to automatically select the GitHub App that has recently provided this check, or any app if it was not set by a GitHub App. Pass -1 to explicitly allow any app to set the status.',
                            }),
                        })
                        .openapi({ required: ['context'] }),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        'The list of status checks to require in order to merge into this branch.',
                    }),
                })
                .nullable()
                .openapi({
                  description:
                    'Require status checks to pass before merging. Set to `null` to disable.',
                  required: ['strict', 'contexts'],
                }),
              enforce_admins: z
                .boolean()
                .nullable()
                .openapi({
                  description:
                    'Enforce all configured restrictions for administrators. Set to `true` to enforce required status checks for repository administrators. Set to `null` to disable.',
                }),
              required_pull_request_reviews: z
                .object({
                  dismissal_restrictions: z
                    .object({
                      users: z
                        .array(z.string())
                        .exactOptional()
                        .openapi({
                          description: 'The list of user `login`s with dismissal access',
                        }),
                      teams: z
                        .array(z.string())
                        .exactOptional()
                        .openapi({ description: 'The list of team `slug`s with dismissal access' }),
                      apps: z
                        .array(z.string())
                        .exactOptional()
                        .openapi({ description: 'The list of app `slug`s with dismissal access' }),
                    })
                    .exactOptional()
                    .openapi({
                      description:
                        'Specify which users, teams, and apps can dismiss pull request reviews. Pass an empty `dismissal_restrictions` object to disable. User and team `dismissal_restrictions` are only available for organization-owned repositories. Omit this parameter for personal repositories.',
                      required: [],
                    }),
                  dismiss_stale_reviews: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description:
                        'Set to `true` if you want to automatically dismiss approving reviews when someone pushes a new commit.',
                    }),
                  require_code_owner_reviews: z
                    .boolean()
                    .exactOptional()
                    .openapi({
                      description:
                        'Blocks merging pull requests until [code owners](https://docs.github.com/articles/about-code-owners/) review them.',
                    }),
                  required_approving_review_count: z
                    .int()
                    .exactOptional()
                    .openapi({
                      description:
                        'Specify the number of reviewers required to approve pull requests. Use a number between 1 and 6 or 0 to not require reviewers.',
                    }),
                  require_last_push_approval: z
                    .boolean()
                    .default(false)
                    .exactOptional()
                    .openapi({
                      description:
                        'Whether the most recent push must be approved by someone other than the person who pushed it. Default: `false`.',
                    }),
                  bypass_pull_request_allowances: z
                    .object({
                      users: z
                        .array(z.string())
                        .exactOptional()
                        .openapi({
                          description:
                            'The list of user `login`s allowed to bypass pull request requirements.',
                        }),
                      teams: z
                        .array(z.string())
                        .exactOptional()
                        .openapi({
                          description:
                            'The list of team `slug`s allowed to bypass pull request requirements.',
                        }),
                      apps: z
                        .array(z.string())
                        .exactOptional()
                        .openapi({
                          description:
                            'The list of app `slug`s allowed to bypass pull request requirements.',
                        }),
                    })
                    .exactOptional()
                    .openapi({
                      description:
                        'Allow specific users, teams, or apps to bypass pull request requirements.',
                      required: [],
                    }),
                })
                .nullable()
                .openapi({
                  description:
                    'Require at least one approving review on a pull request, before merging. Set to `null` to disable.',
                  required: [],
                }),
              restrictions: z
                .object({
                  users: z
                    .array(z.string())
                    .openapi({ description: 'The list of user `login`s with push access' }),
                  teams: z
                    .array(z.string())
                    .openapi({ description: 'The list of team `slug`s with push access' }),
                  apps: z
                    .array(z.string())
                    .exactOptional()
                    .openapi({ description: 'The list of app `slug`s with push access' }),
                })
                .nullable()
                .openapi({
                  description:
                    'Restrict who can push to the protected branch. User, app, and team `restrictions` are only available for organization-owned repositories. Set to `null` to disable.',
                  required: ['users', 'teams'],
                }),
              required_linear_history: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Enforces a linear commit Git history, which prevents anyone from pushing merge commits to a branch. Set to `true` to enforce a linear commit history. Set to `false` to disable a linear commit Git history. Your repository must allow squash merging or rebase merging before you can enable a linear commit history. Default: `false`. For more information, see "[Requiring a linear commit history](https://docs.github.com/github/administering-a-repository/requiring-a-linear-commit-history)" in the GitHub Help documentation.',
                }),
              allow_force_pushes: z
                .boolean()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'Permits force pushes to the protected branch by anyone with write access to the repository. Set to `true` to allow force pushes. Set to `false` or `null` to block force pushes. Default: `false`. For more information, see "[Enabling force pushes to a protected branch](https://docs.github.com/github/administering-a-repository/enabling-force-pushes-to-a-protected-branch)" in the GitHub Help documentation."',
                }),
              allow_deletions: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Allows deletion of the protected branch by anyone with write access to the repository. Set to `false` to prevent deletion of the protected branch. Default: `false`. For more information, see "[Enabling force pushes to a protected branch](https://docs.github.com/github/administering-a-repository/enabling-force-pushes-to-a-protected-branch)" in the GitHub Help documentation.',
                }),
              block_creations: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'If set to `true`, the `restrictions` branch protection settings which limits who can push will also block pushes which create new branches, unless the push is initiated by a user, team, or app which has the ability to push. Set to `true` to restrict new branch creation. Default: `false`.',
                }),
              required_conversation_resolution: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Requires all conversations on code to be resolved before a pull request can be merged into a branch that matches this rule. Set to `false` to disable. Default: `false`.',
                }),
              lock_branch: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Whether to set the branch as read-only. If this is true, users will not be able to push to the branch. Default: `false`.',
                }),
              allow_fork_syncing: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Whether users can pull changes from upstream when the branch is locked. Set to `true` to allow fork syncing. Set to `false` to prevent fork syncing. Default: `false`.',
                }),
            })
            .openapi({
              required: [
                'required_status_checks',
                'enforce_admins',
                'required_pull_request_reviews',
                'restrictions',
              ],
            }),
          examples: {
            default: {
              value: {
                required_status_checks: {
                  strict: true,
                  contexts: ['continuous-integration/travis-ci'],
                },
                enforce_admins: true,
                required_pull_request_reviews: {
                  dismissal_restrictions: { users: ['octocat'], teams: ['justice-league'] },
                  dismiss_stale_reviews: true,
                  require_code_owner_reviews: true,
                  required_approving_review_count: 2,
                  require_last_push_approval: true,
                  bypass_pull_request_allowances: { users: ['octocat'], teams: ['justice-league'] },
                },
                restrictions: { users: ['octocat'], teams: ['justice-league'], apps: ['super-ci'] },
                required_linear_history: true,
                allow_force_pushes: true,
                allow_deletions: true,
                block_creations: true,
                required_conversation_resolution: true,
                lock_branch: true,
                allow_fork_syncing: true,
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: ProtectedBranchSchema,
          examples: { default: BranchProtectionUpdateExample },
        },
      },
    },
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedSimpleResponse,
  },
})

