export const patchReposOwnerRepoBranchesBranchProtectionRequiredStatusChecksRoute = createRoute({
  method: 'patch',
  path: '/repos/{owner}/{repo}/branches/{branch}/protection/required_status_checks',
  tags: ['repos'],
  summary: 'Update status check protection',
  description:
    "Protected branches are available in public repositories with GitHub Free and GitHub Free for organizations, and in public and private repositories with GitHub Pro, GitHub Team, GitHub Enterprise Cloud, and GitHub Enterprise Server. For more information, see [GitHub's products](https://docs.github.com/github/getting-started-with-github/githubs-products) in the GitHub Help documentation.\n\nUpdating required status checks requires admin or owner permissions to the repository and branch protection to be enabled.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/branches/branch-protection#update-status-check-protection',
  },
  operationId: 'repos/update-status-check-protection',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      branch: BranchParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              strict: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Require branches to be up to date before merging.' }),
              contexts: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  deprecated: true,
                  description:
                    '**Closing down notice**: The list of status checks to require in order to merge into this branch. If any of these checks have recently been set by a particular GitHub App, they will be required to come from that app in future for the branch to merge. Use `checks` instead of `contexts` for more fine-grained control.',
                }),
              checks: z
                .array(
                  z
                    .object({
                      context: z
                        .string()
                        .openapi({ description: 'The name of the required check' }),
                      app_id: z
                        .int()
                        .exactOptional()
                        .openapi({
                          description:
                            'The ID of the GitHub App that must provide this check. Omit this field to automatically select the GitHub App that has recently provided this check, or any app if it was not set by a GitHub App. Pass -1 to explicitly allow any app to set the status.',
                        }),
                    })
                    .openapi({ required: ['context'] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'The list of status checks to require in order to merge into this branch.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            default: { value: { strict: true, contexts: ['continuous-integration/travis-ci'] } },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: StatusCheckPolicySchema,
          examples: { default: StatusCheckPolicyExample },
        },
      },
    },
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

