export const postReposOwnerRepoCheckRunsRoute = createRoute({
  method: 'post',
  path: '/repos/{owner}/{repo}/check-runs',
  tags: ['checks'],
  summary: 'Create a check run',
  description:
    'Creates a new check run for a specific commit in a repository.\n\nTo create a check run, you must use a GitHub App. OAuth apps and authenticated users are not able to create a check suite.\n\nIn a check suite, GitHub limits the number of check runs with the same name to 1000. Once these check runs exceed 1000, GitHub will start to automatically delete older check runs.\n\n> [!NOTE]\n> The Checks API only looks for pushes in the repository where the check suite or check run were created. Pushes to a branch in a forked repository are not detected and return an empty `pull_requests` array.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/checks/runs#create-a-check-run',
  },
  operationId: 'checks/create',
  request: {
    params: z.object({ owner: OwnerParamsSchema, repo: RepoParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .xor([
              z
                .looseObject({ status: z.literal('completed') })
                .openapi({ required: ['status', 'conclusion'] }),
              z
                .looseObject({ status: z.enum(['queued', 'in_progress']).exactOptional() })
                .openapi({ required: [] }),
            ])
            .openapi({ required: ['name', 'head_sha'], discriminator: { propertyName: 'status' } }),
          examples: {
            'example-of-in-progress-conclusion': {
              summary: 'Example of an in_progress conclusion',
              value: {
                name: 'mighty_readme',
                head_sha: 'ce587453ced02b1526dfb4cb910479d431683101',
                status: 'in_progress',
                external_id: '42',
                started_at: '2018-05-04T01:14:52Z',
                output: { title: 'Mighty Readme report', summary: '', text: '' },
              },
            },
            'example-of-completed-conclusion': {
              summary: 'Example of a completed conclusion',
              value: {
                name: 'mighty_readme',
                head_sha: 'ce587453ced02b1526dfb4cb910479d431683101',
                status: 'completed',
                started_at: '2017-11-30T19:39:10Z',
                conclusion: 'success',
                completed_at: '2017-11-30T19:49:10Z',
                output: {
                  title: 'Mighty Readme report',
                  summary: 'There are 0 failures, 2 warnings, and 1 notices.',
                  text: 'You may have some misspelled words on lines 2 and 4. You also may want to add a section in your README about how to install your app.',
                  annotations: [
                    {
                      path: 'README.md',
                      annotation_level: 'warning',
                      title: 'Spell Checker',
                      message: "Check your spelling for 'banaas'.",
                      raw_details: "Do you mean 'bananas' or 'banana'?",
                      start_line: 2,
                      end_line: 2,
                    },
                    {
                      path: 'README.md',
                      annotation_level: 'warning',
                      title: 'Spell Checker',
                      message: "Check your spelling for 'aples'",
                      raw_details: "Do you mean 'apples' or 'Naples'",
                      start_line: 4,
                      end_line: 4,
                    },
                  ],
                  images: [{ alt: 'Super bananas', image_url: 'http://example.com/images/42' }],
                },
                actions: [
                  {
                    label: 'Fix',
                    identifier: 'fix_errors',
                    description: 'Allow us to fix these errors for you',
                  },
                ],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: CheckRunSchema,
          examples: {
            'example-of-completed-conclusion': CheckRunExampleOfCompletedConclusionExample,
            'example-of-in-progress-conclusion': CheckRunExampleOfInProgressConclusionExample,
          },
        },
      },
    },
  },
})

