export const patchReposOwnerRepoCheckRunsCheckRunIdRoute = createRoute({
  method: 'patch',
  path: '/repos/{owner}/{repo}/check-runs/{check_run_id}',
  tags: ['checks'],
  summary: 'Update a check run',
  description:
    'Updates a check run for a specific commit in a repository.\n\n> [!NOTE]\n> The endpoints to manage checks only look for pushes in the repository where the check suite or check run were created. Pushes to a branch in a forked repository are not detected and return an empty `pull_requests` array.\n\nOAuth apps and personal access tokens (classic) cannot use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/checks/runs#update-a-check-run',
  },
  operationId: 'checks/update',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      check_run_id: CheckRunIdParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .union([
              z
                .looseObject({ status: z.literal('completed').exactOptional() })
                .openapi({ required: ['conclusion'] }),
              z
                .looseObject({ status: z.enum(['queued', 'in_progress']).exactOptional() })
                .openapi({ required: [] }),
            ])
            .and(
              z
                .object({
                  name: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'The name of the check. For example, "code-coverage".',
                    }),
                  details_url: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        "The URL of the integrator's site that has the full details of the check.",
                    }),
                  external_id: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: "A reference for the run on the integrator's system.",
                    }),
                  started_at: z.iso
                    .datetime({ offset: true })
                    .exactOptional()
                    .openapi({
                      description:
                        'This is a timestamp in [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) format: `YYYY-MM-DDTHH:MM:SSZ`.',
                    }),
                  status: z
                    .enum(['queued', 'in_progress', 'completed', 'waiting', 'requested', 'pending'])
                    .exactOptional()
                    .openapi({
                      description:
                        'The current status of the check run. Only GitHub Actions can set a status of `waiting`, `pending`, or `requested`.',
                    }),
                  conclusion: z
                    .enum([
                      'action_required',
                      'cancelled',
                      'failure',
                      'neutral',
                      'success',
                      'skipped',
                      'stale',
                      'timed_out',
                    ])
                    .exactOptional()
                    .openapi({
                      description:
                        '**Required if you provide `completed_at` or a `status` of `completed`**. The final conclusion of the check. \n**Note:** Providing `conclusion` will automatically set the `status` parameter to `completed`. You cannot change a check run conclusion to `stale`, only GitHub can set this.',
                    }),
                  completed_at: z.iso
                    .datetime({ offset: true })
                    .exactOptional()
                    .openapi({
                      description:
                        'The time the check completed. This is a timestamp in [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) format: `YYYY-MM-DDTHH:MM:SSZ`.',
                    }),
                  output: z
                    .object({
                      title: z.string().exactOptional().openapi({ description: '**Required**.' }),
                      summary: z
                        .string()
                        .max(65535)
                        .openapi({ description: 'Can contain Markdown.' }),
                      text: z
                        .string()
                        .max(65535)
                        .exactOptional()
                        .openapi({ description: 'Can contain Markdown.' }),
                      annotations: z
                        .array(
                          z
                            .object({
                              path: z
                                .string()
                                .openapi({
                                  description:
                                    'The path of the file to add an annotation to. For example, `assets/css/main.css`.',
                                }),
                              start_line: z
                                .int()
                                .openapi({
                                  description:
                                    'The start line of the annotation. Line numbers start at 1.',
                                }),
                              end_line: z
                                .int()
                                .openapi({ description: 'The end line of the annotation.' }),
                              start_column: z
                                .int()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'The start column of the annotation. Annotations only support `start_column` and `end_column` on the same line. Omit this parameter if `start_line` and `end_line` have different values. Column numbers start at 1.',
                                }),
                              end_column: z
                                .int()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'The end column of the annotation. Annotations only support `start_column` and `end_column` on the same line. Omit this parameter if `start_line` and `end_line` have different values.',
                                }),
                              annotation_level: z
                                .enum(['notice', 'warning', 'failure'])
                                .openapi({ description: 'The level of the annotation.' }),
                              message: z
                                .string()
                                .openapi({
                                  description:
                                    'A short description of the feedback for these lines of code. The maximum size is 64 KB.',
                                }),
                              title: z
                                .string()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'The title that represents the annotation. The maximum size is 255 characters.',
                                }),
                              raw_details: z
                                .string()
                                .exactOptional()
                                .openapi({
                                  description:
                                    'Details about this annotation. The maximum size is 64 KB.',
                                }),
                            })
                            .openapi({
                              required: [
                                'path',
                                'start_line',
                                'end_line',
                                'annotation_level',
                                'message',
                              ],
                            }),
                        )
                        .max(50)
                        .exactOptional()
                        .openapi({
                          description:
                            'Adds information from your analysis to specific lines of code. Annotations are visible in GitHub\'s pull request UI. Annotations are visible in GitHub\'s pull request UI. The Checks API limits the number of annotations to a maximum of 50 per API request. To create more than 50 annotations, you have to make multiple requests to the [Update a check run](https://docs.github.com/rest/checks/runs#update-a-check-run) endpoint. Each time you update the check run, annotations are appended to the list of annotations that already exist for the check run. GitHub Actions are limited to 10 warning annotations and 10 error annotations per step. For details about annotations in the UI, see "[About status checks](https://docs.github.com/articles/about-status-checks#checks)".',
                        }),
                      images: z
                        .array(
                          z
                            .object({
                              alt: z
                                .string()
                                .openapi({ description: 'The alternative text for the image.' }),
                              image_url: z
                                .string()
                                .openapi({ description: 'The full URL of the image.' }),
                              caption: z
                                .string()
                                .exactOptional()
                                .openapi({ description: 'A short image description.' }),
                            })
                            .openapi({ required: ['alt', 'image_url'] }),
                        )
                        .exactOptional()
                        .openapi({
                          description:
                            'Adds images to the output displayed in the GitHub pull request UI.',
                        }),
                    })
                    .exactOptional()
                    .openapi({
                      description:
                        'Check runs can accept a variety of data in the `output` object, including a `title` and `summary` and can optionally provide descriptive details about the run.',
                      required: ['summary'],
                    }),
                  actions: z
                    .array(
                      z
                        .object({
                          label: z
                            .string()
                            .max(20)
                            .openapi({
                              description:
                                'The text to be displayed on a button in the web UI. The maximum size is 20 characters.',
                            }),
                          description: z
                            .string()
                            .max(40)
                            .openapi({
                              description:
                                'A short explanation of what this action would do. The maximum size is 40 characters.',
                            }),
                          identifier: z
                            .string()
                            .max(20)
                            .openapi({
                              description:
                                "A reference for the action on the integrator's system. The maximum size is 20 characters.",
                            }),
                        })
                        .openapi({ required: ['label', 'description', 'identifier'] }),
                    )
                    .max(3)
                    .exactOptional()
                    .openapi({
                      description:
                        'Possible further actions the integrator can perform, which a user may trigger. Each action includes a `label`, `identifier` and `description`. A maximum of three actions are accepted. To learn more about check runs and requested actions, see "[Check runs and requested actions](https://docs.github.com/rest/guides/using-the-rest-api-to-interact-with-checks#check-runs-and-requested-actions)."',
                    }),
                })
                .openapi({ required: [] }),
            ),
          examples: {
            default: {
              value: {
                name: 'mighty_readme',
                started_at: '2018-05-04T01:14:52Z',
                status: 'completed',
                conclusion: 'success',
                completed_at: '2018-05-04T01:14:52Z',
                output: {
                  title: 'Mighty Readme report',
                  summary: 'There are 0 failures, 2 warnings, and 1 notices.',
                  text: 'You may have some misspelled words on lines 2 and 4. You also may want to add a section in your README about how to install your app.',
                  annotations: [
                    {
                      path: 'README.md',
                      annotation_level: 'warning',
                      title: 'Spell Checker',
                      message: "Check your spelling for 'banaas'.",
                      raw_details: "Do you mean 'bananas' or 'banana'?",
                      start_line: 2,
                      end_line: 2,
                    },
                    {
                      path: 'README.md',
                      annotation_level: 'warning',
                      title: 'Spell Checker',
                      message: "Check your spelling for 'aples'",
                      raw_details: "Do you mean 'apples' or 'Naples'",
                      start_line: 4,
                      end_line: 4,
                    },
                  ],
                  images: [{ alt: 'Super bananas', image_url: 'http://example.com/images/42' }],
                },
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': { schema: CheckRunSchema, examples: { default: CheckRunExample } },
      },
    },
  },
})

