export const patchReposOwnerRepoCodeScanningAlertsAlertNumberRoute = createRoute({
  method: 'patch',
  path: '/repos/{owner}/{repo}/code-scanning/alerts/{alert_number}',
  tags: ['code-scanning'],
  summary: 'Update a code scanning alert',
  description:
    'Updates the status of a single code scanning alert.\nOAuth app tokens and personal access tokens (classic) need the `security_events` scope to use this endpoint with private or public repositories, or the `public_repo` scope to use this endpoint with only public repositories.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/code-scanning/code-scanning#update-a-code-scanning-alert',
  },
  operationId: 'code-scanning/update-alert',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      alert_number: AlertNumberParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .union([
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'state')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['state'] }),
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'assignees')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['assignees'] }),
            ])
            .and(
              z
                .object({
                  state: CodeScanningAlertSetStateSchema.exactOptional(),
                  dismissed_reason: CodeScanningAlertDismissedReasonSchema.exactOptional(),
                  dismissed_comment: CodeScanningAlertDismissedCommentSchema.exactOptional(),
                  create_request: CodeScanningAlertCreateRequestSchema.exactOptional(),
                  assignees: CodeScanningAlertAssigneesSchema.exactOptional(),
                })
                .openapi({ required: [] }),
            ),
          examples: {
            default: {
              value: {
                state: 'dismissed',
                dismissed_reason: 'false positive',
                dismissed_comment:
                  "This alert is not actually correct, because there's a sanitizer included in the library.",
                create_request: true,
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: CodeScanningAlertSchema,
          examples: { default: CodeScanningAlertDismissedExample },
        },
      },
    },
    400: BadRequestResponse,
    403: CodeScanningForbiddenWriteResponse,
    404: NotFoundResponse,
    503: ServiceUnavailableResponse,
  },
})

