export const postReposOwnerRepoCodespacesRoute = createRoute({
  method: 'post',
  path: '/repos/{owner}/{repo}/codespaces',
  tags: ['codespaces'],
  summary: 'Create a codespace in a repository',
  description:
    'Creates a codespace owned by the authenticated user in the specified repository.\n\nOAuth app tokens and personal access tokens (classic) need the `codespace` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/codespaces/codespaces#create-a-codespace-in-a-repository',
  },
  operationId: 'codespaces/create-with-repo-for-authenticated-user',
  request: {
    params: z.object({ owner: OwnerParamsSchema, repo: RepoParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              ref: z
                .string()
                .exactOptional()
                .openapi({ description: 'Git ref (typically a branch name) for this codespace' }),
              location: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The requested location for a new codespace. Best efforts are made to respect this upon creation. Assigned by IP if not provided.',
                }),
              geo: z
                .enum(['EuropeWest', 'SoutheastAsia', 'UsEast', 'UsWest'])
                .exactOptional()
                .openapi({
                  description:
                    'The geographic area for this codespace. If not specified, the value is assigned by IP. This property replaces `location`, which is closing down.',
                }),
              client_ip: z
                .string()
                .exactOptional()
                .openapi({ description: 'IP for location auto-detection when proxying a request' }),
              machine: z
                .string()
                .exactOptional()
                .openapi({ description: 'Machine type to use for this codespace' }),
              devcontainer_path: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Path to devcontainer.json config to use for this codespace',
                }),
              multi_repo_permissions_opt_out: z
                .boolean()
                .exactOptional()
                .openapi({
                  description: 'Whether to authorize requested permissions from devcontainer.json',
                }),
              working_directory: z
                .string()
                .exactOptional()
                .openapi({ description: 'Working directory for this codespace' }),
              idle_timeout_minutes: z
                .int()
                .exactOptional()
                .openapi({ description: 'Time in minutes before codespace stops from inactivity' }),
              display_name: z
                .string()
                .exactOptional()
                .openapi({ description: 'Display name for this codespace' }),
              retention_period_minutes: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'Duration in minutes after codespace has gone idle in which it will be deleted. Must be integer minutes between 0 and 43200 (30 days).',
                }),
            })
            .nullable()
            .openapi({ required: [] }),
          examples: { default: { value: { ref: 'main', machine: 'standardLinux32gb' } } },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response when the codespace was successfully created',
      content: {
        'application/json': { schema: CodespaceSchema, examples: { default: CodespaceExample } },
      },
    },
    202: {
      description:
        'Response when the codespace creation partially failed but is being retried in the background',
      content: {
        'application/json': { schema: CodespaceSchema, examples: { default: CodespaceExample } },
      },
    },
    400: BadRequestResponse,
    401: RequiresAuthenticationResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    503: ServiceUnavailableResponse,
  },
})

