export const putReposOwnerRepoCodespacesSecretsSecretNameRoute = createRoute({
  method: 'put',
  path: '/repos/{owner}/{repo}/codespaces/secrets/{secret_name}',
  tags: ['codespaces'],
  summary: 'Create or update a repository secret',
  description:
    'Creates or updates a repository development environment secret with an encrypted value. Encrypt your secret using\n[LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages). For more information, see "[Encrypting secrets for the REST API](https://docs.github.com/rest/guides/encrypting-secrets-for-the-rest-api)."\n\nOAuth app tokens and personal access tokens (classic) need the `repo` scope to use this endpoint. The associated user must be a repository admin.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/codespaces/repository-secrets#create-or-update-a-repository-secret',
  },
  operationId: 'codespaces/create-or-update-repo-secret',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      secret_name: SecretNameParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              encrypted_value: z
                .string()
                .regex(
                  /^(?:[A-Za-z0-9+\/]{4})*(?:[A-Za-z0-9+\/]{2}==|[A-Za-z0-9+\/]{3}=|[A-Za-z0-9+\/]{4})$/,
                )
                .exactOptional()
                .openapi({
                  description:
                    'Value for your secret, encrypted with [LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages) using the public key retrieved from the [Get a repository public key](https://docs.github.com/rest/codespaces/repository-secrets#get-a-repository-public-key) endpoint.',
                }),
              key_id: z
                .string()
                .exactOptional()
                .openapi({ description: 'ID of the key you used to encrypt the secret.' }),
            })
            .openapi({ required: [] }),
          examples: {
            default: { value: { encrypted_value: 'c2VjcmV0', key_id: '012345678912345678' } },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response when creating a secret',
      content: {
        'application/json': { schema: EmptyObjectSchema, examples: { default: { value: null } } },
      },
    },
    204: { description: 'Response when updating a secret' },
  },
})

