export const getReposOwnerRepoCollaboratorsRoute = createRoute({
  method: 'get',
  path: '/repos/{owner}/{repo}/collaborators',
  tags: ['repos'],
  summary: 'List repository collaborators',
  description:
    'For organization-owned repositories, the list of collaborators includes outside collaborators, organization members that are direct collaborators, organization members with access through team memberships, organization members with access through default organization permissions, and organization owners.\nThe `permissions` hash returned in the response contains the base role permissions of the collaborator. The `role_name` is the highest role assigned to the collaborator after considering all sources of grants, including: repo, teams, organization, and enterprise.\nThere is presently not a way to differentiate between an organization level grant and a repository level grant from this endpoint response.\n\nTeam members will include the members of child teams.\n\nThe authenticated user must have write, maintain, or admin privileges on the repository to use this endpoint. For organization-owned repositories, the authenticated user needs to be a member of the organization.\nOAuth app tokens and personal access tokens (classic) need the `read:org` and `repo` scopes to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/collaborators/collaborators#list-repository-collaborators',
  },
  operationId: 'repos/list-collaborators',
  request: {
    params: z.object({ owner: OwnerParamsSchema, repo: RepoParamsSchema }),
    query: z.object({
      affiliation: z
        .enum(['outside', 'direct', 'all'])
        .default('all')
        .exactOptional()
        .openapi({
          param: {
            name: 'affiliation',
            description:
              'Filter collaborators returned by their affiliation. `outside` means all outside collaborators of an organization-owned repository. `direct` means all collaborators with permissions to an organization-owned repository, regardless of organization membership status. `all` means all collaborators the authenticated user can see.',
            in: 'query',
            required: false,
            schema: { type: 'string', enum: ['outside', 'direct', 'all'], default: 'all' },
          },
        }),
      permission: z
        .enum(['pull', 'triage', 'triage_plus', 'push', 'maintain', 'admin'])
        .exactOptional()
        .openapi({
          param: {
            name: 'permission',
            description:
              'Filter collaborators by the permissions they have on the repository. If not specified, all collaborators will be returned.',
            in: 'query',
            required: false,
            schema: {
              type: 'string',
              enum: ['pull', 'triage', 'triage_plus', 'push', 'maintain', 'admin'],
            },
          },
        }),
      per_page: PerPageParamsSchema,
      page: PageParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z.array(CollaboratorSchema),
          examples: { default: CollaboratorItemsExample },
        },
      },
      headers: z.object({ Link: LinkHeaderSchema }),
    },
    404: NotFoundResponse,
  },
})

