export const getReposOwnerRepoCommitsRoute = createRoute({
  method: 'get',
  path: '/repos/{owner}/{repo}/commits',
  tags: ['repos'],
  summary: 'List commits',
  description:
    '**Signature verification object**\n\nThe response will include a `verification` object that describes the result of verifying the commit\'s signature. The following fields are included in the `verification` object:\n\n| Name | Type | Description |\n| ---- | ---- | ----------- |\n| `verified` | `boolean` | Indicates whether GitHub considers the signature in this commit to be verified. |\n| `reason` | `string` | The reason for verified value. Possible values and their meanings are enumerated in table below. |\n| `signature` | `string` | The signature that was extracted from the commit. |\n| `payload` | `string` | The value that was signed. |\n| `verified_at` | `string` | The date the signature was verified by GitHub. |\n\nThese are the possible values for `reason` in the `verification` object:\n\n| Value | Description |\n| ----- | ----------- |\n| `expired_key` | The key that made the signature is expired. |\n| `not_signing_key` | The "signing" flag is not among the usage flags in the GPG key that made the signature. |\n| `gpgverify_error` | There was an error communicating with the signature verification service. |\n| `gpgverify_unavailable` | The signature verification service is currently unavailable. |\n| `unsigned` | The object does not include a signature. |\n| `unknown_signature_type` | A non-PGP signature was found in the commit. |\n| `no_user` | No user was associated with the `committer` email address in the commit. |\n| `unverified_email` | The `committer` email address in the commit was associated with a user, but the email address is not verified on their account. |\n| `bad_email` | The `committer` email address in the commit is not included in the identities of the PGP key that made the signature. |\n| `unknown_key` | The key that made the signature has not been registered with any user\'s account. |\n| `malformed_signature` | There was an error parsing the signature. |\n| `invalid` | The signature could not be cryptographically verified using the key whose key-id was found in the signature. |\n| `valid` | None of the above errors applied, so the signature is considered to be verified. |',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/commits/commits#list-commits',
  },
  operationId: 'repos/list-commits',
  request: {
    params: z.object({ owner: OwnerParamsSchema, repo: RepoParamsSchema }),
    query: z.object({
      sha: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'sha',
            description:
              'SHA or branch to start listing commits from. Default: the repository’s default branch (usually `main`).',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      path: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'path',
            description: 'Only commits containing this file path will be returned.',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      author: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'author',
            description: 'GitHub username or email address to use to filter by commit author.',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      committer: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'committer',
            description: 'GitHub username or email address to use to filter by commit committer.',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      since: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'since',
            description:
              'Only show results that were last updated after the given time. This is a timestamp in [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) format: `YYYY-MM-DDTHH:MM:SSZ`. Due to limitations of Git, timestamps must be between 1970-01-01 and 2099-12-31 (inclusive) or unexpected results may be returned.',
            in: 'query',
            required: false,
            schema: { type: 'string', format: 'date-time' },
          },
        }),
      until: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            name: 'until',
            description:
              'Only commits before this date will be returned. This is a timestamp in [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) format: `YYYY-MM-DDTHH:MM:SSZ`. Due to limitations of Git, timestamps must be between 1970-01-01 and 2099-12-31 (inclusive) or unexpected results may be returned.',
            in: 'query',
            required: false,
            schema: { type: 'string', format: 'date-time' },
          },
        }),
      per_page: PerPageParamsSchema,
      page: PageParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z.array(CommitSchema),
          examples: { default: CommitItemsExample },
        },
      },
      headers: z.object({ Link: LinkHeaderSchema }),
    },
    400: BadRequestResponse,
    404: NotFoundResponse,
    409: ConflictResponse,
    422: ValidationFailedResponse,
    429: ServerLoadTryAgainResponse,
    500: InternalErrorResponse,
  },
})

