export const putReposOwnerRepoEnvironmentsEnvironmentNameRoute = createRoute({
  method: 'put',
  path: '/repos/{owner}/{repo}/environments/{environment_name}',
  tags: ['repos'],
  summary: 'Create or update an environment',
  description:
    'Create or update an environment with protection rules, such as required reviewers. For more information about environment protection rules, see "[Environments](/actions/reference/environments#environment-protection-rules)."\n\n> [!NOTE]\n> To create or update name patterns that branches must match in order to deploy to this environment, see "[Deployment branch policies](/rest/deployments/branch-policies)."\n\n> [!NOTE]\n> To create or update secrets for an environment, see "[GitHub Actions secrets](/rest/actions/secrets)."\n\nOAuth app tokens and personal access tokens (classic) need the `repo` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/deployments/environments#create-or-update-an-environment',
  },
  operationId: 'repos/create-or-update-environment',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      environment_name: EnvironmentNameParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              wait_timer: WaitTimerSchema.exactOptional(),
              prevent_self_review: PreventSelfReviewSchema.exactOptional(),
              reviewers: z
                .array(
                  z
                    .object({
                      type: DeploymentReviewerTypeSchema.exactOptional(),
                      id: z
                        .int()
                        .exactOptional()
                        .openapi({
                          description: 'The id of the user or team who can review the deployment',
                          example: 4532992,
                        }),
                    })
                    .openapi({ required: [] }),
                )
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'The people or teams that may review jobs that reference the environment. You can list up to six users or teams as reviewers. The reviewers must have at least read access to the repository. Only one of the required reviewers needs to approve the job for it to proceed.',
                }),
              deployment_branch_policy: DeploymentBranchPolicySettingsSchema.exactOptional(),
            })
            .nullable()
            .openapi({ required: [] }),
          examples: {
            default: {
              value: {
                wait_timer: 30,
                prevent_self_review: false,
                reviewers: [
                  { type: 'User', id: 1 },
                  { type: 'Team', id: 1 },
                ],
                deployment_branch_policy: {
                  protected_branches: false,
                  custom_branch_policies: true,
                },
              },
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: EnvironmentSchema,
          examples: { default: EnvironmentExample },
        },
      },
    },
    422: {
      description:
        'Validation error when the environment name is invalid or when `protected_branches` and `custom_branch_policies` in `deployment_branch_policy` are set to the same value',
      content: { 'application/json': { schema: BasicErrorSchema } },
    },
  },
})

