export const postReposOwnerRepoGitCommitsRoute = createRoute({
  method: 'post',
  path: '/repos/{owner}/{repo}/git/commits',
  tags: ['git'],
  summary: 'Create a commit',
  description:
    'Creates a new Git [commit object](https://git-scm.com/book/en/v2/Git-Internals-Git-Objects).\n\n**Signature verification object**\n\nThe response will include a `verification` object that describes the result of verifying the commit\'s signature. The following fields are included in the `verification` object:\n\n| Name | Type | Description |\n| ---- | ---- | ----------- |\n| `verified` | `boolean` | Indicates whether GitHub considers the signature in this commit to be verified. |\n| `reason` | `string` | The reason for verified value. Possible values and their meanings are enumerated in the table below. |\n| `signature` | `string` | The signature that was extracted from the commit. |\n| `payload` | `string` | The value that was signed. |\n| `verified_at` | `string` | The date the signature was verified by GitHub. |\n\nThese are the possible values for `reason` in the `verification` object:\n\n| Value | Description |\n| ----- | ----------- |\n| `expired_key` | The key that made the signature is expired. |\n| `not_signing_key` | The "signing" flag is not among the usage flags in the GPG key that made the signature. |\n| `gpgverify_error` | There was an error communicating with the signature verification service. |\n| `gpgverify_unavailable` | The signature verification service is currently unavailable. |\n| `unsigned` | The object does not include a signature. |\n| `unknown_signature_type` | A non-PGP signature was found in the commit. |\n| `no_user` | No user was associated with the `committer` email address in the commit. |\n| `unverified_email` | The `committer` email address in the commit was associated with a user, but the email address is not verified on their account. |\n| `bad_email` | The `committer` email address in the commit is not included in the identities of the PGP key that made the signature. |\n| `unknown_key` | The key that made the signature has not been registered with any user\'s account. |\n| `malformed_signature` | There was an error parsing the signature. |\n| `invalid` | The signature could not be cryptographically verified using the key whose key-id was found in the signature. |\n| `valid` | None of the above errors applied, so the signature is considered to be verified. |',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/git/commits#create-a-commit',
  },
  operationId: 'git/create-commit',
  request: {
    params: z.object({ owner: OwnerParamsSchema, repo: RepoParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              message: z.string().openapi({ description: 'The commit message' }),
              tree: z
                .string()
                .openapi({ description: 'The SHA of the tree object this commit points to' }),
              parents: z
                .array(z.string())
                .exactOptional()
                .openapi({
                  description:
                    'The full SHAs of the commits that were the parents of this commit. If omitted or empty, the commit will be written as a root commit. For a single parent, an array of one SHA should be provided; for a merge commit, an array of more than one should be provided.',
                }),
              author: z
                .object({
                  name: z
                    .string()
                    .openapi({
                      description: 'The name of the author (or committer) of the commit',
                    }),
                  email: z
                    .string()
                    .openapi({
                      description: 'The email of the author (or committer) of the commit',
                    }),
                  date: z.iso
                    .datetime({ offset: true })
                    .exactOptional()
                    .openapi({
                      description:
                        'Indicates when this commit was authored (or committed). This is a timestamp in [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) format: `YYYY-MM-DDTHH:MM:SSZ`.',
                    }),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Information about the author of the commit. By default, the `author` will be the authenticated user and the current date. See the `author` and `committer` object below for details.',
                  required: ['name', 'email'],
                }),
              committer: z
                .object({
                  name: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'The name of the author (or committer) of the commit',
                    }),
                  email: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description: 'The email of the author (or committer) of the commit',
                    }),
                  date: z.iso
                    .datetime({ offset: true })
                    .exactOptional()
                    .openapi({
                      description:
                        'Indicates when this commit was authored (or committed). This is a timestamp in [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) format: `YYYY-MM-DDTHH:MM:SSZ`.',
                    }),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Information about the person who is making the commit. By default, `committer` will use the information set in `author`. See the `author` and `committer` object below for details.',
                  required: [],
                }),
              signature: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The [PGP signature](https://en.wikipedia.org/wiki/Pretty_Good_Privacy) of the commit. GitHub adds the signature to the `gpgsig` header of the created commit. For a commit signature to be verifiable by Git or GitHub, it must be an ASCII-armored detached PGP signature over the string commit as it would be written to the object database. To pass a `signature` parameter, you need to first manually create a valid PGP signature, which can be complicated. You may find it easier to [use the command line](https://git-scm.com/book/id/v2/Git-Tools-Signing-Your-Work) to create signed commits.',
                }),
            })
            .openapi({ required: ['message', 'tree'] }),
          examples: {
            default: {
              value: {
                message: 'my commit message',
                author: {
                  name: 'Mona Octocat',
                  email: 'octocat@github.com',
                  date: '2008-07-09T16:13:30+12:00',
                },
                parents: ['7d1b31e74ee336d15cbd21741bc88a537ed063a0'],
                tree: '827efc6d56897b048c772eb4087f854f46256132',
                signature:
                  '-----BEGIN PGP SIGNATURE-----\n\niQIzBAABAQAdFiEESn/54jMNIrGSE6Tp6cQjvhfv7nAFAlnT71cACgkQ6cQjvhfv\n7nCWwA//XVqBKWO0zF+bZl6pggvky3Oc2j1pNFuRWZ29LXpNuD5WUGXGG209B0hI\nDkmcGk19ZKUTnEUJV2Xd0R7AW01S/YSub7OYcgBkI7qUE13FVHN5ln1KvH2all2n\n2+JCV1HcJLEoTjqIFZSSu/sMdhkLQ9/NsmMAzpf/iIM0nQOyU4YRex9eD1bYj6nA\nOQPIDdAuaTQj1gFPHYLzM4zJnCqGdRlg0sOM/zC5apBNzIwlgREatOYQSCfCKV7k\nnrU34X8b9BzQaUx48Qa+Dmfn5KQ8dl27RNeWAqlkuWyv3pUauH9UeYW+KyuJeMkU\n+NyHgAsWFaCFl23kCHThbLStMZOYEnGagrd0hnm1TPS4GJkV4wfYMwnI4KuSlHKB\njHl3Js9vNzEUQipQJbgCgTiWvRJoK3ENwBTMVkKHaqT4x9U4Jk/XZB6Q8MA09ezJ\n3QgiTjTAGcum9E9QiJqMYdWQPWkaBIRRz5cET6HPB48YNXAAUsfmuYsGrnVLYbG+\nUpC6I97VybYHTy2O9XSGoaLeMI9CsFn38ycAxxbWagk5mhclNTP5mezIq6wKSwmr\nX11FW3n1J23fWZn5HJMBsRnUCgzqzX3871IqLYHqRJ/bpZ4h20RhTyPj5c/z7QXp\neSakNQMfbbMcljkha+ZMuVQX1K9aRlVqbmv3ZMWh+OijLYVU2bc=\n=5Io4\n-----END PGP SIGNATURE-----\n',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': { schema: GitCommitSchema, examples: { default: GitCommitExample } },
      },
      headers: z.object({
        Location: {
          example:
            'https://api.github.com/repos/octocat/Hello-World/git/commits/7638417db6d59f3c431d3e1f261cc637155684cd',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              example:
                'https://api.github.com/repos/octocat/Hello-World/git/commits/7638417db6d59f3c431d3e1f261cc637155684cd',
              param: { required: false },
            }),
        },
      }),
    },
    404: NotFoundResponse,
    409: ConflictResponse,
    422: ValidationFailedResponse,
  },
})

