export const postReposOwnerRepoHooksRoute = createRoute({
  method: 'post',
  path: '/repos/{owner}/{repo}/hooks',
  tags: ['repos'],
  summary: 'Create a repository webhook',
  description:
    'Repositories can have multiple webhooks installed. Each webhook should have a unique `config`. Multiple webhooks can\nshare the same `config` as long as those webhooks do not have any `events` that overlap.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/repos/webhooks#create-a-repository-webhook',
  },
  operationId: 'repos/create-webhook',
  request: {
    params: z.object({ owner: OwnerParamsSchema, repo: RepoParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              name: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Use `web` to create a webhook. Default: `web`. This parameter only accepts the value `web`.',
                }),
              config: z
                .object({
                  url: WebhookConfigUrlSchema.exactOptional(),
                  content_type: WebhookConfigContentTypeSchema.exactOptional(),
                  secret: WebhookConfigSecretSchema.exactOptional(),
                  insecure_ssl: WebhookConfigInsecureSslSchema.exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description: 'Key/value pairs to provide settings for this webhook.',
                  required: [],
                }),
              events: z
                .array(z.string())
                .default(['push'])
                .exactOptional()
                .openapi({
                  description:
                    'Determines what [events](https://docs.github.com/webhooks/event-payloads) the hook is triggered for.',
                }),
              active: z
                .boolean()
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    'Determines if notifications are sent when the webhook is triggered. Set to `true` to send notifications.',
                }),
            })
            .nullable()
            .openapi({ required: [] }),
          examples: {
            default: {
              value: {
                name: 'web',
                active: true,
                events: ['push', 'pull_request'],
                config: {
                  url: 'https://example.com/webhook',
                  content_type: 'json',
                  insecure_ssl: '0',
                },
              },
            },
          },
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: { 'application/json': { schema: HookSchema, examples: { default: HookExample } } },
      headers: z.object({
        Location: {
          example: 'https://api.github.com/repos/octocat/Hello-World/hooks/12345678',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              example: 'https://api.github.com/repos/octocat/Hello-World/hooks/12345678',
              param: { required: false },
            }),
        },
      }),
    },
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

