export const patchReposOwnerRepoImportAuthorsAuthorIdRoute = createRoute({
  method: 'patch',
  path: '/repos/{owner}/{repo}/import/authors/{author_id}',
  tags: ['migrations'],
  summary: 'Map a commit author',
  description:
    "Update an author's identity for the import. Your application can continue updating authors any time before you push\nnew commits to the repository.\n\n> [!WARNING]\n> **Endpoint closing down notice:** Due to very low levels of usage and available alternatives, this endpoint is closing down and will no longer be available from 00:00 UTC on April 12, 2024. For more details and alternatives, see the [changelog](https://gh.io/source-imports-api-deprecation).",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/migrations/source-imports#map-a-commit-author',
  },
  operationId: 'migrations/map-commit-author',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      author_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: { name: 'author_id', in: 'path', required: true, schema: { type: 'integer' } },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              email: z
                .string()
                .exactOptional()
                .openapi({ description: 'The new Git author email.' }),
              name: z.string().exactOptional().openapi({ description: 'The new Git author name.' }),
            })
            .openapi({ required: [] }),
          examples: { default: { value: { email: 'hubot@github.com', name: 'Hubot the Robot' } } },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: PorterAuthorSchema,
          examples: { default: PorterAuthorExample },
        },
      },
    },
    404: NotFoundResponse,
    422: ValidationFailedResponse,
    503: PorterMaintenanceResponse,
  },
  deprecated: true,
})

