export const getReposOwnerRepoIssuesRoute = createRoute({
  method: 'get',
  path: '/repos/{owner}/{repo}/issues',
  tags: ['issues'],
  summary: 'List repository issues',
  description:
    'List issues in a repository. Only open issues will be listed.\n\n> [!NOTE]\n> GitHub\'s REST API considers every pull request an issue, but not every issue is a pull request. For this reason, "Issues" endpoints may return both issues and pull requests in the response. You can identify pull requests by the `pull_request` key. Be aware that the `id` of a pull request returned from "Issues" endpoints will be an _issue id_. To find out the pull request id, use the "[List pull requests](https://docs.github.com/rest/pulls/pulls#list-pull-requests)" endpoint.\n\nThis endpoint supports the following custom media types. For more information, see "[Media types](https://docs.github.com/rest/using-the-rest-api/getting-started-with-the-rest-api#media-types)."\n\n- **`application/vnd.github.raw+json`**: Returns the raw markdown body. Response will include `body`. This is the default if you do not pass any specific media type.\n- **`application/vnd.github.text+json`**: Returns a text only representation of the markdown body. Response will include `body_text`.\n- **`application/vnd.github.html+json`**: Returns HTML rendered from the body\'s markdown. Response will include `body_html`.\n- **`application/vnd.github.full+json`**: Returns raw, text, and HTML representations. Response will include `body`, `body_text`, and `body_html`.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/issues/issues#list-repository-issues',
  },
  operationId: 'issues/list-for-repo',
  request: {
    params: z.object({ owner: OwnerParamsSchema, repo: RepoParamsSchema }),
    query: z.object({
      milestone: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'milestone',
            description:
              'If an `integer` is passed, it should refer to a milestone by its `number` field. If the string `*` is passed, issues with any milestone are accepted. If the string `none` is passed, issues without milestones are returned.',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      state: z
        .enum(['open', 'closed', 'all'])
        .default('open')
        .exactOptional()
        .openapi({
          param: {
            name: 'state',
            description: 'Indicates the state of the issues to return.',
            in: 'query',
            required: false,
            schema: { type: 'string', enum: ['open', 'closed', 'all'], default: 'open' },
          },
        }),
      assignee: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'assignee',
            description:
              'Can be the name of a user. Pass in `none` for issues with no assigned user, and `*` for issues assigned to any user.',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      type: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'type',
            description:
              'Can be the name of an issue type. If the string `*` is passed, issues with any type are accepted. If the string `none` is passed, issues without type are returned.',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      creator: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'creator',
            description: 'The user that created the issue.',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      mentioned: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'mentioned',
            description: "A user that's mentioned in the issue.",
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      issue_field_values: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'issue_field_values',
            description:
              "A comma-separated list of issue field filters in `field_slug:value` format.\nOnly issues matching all specified field values are returned.\nRequires issue fields to be enabled for the repository. Issue fields are\nnot available for user-owned repositories, and field availability for\norganization-owned public repositories depends on the organization's\nvisibility settings. For example, `priority:Urgent,severity:High` filters\nissues where the `priority` field is `Urgent` AND the `severity` field is\n`High`.",
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      labels: LabelsParamsSchema,
      sort: z
        .enum(['created', 'updated', 'comments'])
        .default('created')
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            description: 'What to sort results by.',
            in: 'query',
            required: false,
            schema: {
              type: 'string',
              enum: ['created', 'updated', 'comments'],
              default: 'created',
            },
          },
        }),
      direction: DirectionParamsSchema,
      since: SinceParamsSchema,
      per_page: PerPageParamsSchema,
      page: PageParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z.array(IssueSchema),
          examples: { default: IssueItemsExample },
        },
      },
      headers: z.object({ Link: LinkHeaderSchema }),
    },
    301: MovedPermanentlyResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

