export const putReposOwnerRepoIssuesIssueNumberIssueFieldValuesRoute = createRoute({
  method: 'put',
  path: '/repos/{owner}/{repo}/issues/{issue_number}/issue-field-values',
  tags: ['issues'],
  summary: 'Set issue field values for an issue',
  description:
    'Set custom field values for an issue, replacing any existing values. You can set values for organization-level issue fields that have been defined for the repository\'s organization.\n\nThis endpoint supports the following field data types:\n- **`text`**: String values for text fields\n- **`single_select`**: Option names for single-select fields (must match an existing option name)\n- **`number`**: Numeric values for number fields\n- **`date`**: ISO 8601 date strings for date fields\n\nThis operation will replace all existing field values with the provided ones. If you want to add field values without replacing existing ones, use the `POST` endpoint instead.\n\nOnly users with push access to the repository can set issue field values. If you don\'t have the proper permissions, you\'ll receive a `403 Forbidden` response.\n\nThis endpoint triggers [notifications](https://docs.github.com/github/managing-subscriptions-and-notifications-on-github/about-notifications). Creating content too quickly using this endpoint may result in secondary rate limiting. For more information, see "[Rate limits for the API](https://docs.github.com/rest/using-the-rest-api/rate-limits-for-the-rest-api#about-secondary-rate-limits)"\nand "[Best practices for using the REST API](https://docs.github.com/rest/guides/best-practices-for-using-the-rest-api)."',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/issues/issue-field-values#set-issue-field-values-for-an-issue',
  },
  operationId: 'issues/set-issue-field-values',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      issue_number: IssueNumberParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              issue_field_values: z
                .array(
                  z
                    .strictObject({
                      field_id: z
                        .int()
                        .openapi({ description: 'The ID of the issue field to set', example: 123 }),
                      value: z
                        .xor([
                          z
                            .string()
                            .openapi({
                              description:
                                'The value to set for text, single_select, or date fields',
                            }),
                          z.number().openapi({ description: 'The value to set for number fields' }),
                        ])
                        .openapi({
                          description:
                            "The value to set for the field. The type depends on the field's data type:\n- For text fields: provide a string value\n- For single_select fields: provide the option name as a string (must match an existing option)\n- For number fields: provide a numeric value\n- For date fields: provide an ISO 8601 date string",
                          example: 'Critical',
                        }),
                    })
                    .openapi({ required: ['field_id', 'value'] }),
                )
                .max(25)
                .exactOptional()
                .openapi({
                  description:
                    'An array of issue field values to set for this issue. Each field value must include the field ID and the value to set. All existing field values will be replaced.',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            default: {
              summary: 'Set multiple field values',
              value: {
                issue_field_values: [
                  { field_id: 123, value: 'Critical' },
                  { field_id: 456, value: 5 },
                  { field_id: 789, value: '2024-12-31' },
                ],
              },
            },
            'single-field': {
              summary: 'Set a single field value',
              value: { issue_field_values: [{ field_id: 123, value: 'High Priority' }] },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z
            .array(IssueFieldValueSchema)
            .openapi({
              description:
                'The current issue field values for this issue after setting the new values',
            }),
          examples: { default: IssueFieldValueItemsExample },
        },
      },
    },
    400: BadRequestResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
    503: ServiceUnavailableResponse,
  },
})

