export const deleteReposOwnerRepoIssuesIssueNumberRelatesToIssueIdRoute = createRoute({
  method: 'delete',
  path: '/repos/{owner}/{repo}/issues/{issue_number}/relates_to/{issue_id}',
  tags: ['issues'],
  summary: 'Remove a related issue',
  description:
    "You can use the REST API to remove a 'relates to' relationship between two issues.\n\nRemoving content too quickly using this endpoint may result in secondary rate limiting.\nFor more information, see [Rate limits for the API](https://docs.github.com/rest/using-the-rest-api/rate-limits-for-the-rest-api#about-secondary-rate-limits)\nand [Best practices for using the REST API](https://docs.github.com/rest/guides/best-practices-for-using-the-rest-api).\n\nThis endpoint supports the following custom media types. For more information, see [Media types](https://docs.github.com/rest/using-the-rest-api/getting-started-with-the-rest-api#media-types).\n\n- **`application/vnd.github.raw+json`**: Returns the raw Markdown body. Response will include `body`. This is the default if you do not pass any specific media type.\n- **`application/vnd.github.text+json`**: Returns a text only representation of the Markdown body. Response will include `body_text`.\n- **`application/vnd.github.html+json`**: Returns HTML rendered from the body's Markdown. Response will include `body_html`.\n- **`application/vnd.github.full+json`**: Returns raw, text, and HTML representations. Response will include `body`, `body_text`, and `body_html`.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/issues/issues#remove-a-related-issue',
  },
  operationId: 'issues/remove-relates-to',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      issue_number: IssueNumberParamsSchema,
      issue_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'issue_id',
            in: 'path',
            description: 'The id of the related issue to remove',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: { 'application/json': { schema: IssueSchema, examples: { default: IssueExample } } },
    },
    301: MovedPermanentlyResponse,
    400: BadRequestResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    410: GoneResponse,
  },
})

