export const getReposOwnerRepoPullsRoute = createRoute({
  method: 'get',
  path: '/repos/{owner}/{repo}/pulls',
  tags: ['pulls'],
  summary: 'List pull requests',
  description:
    'Lists pull requests in a specified repository.\n\nDraft pull requests are available in public repositories with GitHub\nFree and GitHub Free for organizations, GitHub Pro, and legacy per-repository billing\nplans, and in public and private repositories with GitHub Team and GitHub Enterprise\nCloud. For more information, see [GitHub\'s products](https://docs.github.com/github/getting-started-with-github/githubs-products)\nin the GitHub Help documentation.\n\nThis endpoint supports the following custom media types. For more information, see "[Media types](https://docs.github.com/rest/using-the-rest-api/getting-started-with-the-rest-api#media-types)."\n\n- **`application/vnd.github.raw+json`**: Returns the raw markdown body. Response will include `body`. This is the default if you do not pass any specific media type.\n- **`application/vnd.github.text+json`**: Returns a text only representation of the markdown body. Response will include `body_text`.\n- **`application/vnd.github.html+json`**: Returns HTML rendered from the body\'s markdown. Response will include `body_html`.\n- **`application/vnd.github.full+json`**: Returns raw, text, and HTML representations. Response will include `body`, `body_text`, and `body_html`.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/pulls/pulls#list-pull-requests',
  },
  operationId: 'pulls/list',
  request: {
    params: z.object({ owner: OwnerParamsSchema, repo: RepoParamsSchema }),
    query: z.object({
      state: z
        .enum(['open', 'closed', 'all'])
        .default('open')
        .exactOptional()
        .openapi({
          param: {
            name: 'state',
            description: 'Either `open`, `closed`, or `all` to filter by state.',
            in: 'query',
            required: false,
            schema: { type: 'string', enum: ['open', 'closed', 'all'], default: 'open' },
          },
        }),
      head: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'head',
            description:
              'Filter pulls by head user or head organization and branch name in the format of `user:ref-name` or `organization:ref-name`. For example: `github:new-script-format` or `octocat:test-branch`.',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      base: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'base',
            description: 'Filter pulls by base branch name. Example: `gh-pages`.',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
      sort: z
        .enum(['created', 'updated', 'popularity', 'long-running'])
        .default('created')
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            description:
              'What to sort results by. `popularity` will sort by the number of comments. `long-running` will sort by date created and will limit the results to pull requests that have been open for more than a month and have had activity within the past month.',
            in: 'query',
            required: false,
            schema: {
              type: 'string',
              enum: ['created', 'updated', 'popularity', 'long-running'],
              default: 'created',
            },
          },
        }),
      direction: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            description:
              'The direction of the sort. Default: `desc` when sort is `created` or sort is not specified, otherwise `asc`.',
            in: 'query',
            required: false,
            schema: { type: 'string', enum: ['asc', 'desc'] },
          },
        }),
      per_page: PerPageParamsSchema,
      page: PageParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z.array(PullRequestSimpleSchema),
          examples: { default: PullRequestSimpleItemsExample },
        },
      },
      headers: z.object({ Link: LinkHeaderSchema }),
    },
    304: NotModifiedResponse,
    422: ValidationFailedResponse,
  },
})

export const postReposOwnerRepoPullsRoute = createRoute({
  method: 'post',
  path: '/repos/{owner}/{repo}/pulls',
  tags: ['pulls'],
  summary: 'Create a pull request',
  description:
    'Draft pull requests are available in public repositories with GitHub Free and GitHub Free for organizations, GitHub Pro, and legacy per-repository billing plans, and in public and private repositories with GitHub Team and GitHub Enterprise Cloud. For more information, see [GitHub\'s products](https://docs.github.com/github/getting-started-with-github/githubs-products) in the GitHub Help documentation.\n\nTo open or update a pull request in a public repository, you must have write access to the head or the source branch. For organization-owned repositories, you must be a member of the organization that owns the repository to open or update a pull request.\n\nThis endpoint triggers [notifications](https://docs.github.com/github/managing-subscriptions-and-notifications-on-github/about-notifications). Creating content too quickly using this endpoint may result in secondary rate limiting. For more information, see "[Rate limits for the API](https://docs.github.com/rest/using-the-rest-api/rate-limits-for-the-rest-api#about-secondary-rate-limits)" and "[Best practices for using the REST API](https://docs.github.com/rest/guides/best-practices-for-using-the-rest-api)."\n\nThis endpoint supports the following custom media types. For more information, see "[Media types](https://docs.github.com/rest/using-the-rest-api/getting-started-with-the-rest-api#media-types)."\n\n- **`application/vnd.github.raw+json`**: Returns the raw markdown body. Response will include `body`. This is the default if you do not pass any specific media type.\n- **`application/vnd.github.text+json`**: Returns a text only representation of the markdown body. Response will include `body_text`.\n- **`application/vnd.github.html+json`**: Returns HTML rendered from the body\'s markdown. Response will include `body_html`.\n- **`application/vnd.github.full+json`**: Returns raw, text, and HTML representations. Response will include `body`, `body_text`, and `body_html`.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/pulls/pulls#create-a-pull-request',
  },
  operationId: 'pulls/create',
  request: {
    params: z.object({ owner: OwnerParamsSchema, repo: RepoParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              title: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The title of the new pull request. Required unless `issue` is specified.',
                }),
              head: z
                .string()
                .openapi({
                  description:
                    'The name of the branch where your changes are implemented. For cross-repository pull requests in the same network, namespace `head` with a user like this: `username:branch`.',
                }),
              head_repo: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The name of the repository where the changes in the pull request were made. This field is required for cross-repository pull requests if both repositories are owned by the same organization.',
                  example: 'octo-org/octo-repo',
                }),
              base: z
                .string()
                .openapi({
                  description:
                    'The name of the branch you want the changes pulled into. This should be an existing branch on the current repository. You cannot submit a pull request to one repository that requests a merge to a base of another repository.',
                }),
              body: z
                .string()
                .exactOptional()
                .openapi({ description: 'The contents of the pull request.' }),
              maintainer_can_modify: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Indicates whether [maintainers can modify](https://docs.github.com/articles/allowing-changes-to-a-pull-request-branch-created-from-a-fork/) the pull request.',
                }),
              draft: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Indicates whether the pull request is a draft. See "[Draft Pull Requests](https://docs.github.com/articles/about-pull-requests#draft-pull-requests)" in the GitHub Help documentation to learn more.',
                }),
              issue: z
                .preprocess(
                  (val) =>
                    typeof val === 'number' && Number.isSafeInteger(val)
                      ? BigInt(val)
                      : typeof val === 'string' && /^-?\d+$/.test(val)
                        ? BigInt(val)
                        : val,
                  z.int64(),
                )
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  example: 1,
                  description:
                    'An issue in the repository to convert to a pull request. The issue title, body, and comments will become the title, body, and comments on the new pull request. Required unless `title` is specified.',
                }),
            })
            .openapi({ required: ['head', 'base'] }),
          examples: {
            default: {
              value: {
                title: 'Amazing new feature',
                body: 'Please pull these awesome changes in!',
                head: 'octocat:new-feature',
                base: 'master',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: PullRequestSchema,
          examples: { default: PullRequestExample },
        },
      },
      headers: z.object({
        Location: {
          example: 'https://api.github.com/repos/octocat/Hello-World/pulls/1347',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              example: 'https://api.github.com/repos/octocat/Hello-World/pulls/1347',
              param: { required: false },
            }),
        },
      }),
    },
    403: ForbiddenResponse,
    422: ValidationFailedResponse,
  },
})

