export const postReposOwnerRepoPullsPullNumberRequestedReviewersRoute = createRoute({
  method: 'post',
  path: '/repos/{owner}/{repo}/pulls/{pull_number}/requested_reviewers',
  tags: ['pulls'],
  summary: 'Request reviewers for a pull request',
  description:
    'Requests reviews for a pull request from a given set of users and/or teams.\nThis endpoint triggers [notifications](https://docs.github.com/github/managing-subscriptions-and-notifications-on-github/about-notifications). Creating content too quickly using this endpoint may result in secondary rate limiting. For more information, see "[Rate limits for the API](https://docs.github.com/rest/using-the-rest-api/rate-limits-for-the-rest-api#about-secondary-rate-limits)" and "[Best practices for using the REST API](https://docs.github.com/rest/guides/best-practices-for-using-the-rest-api)."',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/pulls/review-requests#request-reviewers-for-a-pull-request',
  },
  operationId: 'pulls/request-reviewers',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      pull_number: PullNumberParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .union([
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'reviewers')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['reviewers'] }),
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'team_reviewers')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['team_reviewers'] }),
            ])
            .and(
              z
                .object({
                  reviewers: z
                    .array(z.string())
                    .exactOptional()
                    .openapi({ description: 'An array of user `login`s that will be requested.' }),
                  team_reviewers: z
                    .array(z.string())
                    .exactOptional()
                    .openapi({ description: 'An array of team `slug`s that will be requested.' }),
                })
                .openapi({ required: [] }),
            ),
          examples: {
            default: {
              value: {
                reviewers: ['octocat', 'hubot', 'other_user'],
                team_reviewers: ['justice-league'],
              },
            },
          },
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: PullRequestSimpleSchema,
          examples: { default: PullRequestReviewRequestExample },
        },
      },
    },
    403: ForbiddenResponse,
    422: { description: 'Unprocessable Entity if user is not a collaborator' },
    503: ServiceUnavailableResponse,
  },
})

