export const postReposOwnerRepoReleasesRoute = createRoute({
  method: 'post',
  path: '/repos/{owner}/{repo}/releases',
  tags: ['repos'],
  summary: 'Create a release',
  description:
    'Users with push access to the repository can create a release.\n\n> [!NOTE]\n> If the commit identified by `target_commitish` (or, when `target_commitish` is omitted, the latest commit on the default branch) adds or modifies any file under `.github/workflows/` relative to the repository\'s default branch, the authenticating token must be authorized to modify workflows. Otherwise, this endpoint returns `404 Not Found`; some authentication paths surface `403 Resource not accessible by integration` instead.\n\nOAuth app tokens and personal access tokens (classic) need the `workflow` scope when the resolved target commit modifies workflow files. Fine-grained access tokens and GitHub App installation tokens also need the "Workflows" repository permission (write). The `GITHUB_TOKEN` available to GitHub Actions cannot be authorized for this; for more information, see "[Automatic token authentication](https://docs.github.com/actions/security-guides/automatic-token-authentication#permissions-for-the-github_token)".\n\nThis endpoint triggers [notifications](https://docs.github.com/github/managing-subscriptions-and-notifications-on-github/about-notifications). Creating content too quickly using this endpoint may result in secondary rate limiting. For more information, see "[Rate limits for the API](https://docs.github.com/rest/using-the-rest-api/rate-limits-for-the-rest-api#about-secondary-rate-limits)" and "[Best practices for using the REST API](https://docs.github.com/rest/guides/best-practices-for-using-the-rest-api)."',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/releases/releases#create-a-release',
  },
  operationId: 'repos/create-release',
  request: {
    params: z.object({ owner: OwnerParamsSchema, repo: RepoParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              tag_name: z.string().openapi({ description: 'The name of the tag.' }),
              target_commitish: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "Specifies the commitish value that determines where the Git tag is created from. Can be any branch or commit SHA. Unused if the Git tag already exists. Default: the repository's default branch.",
                }),
              name: z.string().exactOptional().openapi({ description: 'The name of the release.' }),
              body: z
                .string()
                .exactOptional()
                .openapi({ description: 'Text describing the contents of the tag.' }),
              draft: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    '`true` to create a draft (unpublished) release, `false` to create a published one.',
                }),
              prerelease: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    '`true` to identify the release as a prerelease. `false` to identify the release as a full release.',
                }),
              discussion_category_name: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'If specified, a discussion of the specified category is created and linked to the release. The value must be a category that already exists in the repository. For more information, see "[Managing categories for discussions in your repository](https://docs.github.com/discussions/managing-discussions-for-your-community/managing-categories-for-discussions-in-your-repository)."',
                }),
              generate_release_notes: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Whether to automatically generate the name and body for this release. If `name` is specified, the specified name will be used; otherwise, a name will be automatically generated. If `body` is specified, the body will be pre-pended to the automatically generated notes.',
                }),
              make_latest: z
                .enum(['true', 'false', 'legacy'])
                .default('true')
                .exactOptional()
                .openapi({
                  description:
                    'Specifies whether this release should be set as the latest release for the repository. Drafts and prereleases cannot be set as latest. Defaults to `true` for newly published releases. `legacy` specifies that the latest release should be determined based on the release creation date and higher semantic version.',
                }),
            })
            .openapi({ required: ['tag_name'] }),
          examples: {
            default: {
              value: {
                tag_name: 'v1.0.0',
                target_commitish: 'master',
                name: 'v1.0.0',
                body: 'Description of the release',
                draft: false,
                prerelease: false,
                generate_release_notes: false,
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': { schema: ReleaseSchema, examples: { default: ReleaseExample } },
      },
      headers: z.object({
        Location: {
          example: 'https://api.github.com/repos/octocat/Hello-World/releases/1',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              example: 'https://api.github.com/repos/octocat/Hello-World/releases/1',
              param: { required: false },
            }),
        },
      }),
    },
    404: {
      description: 'Not Found if the discussion category name is invalid',
      content: { 'application/json': { schema: BasicErrorSchema } },
    },
    422: ValidationFailedResponse,
  },
})

