export const patchReposOwnerRepoReleasesReleaseIdRoute = createRoute({
  method: 'patch',
  path: '/repos/{owner}/{repo}/releases/{release_id}',
  tags: ['repos'],
  summary: 'Update a release',
  description:
    'Users with push access to the repository can edit a release.\n\n> [!NOTE]\n> If the resolved target commit (the new value of `target_commitish` if you are changing it, otherwise the existing target) adds or modifies any file under `.github/workflows/` relative to the repository\'s default branch, the authenticating token must be authorized to modify workflows. Otherwise, this endpoint returns `404 Not Found`; some authentication paths surface `403 Resource not accessible by integration` instead.\n\nOAuth app tokens and personal access tokens (classic) need the `workflow` scope when the resolved target commit modifies workflow files. Fine-grained access tokens and GitHub App installation tokens also need the "Workflows" repository permission (write). The `GITHUB_TOKEN` available to GitHub Actions cannot be authorized for this; for more information, see "[Automatic token authentication](https://docs.github.com/actions/security-guides/automatic-token-authentication#permissions-for-the-github_token)".',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/releases/releases#update-a-release',
  },
  operationId: 'repos/update-release',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      release_id: ReleaseIdParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              tag_name: z.string().exactOptional().openapi({ description: 'The name of the tag.' }),
              target_commitish: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "Specifies the commitish value that determines where the Git tag is created from. Can be any branch or commit SHA. Unused if the Git tag already exists. Default: the repository's default branch.",
                }),
              name: z.string().exactOptional().openapi({ description: 'The name of the release.' }),
              body: z
                .string()
                .exactOptional()
                .openapi({ description: 'Text describing the contents of the tag.' }),
              draft: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    '`true` makes the release a draft, and `false` publishes the release.',
                }),
              prerelease: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    '`true` to identify the release as a prerelease, `false` to identify the release as a full release.',
                }),
              make_latest: z
                .enum(['true', 'false', 'legacy'])
                .default('true')
                .exactOptional()
                .openapi({
                  description:
                    'Specifies whether this release should be set as the latest release for the repository. Drafts and prereleases cannot be set as latest. Defaults to `true` for newly published releases. `legacy` specifies that the latest release should be determined based on the release creation date and higher semantic version.',
                }),
              discussion_category_name: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'If specified, a discussion of the specified category is created and linked to the release. The value must be a category that already exists in the repository. If there is already a discussion linked to the release, this parameter is ignored. For more information, see "[Managing categories for discussions in your repository](https://docs.github.com/discussions/managing-discussions-for-your-community/managing-categories-for-discussions-in-your-repository)."',
                }),
            })
            .openapi({ required: [] }),
          examples: {
            default: {
              value: {
                tag_name: 'v1.0.0',
                target_commitish: 'master',
                name: 'v1.0.0',
                body: 'Description of the release',
                draft: false,
                prerelease: false,
              },
            },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': { schema: ReleaseSchema, examples: { default: ReleaseExample } },
      },
    },
    404: {
      description: 'Not Found if the discussion category name is invalid',
      content: { 'application/json': { schema: BasicErrorSchema } },
    },
  },
})

