export const postReposOwnerRepoRulesetsRoute = createRoute({
  method: 'post',
  path: '/repos/{owner}/{repo}/rulesets',
  tags: ['repos'],
  summary: 'Create a repository ruleset',
  description: 'Create a ruleset for a repository.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/repos/rules#create-a-repository-ruleset',
  },
  operationId: 'repos/create-repo-ruleset',
  request: {
    params: z.object({ owner: OwnerParamsSchema, repo: RepoParamsSchema }),
    body: {
      description: 'Request body',
      content: {
        'application/json': {
          schema: z
            .object({
              name: z.string().openapi({ description: 'The name of the ruleset.' }),
              target: z
                .enum(['branch', 'tag', 'push'])
                .default('branch')
                .exactOptional()
                .openapi({ description: 'The target of the ruleset' }),
              enforcement: RepositoryRuleEnforcementSchema,
              bypass_actors: z
                .array(RepositoryRulesetBypassActorSchema)
                .exactOptional()
                .openapi({ description: 'The actors that can bypass the rules in this ruleset' }),
              conditions: RepositoryRulesetConditionsSchema.exactOptional(),
              rules: z
                .array(RepositoryRuleSchema)
                .exactOptional()
                .openapi({ description: 'An array of rules within the ruleset.' }),
            })
            .openapi({ required: ['name', 'enforcement'] }),
          examples: {
            default: {
              value: {
                name: 'super cool ruleset',
                target: 'branch',
                enforcement: 'active',
                bypass_actors: [{ actor_id: 234, actor_type: 'Team', bypass_mode: 'always' }],
                conditions: {
                  ref_name: {
                    include: ['refs/heads/main', 'refs/heads/master'],
                    exclude: ['refs/heads/dev*'],
                  },
                },
                rules: [
                  {
                    type: 'commit_author_email_pattern',
                    parameters: { operator: 'contains', pattern: 'github' },
                  },
                ],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: RepositoryRulesetSchema,
          examples: { default: RepositoryRulesetExample },
        },
      },
    },
    404: NotFoundResponse,
    422: ValidationFailedResponse,
    500: InternalErrorResponse,
  },
})

