export const getReposOwnerRepoRulesetsRulesetIdRoute = createRoute({
  method: 'get',
  path: '/repos/{owner}/{repo}/rulesets/{ruleset_id}',
  tags: ['repos'],
  summary: 'Get a repository ruleset',
  description:
    'Get a ruleset for a repository.\n\n**Note:** To prevent leaking sensitive information, the `bypass_actors` property is only returned if the user\nmaking the API request has write access to the ruleset.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/repos/rules#get-a-repository-ruleset',
  },
  operationId: 'repos/get-repo-ruleset',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      ruleset_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'ruleset_id',
            description: 'The ID of the ruleset.',
            in: 'path',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
    query: z.object({
      includes_parents: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            name: 'includes_parents',
            description:
              'Include rulesets configured at higher levels that apply to this repository',
            in: 'query',
            required: false,
            schema: { type: 'boolean', default: true },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: RepositoryRulesetSchema,
          examples: { default: RepositoryRulesetExample },
        },
      },
    },
    404: NotFoundResponse,
    500: InternalErrorResponse,
  },
})

