export const patchReposOwnerRepoSecretScanningAlertsAlertNumberRoute = createRoute({
  method: 'patch',
  path: '/repos/{owner}/{repo}/secret-scanning/alerts/{alert_number}',
  tags: ['secret-scanning'],
  summary: 'Update a secret scanning alert',
  description:
    'Updates the status of a secret scanning alert in an eligible repository.\n\nYou can also use this endpoint to assign or unassign an alert to a user who has write access to the repository.\n\nThe authenticated user must be an administrator for the repository or for the organization that owns the repository to use this endpoint.\n\nOAuth app tokens and personal access tokens (classic) need the `repo` or `security_events` scope to use this endpoint. If this endpoint is only used with public repositories, the token can use the `public_repo` scope instead.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/secret-scanning/secret-scanning#update-a-secret-scanning-alert',
  },
  operationId: 'secret-scanning/update-alert',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      alert_number: AlertNumberParamsSchema,
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .union([
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'state')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['state'] }),
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'assignee')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['assignee'] }),
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'validity')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['validity'] }),
            ])
            .and(
              z
                .object({
                  state: SecretScanningAlertStateSchema.exactOptional(),
                  resolution: SecretScanningAlertResolutionSchema.exactOptional(),
                  resolution_comment: SecretScanningAlertResolutionCommentSchema.exactOptional(),
                  assignee: SecretScanningAlertAssigneeSchema.exactOptional(),
                  validity: z
                    .enum(['active', 'inactive'])
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        'Sets the validity of the secret scanning alert. Can be `active`, `inactive`, or `null` to clear the override.',
                    }),
                })
                .openapi({ required: [] }),
            ),
          examples: {
            default: { value: { state: 'resolved', resolution: 'false_positive' } },
            assign: { summary: 'Assign alert to a user', value: { assignee: 'octocat' } },
            unassign: { summary: 'Unassign alert', value: { assignee: null } },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: SecretScanningAlertWithMetadataSchema,
          examples: { default: SecretScanningAlertResolvedExample },
        },
      },
    },
    400: {
      description: 'Bad request, resolution comment is invalid or the resolution was not changed.',
    },
    403: {
      description:
        'Delegated alert dismissal is enabled and the authenticated user is not a valid reviewer.',
    },
    404: {
      description:
        'Repository is public, or secret scanning is disabled for the repository, or the resource is not found',
    },
    422: {
      description:
        'State does not match the resolution or resolution comment, assignee does not have write access to the repository, or the requested validity change could not be applied to this alert',
    },
    503: ServiceUnavailableResponse,
  },
})

