export const getReposOwnerRepoStargazersHistoryRoute = createRoute({
  method: 'get',
  path: '/repos/{owner}/{repo}/stargazers/history',
  tags: ['activity'],
  summary: 'Get repository star history',
  description:
    "Returns repository stars grouped by calendar weeks, most recent first. Pages move backward toward the repository's creation week, and weeks within a page are ordered newest to oldest, so concatenating pages produces one continuous series. Weeks without stars contain zero counts. Week and day boundaries are not guaranteed to align with UTC. The `days` array contains the number of stars created on each day of the week, starting on Sunday.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/activity/starring#get-repository-star-history',
  },
  operationId: 'activity/get-stargazer-history-for-repo',
  request: {
    params: z.object({ owner: OwnerParamsSchema, repo: RepoParamsSchema }),
    query: z.object({
      per_page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(30),
        )
        .default(30)
        .exactOptional()
        .openapi({
          param: {
            name: 'per_page',
            description:
              'The number of results per page (max 30). For more information, see "[Using pagination in the REST API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the-rest-api)."',
            in: 'query',
            schema: { type: 'integer', default: 30, minimum: 1, maximum: 30 },
            required: false,
          },
        }),
      page: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(1)
        .exactOptional()
        .openapi({
          param: {
            name: 'page',
            description:
              'The page number of the results to fetch (max 100). For more information, see "[Using pagination in the REST API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the-rest-api)."',
            in: 'query',
            schema: { type: 'integer', default: 1, minimum: 1, maximum: 100 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Repository star history',
      content: {
        'application/json': {
          schema: z.array(StargazerHistorySchema).max(30),
          examples: {
            default: { value: [{ week: 1754784000, total: 19, days: [0, 12, 7, 0, 0, 0, 0] }] },
          },
        },
      },
      headers: z.object({ Link: LinkHeaderSchema }),
    },
    422: ValidationFailedResponse,
  },
})

