export const postReposOwnerRepoStatusesShaRoute = createRoute({
  method: 'post',
  path: '/repos/{owner}/{repo}/statuses/{sha}',
  tags: ['repos'],
  summary: 'Create a commit status',
  description:
    'Users with push access in a repository can create commit statuses for a given SHA.\n\nNote: there is a limit of 1000 statuses per `sha` and `context` within a repository. Attempts to create more than 1000 statuses will result in a validation error.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/commits/statuses#create-a-commit-status',
  },
  operationId: 'repos/create-commit-status',
  request: {
    params: z.object({
      owner: OwnerParamsSchema,
      repo: RepoParamsSchema,
      sha: z
        .string()
        .openapi({
          param: {
            name: 'sha',
            in: 'path',
            required: true,
            schema: { type: 'string' },
            'x-multi-segment': true,
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              state: z
                .enum(['error', 'failure', 'pending', 'success'])
                .openapi({ description: 'The state of the status.' }),
              target_url: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'The target URL to associate with this status. This URL will be linked from the GitHub UI to allow users to easily see the source of the status.  \nFor example, if your continuous integration system is posting build status, you would want to provide the deep link for the build output for this specific SHA:  \n`http://ci.example.com/user/repo/build/sha`',
                }),
              description: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({ description: 'A short description of the status.' }),
              context: z
                .string()
                .default('default')
                .exactOptional()
                .openapi({
                  description:
                    'A string label to differentiate this status from the status of other systems. This field is case-insensitive.',
                }),
            })
            .openapi({ required: ['state'] }),
          examples: {
            default: {
              value: {
                state: 'success',
                target_url: 'https://example.com/build/status',
                description: 'The build succeeded!',
                context: 'continuous-integration/jenkins',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': { schema: StatusSchema, examples: { default: StatusExample } },
      },
      headers: z.object({
        Location: {
          example:
            'https://api.github.com/repos/octocat/Hello-World/statuses/6dcb09b5b57875f334f61aebed695e2e4193db5e',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              example:
                'https://api.github.com/repos/octocat/Hello-World/statuses/6dcb09b5b57875f334f61aebed695e2e4193db5e',
              param: { required: false },
            }),
        },
      }),
    },
  },
})

