export const postReposTemplateOwnerTemplateRepoGenerateRoute = createRoute({
  method: 'post',
  path: '/repos/{template_owner}/{template_repo}/generate',
  tags: ['repos'],
  summary: 'Create a repository using a template',
  description:
    "Creates a new repository using a repository template. Use the `template_owner` and `template_repo` route parameters to specify the repository to use as the template. If the repository is not public, the authenticated user must own or be a member of an organization that owns the repository. To check if a repository is available to use as a template, get the repository's information using the [Get a repository](https://docs.github.com/rest/repos/repos#get-a-repository) endpoint and check that the `is_template` key is `true`.\n\nOAuth app tokens and personal access tokens (classic) need the `public_repo` or `repo` scope to create a public repository, and `repo` scope to create a private repository.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/repos/repos#create-a-repository-using-a-template',
  },
  operationId: 'repos/create-using-template',
  request: {
    params: z.object({
      template_owner: z
        .string()
        .openapi({
          param: {
            name: 'template_owner',
            description:
              'The account owner of the template repository. The name is not case sensitive.',
            in: 'path',
            required: true,
            schema: { type: 'string' },
          },
        }),
      template_repo: z
        .string()
        .openapi({
          param: {
            name: 'template_repo',
            description:
              'The name of the template repository without the `.git` extension. The name is not case sensitive.',
            in: 'path',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              owner: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The organization or person who will own the new repository. To create a new repository in an organization, the authenticated user must be a member of the specified organization.',
                }),
              name: z.string().openapi({ description: 'The name of the new repository.' }),
              description: z
                .string()
                .exactOptional()
                .openapi({ description: 'A short description of the new repository.' }),
              include_all_branches: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Set to `true` to include the directory structure and files from all branches in the template repository, and not just the default branch. Default: `false`.',
                }),
              private: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Either `true` to create a new private repository or `false` to create a new public one.',
                }),
            })
            .openapi({ required: ['name'] }),
          examples: {
            default: {
              value: {
                owner: 'octocat',
                name: 'Hello-World',
                description: 'This is your first repository',
                include_all_branches: false,
                private: false,
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: FullRepositorySchema,
          examples: { default: FullRepositoryExample },
        },
      },
      headers: z.object({
        Location: {
          example: 'https://api.github.com/repos/octocat/Hello-World',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              example: 'https://api.github.com/repos/octocat/Hello-World',
              param: { required: false },
            }),
        },
      }),
    },
  },
})

