export const getSearchIssuesRoute = createRoute({
  method: 'get',
  path: '/search/issues',
  tags: ['search'],
  summary: 'Search issues and pull requests',
  description:
    'Find issues by state and keyword. This method returns up to 100 results [per page](https://docs.github.com/rest/guides/using-pagination-in-the-rest-api).\n\nWhen searching for issues, you can get text match metadata for the issue **title**, issue **body**, and issue **comment body** fields when you pass the `text-match` media type. For more details about how to receive highlighted\nsearch results, see [Text match metadata](https://docs.github.com/rest/search/search#text-match-metadata).\n\nFor example, if you want to find the oldest unresolved Python bugs on Windows. Your query might look something like this.\n\n`q=windows+label:bug+language:python+state:open&sort=created&order=asc`\n\nThis query searches for the keyword `windows`, within any open issue that is labeled as `bug`. The search runs across repositories whose primary language is Python. The results are sorted by creation date in ascending order, which means the oldest issues appear first in the search results.\n\n> [!NOTE]\n> For requests made by GitHub Apps with a user access token, you can\'t retrieve a combination of issues and pull requests in a single query. Requests that don\'t include the `is:issue` or `is:pull-request` qualifier will receive an HTTP `422 Unprocessable Entity` response. To get results for both issues and pull requests, you must send separate queries for issues and pull requests. For more information about the `is` qualifier, see "[Searching only issues or pull requests](https://docs.github.com/github/searching-for-information-on-github/searching-issues-and-pull-requests#search-only-issues-or-pull-requests)."',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/search/search#search-issues-and-pull-requests',
  },
  operationId: 'search/issues-and-pull-requests',
  request: {
    query: z.object({
      q: z
        .string()
        .openapi({
          param: {
            name: 'q',
            description:
              'The query contains one or more search keywords and qualifiers. Qualifiers allow you to limit your search to specific areas of GitHub. The REST API supports the same qualifiers as the web interface for GitHub. To learn more about the format of the query, see [Constructing a search query](https://docs.github.com/rest/search/search#constructing-a-search-query). See "[Searching issues and pull requests](https://docs.github.com/search-github/searching-on-github/searching-issues-and-pull-requests)" for a detailed list of qualifiers.',
            in: 'query',
            required: true,
            schema: { type: 'string' },
          },
        }),
      sort: z
        .enum([
          'comments',
          'reactions',
          'reactions-+1',
          'reactions--1',
          'reactions-smile',
          'reactions-thinking_face',
          'reactions-heart',
          'reactions-tada',
          'interactions',
          'created',
          'updated',
        ])
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            description:
              'Sorts the results of your query by the number of `comments`, `reactions`, `reactions-+1`, `reactions--1`, `reactions-smile`, `reactions-thinking_face`, `reactions-heart`, `reactions-tada`, or `interactions`. You can also sort results by how recently the items were `created` or `updated`, Default: [best match](https://docs.github.com/rest/search/search#ranking-search-results)',
            in: 'query',
            required: false,
            schema: {
              type: 'string',
              enum: [
                'comments',
                'reactions',
                'reactions-+1',
                'reactions--1',
                'reactions-smile',
                'reactions-thinking_face',
                'reactions-heart',
                'reactions-tada',
                'interactions',
                'created',
                'updated',
              ],
            },
          },
        }),
      order: OrderParamsSchema,
      per_page: PerPageParamsSchema,
      page: PageParamsSchema,
      advanced_search: IssuesAdvancedSearchParamsSchema,
      search_type: SearchTypeParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z
            .object({
              total_count: z.int(),
              incomplete_results: z.boolean(),
              items: z.array(IssueSearchResultItemSchema),
              search_type: z
                .enum(['lexical', 'semantic', 'hybrid'])
                .openapi({
                  description:
                    'The type of search that was performed. Possible values are `lexical`, `semantic`, or `hybrid`.',
                }),
              lexical_fallback_reason: z
                .array(
                  z.enum([
                    'no_text_terms',
                    'quoted_text',
                    'non_issue_target',
                    'or_boolean_not_supported',
                    'no_accessible_repos',
                    'server_error',
                    'only_non_semantic_fields_requested',
                    'service_unavailable',
                  ]),
                )
                .exactOptional()
                .openapi({
                  description:
                    'When a semantic or hybrid search falls back to lexical search, this field contains the reasons for the fallback. Only present when a fallback occurred.',
                }),
            })
            .openapi({ required: ['total_count', 'incomplete_results', 'items', 'search_type'] }),
          examples: {
            default: IssueSearchResultItemPaginatedExample,
            'lexical-fallback': IssueSearchResultItemPaginatedLexicalFallbackExample,
          },
        },
      },
    },
    304: NotModifiedResponse,
    401: RequiresAuthenticationResponse,
    403: ForbiddenResponse,
    422: ValidationFailedResponse,
    503: ServiceUnavailableResponse,
  },
})

export const getSearchLabelsRoute = createRoute({
  method: 'get',
  path: '/search/labels',
  tags: ['search'],
  summary: 'Search labels',
  description:
    'Find labels in a repository with names or descriptions that match search keywords. Returns up to 100 results [per page](https://docs.github.com/rest/guides/using-pagination-in-the-rest-api).\n\nWhen searching for labels, you can get text match metadata for the label **name** and **description** fields when you pass the `text-match` media type. For more details about how to receive highlighted search results, see [Text match metadata](https://docs.github.com/rest/search/search#text-match-metadata).\n\nFor example, if you want to find labels in the `linguist` repository that match `bug`, `defect`, or `enhancement`. Your query might look like this:\n\n`q=bug+defect+enhancement&repository_id=64778136`\n\nThe labels that best match the query appear first in the search results.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/search/search#search-labels',
  },
  operationId: 'search/labels',
  request: {
    query: z.object({
      repository_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'repository_id',
            description: 'The id of the repository.',
            in: 'query',
            required: true,
            schema: { type: 'integer' },
          },
        }),
      q: z
        .string()
        .openapi({
          param: {
            name: 'q',
            description:
              'The search keywords. This endpoint does not accept qualifiers in the query. To learn more about the format of the query, see [Constructing a search query](https://docs.github.com/rest/search/search#constructing-a-search-query).',
            in: 'query',
            required: true,
            schema: { type: 'string' },
          },
        }),
      sort: z
        .enum(['created', 'updated'])
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            description:
              'Sorts the results of your query by when the label was `created` or `updated`. Default: [best match](https://docs.github.com/rest/search/search#ranking-search-results)',
            in: 'query',
            required: false,
            schema: { type: 'string', enum: ['created', 'updated'] },
          },
        }),
      order: OrderParamsSchema,
      per_page: PerPageParamsSchema,
      page: PageParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z
            .object({
              total_count: z.int(),
              incomplete_results: z.boolean(),
              items: z.array(LabelSearchResultItemSchema),
            })
            .openapi({ required: ['total_count', 'incomplete_results', 'items'] }),
          examples: { default: LabelSearchResultItemPaginatedExample },
        },
      },
    },
    304: NotModifiedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

