export const patchTeamsTeamIdRoute = createRoute({
  method: 'patch',
  path: '/teams/{team_id}',
  tags: ['teams'],
  summary: 'Update a team (Legacy)',
  description:
    '> [!WARNING]\n> **Endpoint closing down notice:** This endpoint route is closing down and will be removed from the Teams API. We recommend migrating your existing code to use the new [Update a team](https://docs.github.com/rest/teams/teams#update-a-team) endpoint.\n\nTo edit a team, the authenticated user must either be an organization owner or a team maintainer.\n\n> [!NOTE]\n> With nested teams, the `privacy` for parent teams cannot be `secret`.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/teams/teams#update-a-team-legacy',
  },
  operationId: 'teams/update-legacy',
  request: {
    params: z.object({ team_id: TeamIdParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              name: z.string().openapi({ description: 'The name of the team.' }),
              description: z
                .string()
                .exactOptional()
                .openapi({ description: 'The description of the team.' }),
              privacy: z
                .enum(['secret', 'closed'])
                .exactOptional()
                .openapi({
                  description:
                    'The level of privacy this team should have. Editing teams without specifying this parameter leaves `privacy` intact. The options are:  \n**For a non-nested team:**  \n * `secret` - only visible to organization owners and members of this team.  \n * `closed` - visible to all members of this organization.  \n**For a parent or child team:**  \n * `closed` - visible to all members of this organization.',
                }),
              notification_setting: z
                .enum(['notifications_enabled', 'notifications_disabled'])
                .exactOptional()
                .openapi({
                  description:
                    'The notification setting the team has chosen. Editing teams without specifying this parameter leaves `notification_setting` intact. The options are: \n * `notifications_enabled` - team members receive notifications when the team is @mentioned.  \n * `notifications_disabled` - no one receives notifications.',
                }),
              permission: z
                .enum(['pull', 'push', 'admin'])
                .default('pull')
                .exactOptional()
                .openapi({
                  description:
                    '**Closing down notice**. The permission that new repositories will be added to the team with when none is specified.',
                }),
              parent_team_id: z
                .int()
                .nullable()
                .exactOptional()
                .openapi({ description: 'The ID of a team to set as the parent team.' }),
              parent_team_slug: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'The slug of a team to set as the parent team. Ignored when `parent_team_id` is also provided.',
                }),
            })
            .openapi({ required: ['name'] }),
          examples: {
            default: {
              value: {
                name: 'new team name',
                description: 'new team description',
                privacy: 'closed',
                notification_setting: 'notifications_enabled',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Response when the updated information already exists',
      content: {
        'application/json': { schema: TeamFullSchema, examples: { default: TeamFullExample } },
      },
    },
    201: {
      description: 'Response',
      content: {
        'application/json': { schema: TeamFullSchema, examples: { default: TeamFullExample } },
      },
    },
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
  deprecated: true,
})

