export const putUserCodespacesSecretsSecretNameRoute = createRoute({
  method: 'put',
  path: '/user/codespaces/secrets/{secret_name}',
  tags: ['codespaces'],
  summary: 'Create or update a secret for the authenticated user',
  description:
    'Creates or updates a development environment secret for a user\'s codespace with an encrypted value. Encrypt your secret using\n[LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages). For more information, see "[Encrypting secrets for the REST API](https://docs.github.com/rest/guides/encrypting-secrets-for-the-rest-api)."\n\nThe authenticated user must have Codespaces access to use this endpoint.\n\nOAuth app tokens and personal access tokens (classic) need the `codespace` or `codespace:secrets` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/codespaces/secrets#create-or-update-a-secret-for-the-authenticated-user',
  },
  operationId: 'codespaces/create-or-update-secret-for-authenticated-user',
  request: {
    params: z.object({ secret_name: SecretNameParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              encrypted_value: z
                .string()
                .regex(
                  /^(?:[A-Za-z0-9+\/]{4})*(?:[A-Za-z0-9+\/]{2}==|[A-Za-z0-9+\/]{3}=|[A-Za-z0-9+\/]{4})$/,
                )
                .exactOptional()
                .openapi({
                  description:
                    'Value for your secret, encrypted with [LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages) using the public key retrieved from the [Get the public key for the authenticated user](https://docs.github.com/rest/codespaces/secrets#get-public-key-for-the-authenticated-user) endpoint.',
                }),
              key_id: z
                .string()
                .openapi({ description: 'ID of the key you used to encrypt the secret.' }),
              selected_repository_ids: z
                .array(z.union([z.int(), z.string()]))
                .exactOptional()
                .openapi({
                  description:
                    'An array of repository ids that can access the user secret. You can manage the list of selected repositories using the [List selected repositories for a user secret](https://docs.github.com/rest/codespaces/secrets#list-selected-repositories-for-a-user-secret), [Set selected repositories for a user secret](https://docs.github.com/rest/codespaces/secrets#set-selected-repositories-for-a-user-secret), and [Remove a selected repository from a user secret](https://docs.github.com/rest/codespaces/secrets#remove-a-selected-repository-from-a-user-secret) endpoints.',
                }),
            })
            .openapi({ required: ['key_id'] }),
          examples: {
            default: {
              value: {
                encrypted_value: 'c2VjcmV0',
                key_id: '012345678912345678',
                selected_repository_ids: ['1234567', '2345678'],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response after successfully creating a secret',
      content: {
        'application/json': { schema: EmptyObjectSchema, examples: { default: { value: null } } },
      },
    },
    204: { description: 'Response after successfully updating a secret' },
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

