export const putUserCodespacesSecretsSecretNameRepositoriesRepositoryIdRoute = createRoute({
  method: 'put',
  path: '/user/codespaces/secrets/{secret_name}/repositories/{repository_id}',
  tags: ['codespaces'],
  summary: 'Add a selected repository to a user secret',
  description:
    "Adds a repository to the selected repositories for a user's development environment secret.\n\nThe authenticated user must have Codespaces access to use this endpoint.\n\nOAuth app tokens and personal access tokens (classic) need the `codespace` or `codespace:secrets` scope to use this endpoint.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/codespaces/secrets#add-a-selected-repository-to-a-user-secret',
  },
  operationId: 'codespaces/add-repository-for-secret-for-authenticated-user',
  request: {
    params: z.object({
      secret_name: SecretNameParamsSchema,
      repository_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: { name: 'repository_id', in: 'path', required: true, schema: { type: 'integer' } },
        }),
    }),
  },
  responses: {
    204: { description: 'No Content when repository was added to the selected list' },
    401: RequiresAuthenticationResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    500: InternalErrorResponse,
  },
})

