export const postUserEmailsRoute = createRoute({
  method: 'post',
  path: '/user/emails',
  tags: ['users'],
  summary: 'Add an email address for the authenticated user',
  description:
    'OAuth app tokens and personal access tokens (classic) need the `user` scope to use this endpoint.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/users/emails#add-an-email-address-for-the-authenticated-user',
  },
  operationId: 'users/add-email-for-authenticated-user',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z.xor([
            z
              .object({
                emails: z
                  .array(z.string().openapi({ example: 'username@example.com' }))
                  .min(1)
                  .openapi({
                    description:
                      'Adds one or more email addresses to your GitHub account. Must contain at least one email address. **Note:** Alternatively, you can pass a single email address or an `array` of emails addresses directly, but we recommend that you pass an object using the `emails` key.',
                    example: [],
                  }),
              })
              .openapi({
                required: ['emails'],
                example: { emails: ['octocat@github.com', 'mona@github.com'] },
              }),
            z.array(z.string().openapi({ example: 'username@example.com' })).min(1),
            z.string(),
          ]),
          examples: {
            default: {
              summary: 'Example adding multiple email addresses',
              value: { emails: ['octocat@github.com', 'mona@github.com', 'octocat@octocat.org'] },
            },
          },
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z.array(EmailSchema),
          examples: { default: EmailItemsExample },
        },
      },
    },
    304: NotModifiedResponse,
    401: RequiresAuthenticationResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

