export const getUserIssuesRoute = createRoute({
  method: 'get',
  path: '/user/issues',
  tags: ['issues'],
  summary: 'List user account issues assigned to the authenticated user',
  description:
    'List issues across owned and member repositories assigned to the authenticated user.\n\n> [!NOTE]\n> GitHub\'s REST API considers every pull request an issue, but not every issue is a pull request. For this reason, "Issues" endpoints may return both issues and pull requests in the response. You can identify pull requests by the `pull_request` key. Be aware that the `id` of a pull request returned from "Issues" endpoints will be an _issue id_. To find out the pull request id, use the "[List pull requests](https://docs.github.com/rest/pulls/pulls#list-pull-requests)" endpoint.\n\nThis endpoint supports the following custom media types. For more information, see "[Media types](https://docs.github.com/rest/using-the-rest-api/getting-started-with-the-rest-api#media-types)."\n\n- **`application/vnd.github.raw+json`**: Returns the raw markdown body. Response will include `body`. This is the default if you do not pass any specific media type.\n- **`application/vnd.github.text+json`**: Returns a text only representation of the markdown body. Response will include `body_text`.\n- **`application/vnd.github.html+json`**: Returns HTML rendered from the body\'s markdown. Response will include `body_html`.\n- **`application/vnd.github.full+json`**: Returns raw, text, and HTML representations. Response will include `body`, `body_text`, and `body_html`.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/issues/issues#list-user-account-issues-assigned-to-the-authenticated-user',
  },
  operationId: 'issues/list-for-authenticated-user',
  request: {
    query: z.object({
      filter: z
        .enum(['assigned', 'created', 'mentioned', 'subscribed', 'repos', 'all'])
        .default('assigned')
        .exactOptional()
        .openapi({
          param: {
            name: 'filter',
            description:
              "Indicates which sorts of issues to return. `assigned` means issues assigned to you. `created` means issues created by you. `mentioned` means issues mentioning you. `subscribed` means issues you're subscribed to updates for. `all` or `repos` means all issues you can see, regardless of participation or creation.",
            in: 'query',
            required: false,
            schema: {
              type: 'string',
              enum: ['assigned', 'created', 'mentioned', 'subscribed', 'repos', 'all'],
              default: 'assigned',
            },
          },
        }),
      state: z
        .enum(['open', 'closed', 'all'])
        .default('open')
        .exactOptional()
        .openapi({
          param: {
            name: 'state',
            description: 'Indicates the state of the issues to return.',
            in: 'query',
            required: false,
            schema: { type: 'string', enum: ['open', 'closed', 'all'], default: 'open' },
          },
        }),
      labels: LabelsParamsSchema,
      sort: z
        .enum(['created', 'updated', 'comments'])
        .default('created')
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            description: 'What to sort results by.',
            in: 'query',
            required: false,
            schema: {
              type: 'string',
              enum: ['created', 'updated', 'comments'],
              default: 'created',
            },
          },
        }),
      direction: DirectionParamsSchema,
      since: SinceParamsSchema,
      per_page: PerPageParamsSchema,
      page: PageParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z.array(IssueSchema),
          examples: { default: IssueWithRepoItemsExample },
        },
      },
      headers: z.object({ Link: LinkHeaderSchema }),
    },
    304: NotModifiedResponse,
    404: NotFoundResponse,
  },
})

