export const postUserKeysRoute = createRoute({
  method: 'post',
  path: '/user/keys',
  tags: ['users'],
  summary: 'Create a public SSH key for the authenticated user',
  description:
    "Adds a public SSH key to the authenticated user's GitHub account.\n\nOAuth app tokens and personal access tokens (classic) need the `write:public_key` scope to use this endpoint.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/users/keys#create-a-public-ssh-key-for-the-authenticated-user',
  },
  operationId: 'users/create-public-ssh-key-for-authenticated-user',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              title: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'A descriptive name for the new key.',
                  example: 'Personal MacBook Air',
                }),
              key: z
                .string()
                .regex(/^ssh-(rsa|dss|ed25519) |^ecdsa-sha2-nistp(256|384|521) /)
                .openapi({ description: 'The public SSH key to add to your GitHub account.' }),
            })
            .openapi({ required: ['key'] }),
          examples: {
            default: {
              value: {
                title: 'ssh-rsa AAAAB3NzaC1yc2EAAA',
                key: '2Sg8iYjAxxmI2LvUXpJjkYrMxURPc8r+dB7TJyvv1234',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: { 'application/json': { schema: KeySchema, examples: { default: KeyExample } } },
    },
    304: NotModifiedResponse,
    401: RequiresAuthenticationResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

