export const getUserReposRoute = createRoute({
  method: 'get',
  path: '/user/repos',
  tags: ['repos'],
  summary: 'List repositories for the authenticated user',
  description:
    'Lists repositories that the authenticated user has explicit permission (`:read`, `:write`, or `:admin`) to access.\n\nThe authenticated user has explicit permission to access repositories they own, repositories where they are a collaborator, and repositories that they can access through an organization membership.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/repos/repos#list-repositories-for-the-authenticated-user',
  },
  operationId: 'repos/list-for-authenticated-user',
  request: {
    query: z.object({
      visibility: z
        .enum(['all', 'public', 'private'])
        .default('all')
        .exactOptional()
        .openapi({
          param: {
            name: 'visibility',
            description: 'Limit results to repositories with the specified visibility.',
            in: 'query',
            required: false,
            schema: { type: 'string', enum: ['all', 'public', 'private'], default: 'all' },
          },
        }),
      affiliation: z
        .string()
        .default('owner,collaborator,organization_member')
        .exactOptional()
        .openapi({
          param: {
            name: 'affiliation',
            description:
              'Comma-separated list of values. Can include:  \n * `owner`: Repositories that are owned by the authenticated user.  \n * `collaborator`: Repositories that the user has been added to as a collaborator.  \n * `organization_member`: Repositories that the user has access to through being a member of an organization. This includes every repository on every team that the user is on.',
            in: 'query',
            required: false,
            schema: { type: 'string', default: 'owner,collaborator,organization_member' },
          },
        }),
      type: z
        .enum(['all', 'owner', 'public', 'private', 'member'])
        .default('all')
        .exactOptional()
        .openapi({
          param: {
            name: 'type',
            description:
              'Limit results to repositories of the specified type. Will cause a `422` error if used in the same request as **visibility** or **affiliation**.',
            in: 'query',
            required: false,
            schema: {
              type: 'string',
              enum: ['all', 'owner', 'public', 'private', 'member'],
              default: 'all',
            },
          },
        }),
      sort: z
        .enum(['created', 'updated', 'pushed', 'full_name'])
        .default('full_name')
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            description: 'The property to sort the results by.',
            in: 'query',
            required: false,
            schema: {
              type: 'string',
              enum: ['created', 'updated', 'pushed', 'full_name'],
              default: 'full_name',
            },
          },
        }),
      direction: z
        .enum(['asc', 'desc'])
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            description:
              'The order to sort by. Default: `asc` when using `full_name`, otherwise `desc`.',
            in: 'query',
            required: false,
            schema: { type: 'string', enum: ['asc', 'desc'] },
          },
        }),
      per_page: PerPageParamsSchema,
      page: PageParamsSchema,
      since: SinceRepoDateParamsSchema,
      before: BeforeRepoDateParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z.array(RepositorySchema),
          examples: { default: RepositoryItemsDefaultResponseExample },
        },
      },
      headers: z.object({ Link: LinkHeaderSchema }),
    },
    304: NotModifiedResponse,
    401: RequiresAuthenticationResponse,
    403: ForbiddenResponse,
    422: ValidationFailedResponse,
  },
})

