export const postUserSshSigningKeysRoute = createRoute({
  method: 'post',
  path: '/user/ssh_signing_keys',
  tags: ['users'],
  summary: 'Create a SSH signing key for the authenticated user',
  description:
    "Creates an SSH signing key for the authenticated user's GitHub account.\n\nOAuth app tokens and personal access tokens (classic) need the `write:ssh_signing_key` scope to use this endpoint.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/users/ssh-signing-keys#create-a-ssh-signing-key-for-the-authenticated-user',
  },
  operationId: 'users/create-ssh-signing-key-for-authenticated-user',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              title: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'A descriptive name for the new key.',
                  example: 'Personal MacBook Air',
                }),
              key: z
                .string()
                .regex(
                  /^ssh-(rsa|dss|ed25519) |^ecdsa-sha2-nistp(256|384|521) |^(sk-ssh-ed25519|sk-ecdsa-sha2-nistp256)@openssh.com /,
                )
                .openapi({
                  description:
                    'The public SSH key to add to your GitHub account. For more information, see "[Checking for existing SSH keys](https://docs.github.com/authentication/connecting-to-github-with-ssh/checking-for-existing-ssh-keys)."',
                }),
            })
            .openapi({ required: ['key'] }),
          examples: {
            default: {
              value: {
                key: '2Sg8iYjAxxmI2LvUXpJjkYrMxURPc8r+dB7TJyvv1234',
                title: 'ssh-rsa AAAAB3NzaC1yc2EAAA',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: SshSigningKeySchema,
          examples: { default: SshSigningKeyExample },
        },
      },
    },
    304: NotModifiedResponse,
    401: RequiresAuthenticationResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

