export const postUsersUserIdProjectsV2ProjectNumberViewsRoute = createRoute({
  method: 'post',
  path: '/users/{user_id}/projectsV2/{project_number}/views',
  tags: ['projects'],
  summary: 'Create a view for a user-owned project',
  description:
    'Create a new view in a user-owned project. Views allow you to customize how items in a project are displayed and filtered.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/projects/views#create-a-view-for-a-user-owned-project',
  },
  operationId: 'projects/create-view-for-user',
  request: {
    params: z.object({ user_id: UserIdParamsSchema, project_number: ProjectNumberParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .strictObject({
              name: z
                .string()
                .openapi({ description: 'The name of the view.', example: 'Sprint Board' }),
              layout: z
                .enum(['table', 'board', 'roadmap'])
                .openapi({ description: 'The layout of the view.', example: 'board' }),
              filter: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The filter query for the view. See [Filtering projects](https://docs.github.com/issues/planning-and-tracking-with-projects/customizing-views-in-your-project/filtering-projects) for more information.',
                  example: 'is:issue is:open',
                }),
              visible_fields: z
                .array(z.int())
                .exactOptional()
                .openapi({
                  description:
                    '`visible_fields` is not applicable to `roadmap` layout views.\nFor `table` and `board` layouts, this represents the field IDs that should be visible in the view. If not provided, the default visible fields will be used.',
                  example: [123, 456, 789],
                }),
              sort_by: z
                .array(z.array(z.xor([z.int(), z.string()])).length(2))
                .exactOptional()
                .openapi({
                  description:
                    'Sorting configuration for the view. Each element is a two-element array of `[field_id, direction]` where `direction` is `"asc"` or `"desc"`. Supports multiple sort criteria applied in order.',
                  example: [
                    [123, 'asc'],
                    [456, 'desc'],
                  ],
                }),
              group_by: z
                .array(z.int())
                .max(1)
                .exactOptional()
                .openapi({
                  description:
                    'The field IDs to group items by (horizontal grouping). Supports a single field. The field must support grouping; fields such as `Title`, `Reviewers`, `Linked pull requests`, `Sub-issues progress`, `Tracked by`, and `Tracks` cannot be grouped on.',
                  example: [123],
                }),
              vertical_group_by: z
                .array(z.int())
                .max(1)
                .exactOptional()
                .openapi({
                  description:
                    'The field IDs to use as columns in `board` layout (vertical grouping). Supports a single field. The field must support grouping; fields such as `Title`, `Reviewers`, `Linked pull requests`, `Sub-issues progress`, `Tracked by`, and `Tracks` cannot be grouped on.',
                  example: [456],
                }),
            })
            .openapi({ required: ['name', 'layout'] }),
          examples: {
            table_view: {
              summary: 'Create a table view',
              value: {
                name: 'All Issues',
                layout: 'table',
                filter: 'is:issue',
                visible_fields: [123, 456, 789],
              },
            },
            board_view: {
              summary: 'Create a board view with filter',
              value: {
                name: 'Sprint Board',
                layout: 'board',
                filter: 'is:issue is:open label:sprint',
                visible_fields: [123, 456, 789],
              },
            },
            roadmap_view: {
              summary: 'Create a roadmap view',
              value: { name: 'Product Roadmap', layout: 'roadmap' },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response for creating a view in a user-owned project.',
      content: {
        'application/json': {
          schema: ProjectsV2ViewSchema,
          examples: {
            table_view: {
              summary: 'Response for creating a table view',
              value: { $ref: '#/components/examples/projects-v2-view' },
            },
            board_view: {
              summary: 'Response for creating a board view with filter',
              value: { $ref: '#/components/examples/projects-v2-view' },
            },
            roadmap_view: {
              summary: 'Response for creating a roadmap view',
              value: { $ref: '#/components/examples/projects-v2-view' },
            },
          },
        },
      },
    },
    304: NotModifiedResponse,
    401: RequiresAuthenticationResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: ValidationFailedResponse,
    503: {
      description: 'Service unavailable',
      content: { 'application/json': { schema: BasicErrorSchema } },
    },
  },
})

export const getUsersUsernameRoute = createRoute({
  method: 'get',
  path: '/users/{username}',
  tags: ['users'],
  summary: 'Get a user',
  description:
    'Provides publicly available information about someone with a GitHub account.\n\nIf the specified user has a [private profile](https://docs.github.com/account-and-profile/concepts/personal-profile#private-profiles), the `followers` and `following` values are `0` unless the request is authenticated as that user. A request authenticated as the specified user returns the actual values even if the token has no OAuth scopes.\n\nThe `events_url` value is a URI template. Replace `{/privacy}` with `/public` to retrieve only public events. Omit it to retrieve public events and, when authenticated as the user, private events. For more information, see "[List events for the authenticated user](https://docs.github.com/rest/activity/events#list-events-for-the-authenticated-user)."\n\nIf you are requesting information about an [Enterprise Managed User](https://docs.github.com/enterprise-cloud@latest/admin/managing-iam/understanding-iam-for-enterprises/about-enterprise-managed-users), or a GitHub App bot that is installed in an organization that uses Enterprise Managed Users, your requests must be authenticated as a user or GitHub App that has access to the organization to view that account\'s information. If you are not authorized, the request will return a `404 Not Found` status.\n\nThe `email` key in the following response is the publicly visible email address from your GitHub [profile page](https://github.com/settings/profile). When setting up your profile, you can select a primary email address to be public which provides an email entry for this endpoint. If you do not set a public email address for `email`, then it will have a value of `null`. You only see publicly visible email addresses when authenticated with GitHub. For more information, see [Authentication](https://docs.github.com/rest/guides/getting-started-with-the-rest-api#authentication).\n\nThe Emails API enables you to list all of your email addresses, and toggle a primary email to be visible publicly. For more information, see [Emails API](https://docs.github.com/rest/users/emails).',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/users/users#get-a-user',
  },
  operationId: 'users/get-by-username',
  request: { params: z.object({ username: UsernameParamsSchema }) },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z
            .xor([PrivateUserSchema, PublicUserSchema])
            .openapi({
              discriminator: {
                propertyName: 'user_view_type',
                mapping: {
                  public: '#/components/schemas/public-user',
                  private: '#/components/schemas/private-user',
                },
              },
            }),
          examples: {
            'default-response': PublicUserDefaultResponseExample,
            'response-with-git-hub-plan-information':
              PublicUserResponseWithGitHubPlanInformationExample,
          },
        },
      },
    },
    404: NotFoundResponse,
  },
})

export const postUsersUsernameAttestationsBulkListRoute = createRoute({
  method: 'post',
  path: '/users/{username}/attestations/bulk-list',
  tags: ['users'],
  summary: 'List attestations by bulk subject digests',
  description:
    "List a collection of artifact attestations associated with any entry in a list of subject digests owned by a user.\n\nThe collection of attestations returned by this endpoint is filtered according to the authenticated user's permissions; if the authenticated user cannot read a repository, the attestations associated with that repository will not be included in the response. In addition, when using a fine-grained access token the `attestations:read` permission is required.\n\n**Please note:** in order to offer meaningful security benefits, an attestation's signature and timestamps **must** be cryptographically verified, and the identity of the attestation signer **must** be validated. Attestations can be verified using the [GitHub CLI `attestation verify` command](https://cli.github.com/manual/gh_attestation_verify). For more information, see [our guide on how to use artifact attestations to establish a build's provenance](https://docs.github.com/actions/security-guides/using-artifact-attestations-to-establish-provenance-for-builds).",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/users/attestations#list-attestations-by-bulk-subject-digests',
  },
  operationId: 'users/list-attestations-bulk',
  request: {
    query: z.object({
      per_page: PerPageParamsSchema,
      before: PaginationBeforeParamsSchema,
      after: PaginationAfterParamsSchema,
    }),
    params: z.object({ username: UsernameParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              subject_digests: z
                .array(z.string())
                .min(1)
                .max(1024)
                .openapi({ description: 'List of subject digests to fetch attestations for.' }),
              predicate_type: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Optional filter for fetching attestations with a given predicate type.\nThis option accepts `provenance`, `sbom`, `release`, or freeform text\nfor custom predicate types.',
                }),
            })
            .openapi({ required: ['subject_digests'] }),
          examples: {
            default: BulkSubjectDigestBodyExample,
            withPredicateType: BulkSubjectDigestBodyWithPredicateTypeExample,
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': {
          schema: z
            .object({
              attestations_subject_digests: z
                .record(
                  z.string(),
                  z
                    .array(
                      z
                        .object({
                          bundle: z
                            .object({
                              mediaType: z.string().exactOptional(),
                              verificationMaterial: z.looseObject({}).exactOptional(),
                              dsseEnvelope: z.looseObject({}).exactOptional(),
                            })
                            .exactOptional()
                            .openapi({
                              description: 'The bundle of the attestation.',
                              required: [],
                            }),
                          repository_id: z.int().exactOptional(),
                          bundle_url: z.string().exactOptional(),
                        })
                        .openapi({ required: [] }),
                    )
                    .nullable(),
                )
                .exactOptional()
                .openapi({ description: 'Mapping of subject digest to bundles.' }),
              page_info: z
                .object({
                  has_next: z
                    .boolean()
                    .exactOptional()
                    .openapi({ description: 'Indicates whether there is a next page.' }),
                  has_previous: z
                    .boolean()
                    .exactOptional()
                    .openapi({ description: 'Indicates whether there is a previous page.' }),
                  next: z
                    .string()
                    .exactOptional()
                    .openapi({ description: 'The cursor to the next page.' }),
                  previous: z
                    .string()
                    .exactOptional()
                    .openapi({ description: 'The cursor to the previous page.' }),
                })
                .exactOptional()
                .openapi({ description: 'Information about the current page.', required: [] }),
            })
            .openapi({ required: [] }),
          examples: { default: ListAttestationsBulkExample },
        },
      },
    },
  },
})

