export const deleteUsersUsernameAttestationsAttestationIdRoute = createRoute({
  method: 'delete',
  path: '/users/{username}/attestations/{attestation_id}',
  tags: ['users'],
  summary: 'Delete attestations by ID',
  description:
    'Delete an artifact attestation by unique ID that is associated with a repository owned by a user.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/users/attestations#delete-attestations-by-id',
  },
  operationId: 'users/delete-attestations-by-id',
  request: {
    params: z.object({
      username: UsernameParamsSchema,
      attestation_id: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'attestation_id',
            description: 'Attestation ID',
            in: 'path',
            required: true,
            schema: { type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'Response' },
    204: { description: 'Response' },
    403: ForbiddenResponse,
    404: NotFoundResponse,
  },
})

