export const getUsersUsernameHovercardRoute = createRoute({
  method: 'get',
  path: '/users/{username}/hovercard',
  tags: ['users'],
  summary: 'Get contextual information for a user',
  description:
    "Provides hovercard information. You can find out more about someone in relation to their pull requests, issues, repositories, and organizations.\n\n  The `subject_type` and `subject_id` parameters provide context for the person's hovercard, which returns more information than without the parameters. For example, if you wanted to find out more about `octocat` who owns the `Spoon-Knife` repository, you would use a `subject_type` value of `repository` and a `subject_id` value of `1300192` (the ID of the `Spoon-Knife` repository).\n\nOAuth app tokens and personal access tokens (classic) need the `repo` scope to use this endpoint.",
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/users/users#get-contextual-information-for-a-user',
  },
  operationId: 'users/get-context-for-user',
  request: {
    params: z.object({ username: UsernameParamsSchema }),
    query: z.object({
      subject_type: z
        .enum(['organization', 'repository', 'issue', 'pull_request'])
        .exactOptional()
        .openapi({
          param: {
            name: 'subject_type',
            description:
              "Identifies which additional information you'd like to receive about the person's hovercard. Can be `organization`, `repository`, `issue`, `pull_request`. **Required** when using `subject_id`.",
            in: 'query',
            required: false,
            schema: {
              type: 'string',
              enum: ['organization', 'repository', 'issue', 'pull_request'],
            },
          },
        }),
      subject_id: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'subject_id',
            description:
              'Uses the ID for the `subject_type` you specified. **Required** when using `subject_type`.',
            in: 'query',
            required: false,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Response',
      content: {
        'application/json': { schema: HovercardSchema, examples: { default: HovercardExample } },
      },
    },
    404: NotFoundResponse,
    422: ValidationFailedResponse,
  },
})

