export const postUsersUsernameProjectsV2ProjectNumberItemsRoute = createRoute({
  method: 'post',
  path: '/users/{username}/projectsV2/{project_number}/items',
  tags: ['projects'],
  summary: 'Add item to user owned project',
  description: 'Add an issue or pull request item to the specified user owned project.',
  externalDocs: {
    description: 'API method documentation',
    url: 'https://docs.github.com/rest/projects/items#add-item-to-user-owned-project',
  },
  operationId: 'projects/add-item-for-user',
  request: {
    params: z.object({ username: UsernameParamsSchema, project_number: ProjectNumberParamsSchema }),
    body: {
      description:
        'Details of the item to add to the project. You can specify either the unique ID or the repository owner, name, and issue/PR number.',
      content: {
        'application/json': {
          schema: z
            .xor([
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'id')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['id'] }),
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'owner')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                    if (!Object.hasOwn(val, 'repo')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                    if (!Object.hasOwn(val, 'number')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['owner', 'repo', 'number'] }),
            ])
            .openapi({ required: ['type'] }),
          examples: {
            issue_with_id: {
              summary: 'Add an issue using its unique ID',
              value: { type: 'Issue', id: 3 },
            },
            pull_request_with_id: {
              summary: 'Add a pull request using its unique ID',
              value: { type: 'PullRequest', id: 3 },
            },
            issue_with_nwo: {
              summary: 'Add an issue using repository owner, name, and issue number',
              value: { type: 'Issue', owner: 'octocat', repo: 'hello-world', number: 42 },
            },
            pull_request_with_nwo: {
              summary: 'Add a pull request using repository owner, name, and PR number',
              value: { type: 'PullRequest', owner: 'octocat', repo: 'hello-world', number: 123 },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Response',
      content: {
        'application/json': {
          schema: ProjectsV2ItemSimpleSchema,
          examples: {
            issue_with_id: {
              summary: 'Response for adding an issue using its unique ID',
              value: { $ref: '#/components/examples/projects-v2-item-simple' },
            },
            pull_request_with_id: {
              summary: 'Response for adding a pull request using its unique ID',
              value: { $ref: '#/components/examples/projects-v2-item-simple' },
            },
            issue_with_nwo: {
              summary:
                'Response for adding an issue using repository owner, name, and issue number',
              value: { $ref: '#/components/examples/projects-v2-item-simple' },
            },
            pull_request_with_nwo: {
              summary:
                'Response for adding a pull request using repository owner, name, and PR number',
              value: { $ref: '#/components/examples/projects-v2-item-simple' },
            },
          },
        },
      },
    },
    304: NotModifiedResponse,
    401: RequiresAuthenticationResponse,
    403: ForbiddenResponse,
  },
})

